window.H=window.H||{};H[34]={"34회-1차-017":{"한줄":"토지수용만 직접개입이고, 종합부동산세·담보인정비율·개발부담금은 간접개입 수단이다.","근거":[{"이론":"정부 개입의 근거와 수단","내용":"시장실패(공공재, 외부효과, 정보의 비대칭, 독점 등)와 형평성 문제가 개입 근거이고, 수단은 직접(수용, 공급, 규제)과 간접(조세, 보조금, 금융)으로 나뉜다."}],"선지":[{"번호":1,"판정":"옳음","설명":"투기, 저소득층 주거문제, 자원배분의 비효율은 개입 근거다."},{"번호":2,"판정":"옳음","설명":"공공재, 외부효과, 정보의 비대칭은 시장실패의 대표 원인이다."},{"번호":3,"판정":"옳음","설명":"토지비축은 정부가 토지를 사서 쌓아 두는 직접개입이다."},{"번호":4,"판정":"틀림","설명":"종합부동산세(조세), 담보인정비율(금융), 개발부담금(부담금)은 간접개입이다."},{"번호":5,"판정":"옳음","설명":"분양가 규제는 수익성을 낮춰 민간주택 공급을 줄이는 부작용이 있다."}],"개념":[{"종류":"표","제목":"시장실패 원인과 정부 대응","머리":["원인","내용","대응 예"],"행":[["공공재","비배제성·비경합성으로 무임승차 발생","정부 직접 공급"],["외부효과","제3자에게 대가 없이 이익·손해 전가","용도지역·지구제, 부담금, 보조금"],["정보의 비대칭","거래 당사자 간 정보 격차","공시제도, 자격사 제도"],["독점","시장지배력으로 가격 왜곡","가격 규제, 경쟁 촉진"]]}],"함정":"‘토지수용, 종합부동산세, 담보인정비율, 개발부담금’을 한 묶음으로 보고 모두 규제로 처리하는 오답이다. 수용만 직접이다."},"34회-1차-046":{"한줄":"추인은 소급효가 있지만 제3자의 권리를 해하지 못하므로, 추인 전에 甲에게서 등기를 받은 丁은 유효하게 소유권을 취득하고 1번이 옳다.","근거":[{"법령":"민법","조문":"제133조","원문":"제133조(추인의 효력) 추인은 다른 의사표시가 없는 때에는 계약시에 소급하여 그 효력이 생긴다. 그러나 제삼자의 권리를 해하지 못한다."},{"법령":"민법","조문":"제134조","원문":"제134조(상대방의 철회권) 대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제135조","원문":"제135조(상대방에 대한 무권대리인의 책임) ① 다른 자의 대리인으로서 계약을 맺은 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 받지 못한 경우에는 그는 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다. ② 대리인으로서 계약을 맺은 자에게 대리권이 없다는 사실을 상대방이 알았거나 알 수 있었을 때 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때에는 제1항을 적용하지 아니한다."},{"법령":"민법","조문":"제1005조","원문":"제1005조(상속과 포괄적 권리의무의 승계) 상속인은 상속개시된 때로부터 피상속인의 재산에 관한 포괄적 권리의무를 승계한다. 그러나 피상속인의 일신에 전속한 것은 그러하지 아니하다. <개정 1990.1.13>"},{"판례":"대법원 1994. 9. 27. 선고 94다20617 판결","요지":"무권대리인이 본인을 단독상속한 경우 본인의 지위에서 추인을 거절하는 것은 금반언과 신의칙에 반한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"추인은 계약 시로 소급하지만 제3자의 권리를 해하지 못한다(제133조 단서). 추인 전 甲에게서 이전등기를 받은 丁의 권리가 우선한다."},{"번호":2,"판정":"틀림","설명":"무권대리인이 본인을 단독상속하면 본인 지위에서 추인을 거절하는 것은 신의칙에 반한다(94다20617)."},{"번호":3,"판정":"틀림","설명":"甲의 단독상속인 戊는 甲의 지위를 포괄승계하므로(제1005조) 본인으로서 추인할 수 있다."},{"번호":4,"판정":"틀림","설명":"철회권은 계약 당시 대리권 없음을 몰랐던 선의의 상대방에게만 있다(제134조 단서)."},{"번호":5,"판정":"틀림","설명":"무권대리인이 제한능력자이면 제135조 제1항이 적용되지 않는다(제135조 제2항). 乙이 미성년자이면 丙은 乙에게 손해배상을 청구하지 못한다."}],"개념":[{"종류":"표","제목":"추인의 효과와 한계","머리":["쟁점","내용","근거"],"행":[["소급효","다른 의사표시가 없으면 계약 시로 소급","제133조 본문"],["제3자 보호","추인으로 제3자의 권리를 해하지 못함","제133조 단서"],["상대방","추인·거절은 상대방에게 해야 대항 가능","제132조"],["일부 추인","상대방 동의 없으면 무효","81다카549"],["본인 상속과 추인 거절","무권대리인이 본인을 단독상속하면 거절이 신의칙 위반","94다20617"]]},{"종류":"표","제목":"제135조 무권대리인의 책임 요건","머리":["구분","내용"],"행":[["성립요건","대리권을 증명하지 못함 + 본인의 추인 없음"],["책임 내용","상대방의 선택에 따라 계약 이행 또는 손해배상"],["배제 사유 1","상대방이 대리권 없음을 알았거나 알 수 있었던 때"],["배제 사유 2","무권대리인이 제한능력자인 때"]]}],"함정":"정답률이 32%에 그친 문항이다. 추인의 소급효를 절대적으로 읽어 丁의 소유권이 사라진다고 판단한 수험생이 많다. 소급효는 제3자의 권리를 해하지 못한다. 4번은 상대방이 악의여도 철회할 수 있다고 쓴 선지로, 철회권은 선의자만 가진다."},"34회-1차-063":{"한줄":"제320조는 임의규정이라 유치권 발생을 배제하는 특약은 유효하므로 2번이 틀리다.","근거":[{"법령":"민법","조문":"제322조제1항","원문":"제322조(경매, 간이변제충당) ①유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있다."},{"법령":"민법","조문":"제320조제1항","원문":"제320조(유치권의 내용) ①타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우에는 변제를 받을 때까지 그 물건 또는 유가증권을 유치할 권리가 있다."},{"법령":"민법","조문":"제324조제1항","원문":"제324조(유치권자의 선관의무) ①유치권자는 선량한 관리자의 주의로 유치물을 점유하여야 한다."},{"판례":"대법원 판례(유치권 배제 특약)","요지":"유치권 발생을 배제하는 특약은 유효하다. 특약이 있으면 당사자와 그 특약을 아는 승계인에게 유치권을 주장할 수 없다."},{"판례":"대법원 2008. 5. 30.자 2007마98 결정","요지":"독립한 건물이 되지 못한 정착물만 설치한 채 공사가 중단된 때 수급인은 그 토지에 유치권을 행사할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"유치권자는 채권의 변제를 받기 위해 유치물을 경매할 수 있다(제322조 제1항)."},{"번호":2,"판정":"틀림","설명":"유치권은 법정담보물권이지만 임의규정이어서 발생을 배제하는 특약이 유효하다(제320조에 강행규정 표시가 없다)."},{"번호":3,"판정":"옳음","설명":"정착물은 독립한 건물이 아니고 토지도 공사대금과 견련성이 없어 유치권 대상이 아니다(2007마98)."},{"번호":4,"판정":"옳음","설명":"채권이 변제기에 있어야 유치할 수 있다(제320조 제1항)."},{"번호":5,"판정":"옳음","설명":"유치권자의 선관주의의무다(제324조 제1항)."}],"개념":[{"종류":"표","제목":"유치권자의 권리와 의무","머리":["구분","내용","근거"],"행":[["불가분성","채권 전부를 변제받을 때까지 유치물 전부에 행사","제321조"],["경매·간이변제충당","경매 가능. 정당한 이유가 있으면 감정인 평가로 직접 변제충당을 법원에 청구(미리 채무자에게 통지)","제322조"],["과실수취","과실을 수취해 다른 채권보다 먼저 변제에 충당. 금전이 아닌 과실은 경매","제323조"],["선관의무","선관주의로 점유. 채무자 승낙 없이 사용·대여·담보제공 불가(보존 사용은 예외)","제324조"],["상환청구","필요비는 즉시, 유익비는 가액 증가가 현존할 때 소유자 선택에 따라","제325조"]]},{"종류":"표","제목":"유치권의 소멸","머리":["사유","내용","근거"],"행":[["점유 상실","점유를 잃으면 소멸","제328조"],["타담보 제공","채무자가 상당한 담보를 제공하고 소멸 청구","제327조"],["의무 위반","선관의무·사용금지 위반 시 채무자가 소멸 청구","제324조 제3항"],["시효","유치권 행사는 피담보채권 시효진행에 영향 없음","제326조"]]}],"함정":"유치권이 법정담보물권이라는 이유로 배제 특약도 무효라고 추측하기 쉽다. 법정이라는 말은 발생 근거가 법률이라는 뜻이고, 당사자가 미리 포기하는 것을 막지 않는다. 임차인 지위에서 포기 특약을 하는 상가·주택 계약이 실제로 많다. 4번은 변제기 도래가 성립요건이라는 점으로 풀린다."},"34회-1차-070":{"한줄":"매매계약에 관한 비용은 당사자 쌍방이 균분하여 부담하므로 4번이 틀리다.","근거":[{"법령":"민법","조문":"제566조","원문":"제566조(매매계약의 비용의 부담) 매매계약에 관한 비용은 당사자 쌍방이 균분하여 부담한다."},{"법령":"민법","조문":"제563조","원문":"제563조(매매의 의의) 매매는 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제569조","원문":"제569조(타인의 권리의 매매) 매매의 목적이 된 권리가 타인에게 속한 경우에는 매도인은 그 권리를 취득하여 매수인에게 이전하여야 한다."},{"법령":"민법","조문":"제567조","원문":"제567조(유상계약에의 준용) 본절의 규정은 매매 이외의 유상계약에 준용한다. 그러나 그 계약의 성질이 이를 허용하지 아니하는 때에는 그러하지 아니하다. 제2관 매매의 효력"},{"법령":"민법","조문":"제580조제2항","원문":"제580조(매도인의 하자담보책임) ②전항의 규정은 경매의 경우에 적용하지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"합의만으로 성립하고 방식이 필요 없다(제563조)."},{"번호":2,"판정":"옳음","설명":"타인의 권리도 매매할 수 있다. 매도인은 그 권리를 취득해 매수인에게 이전할 의무를 진다(제569조)."},{"번호":3,"판정":"옳음","설명":"교환은 유상계약이므로 매매 규정을 준용한다(제567조)."},{"번호":4,"판정":"틀림","설명":"매매계약에 관한 비용(계약서 작성비, 측량비 등)은 쌍방이 균분 부담한다(제566조)."},{"번호":5,"판정":"옳음","설명":"경매에는 하자담보책임이 적용되지 않는다(제580조 제2항)."}],"개념":[{"종류":"흐름","제목":"계약금과 해약금","단계":[{"이름":"계약금 교부","설명":"계약 당시 금전 기타 물건을 계약금·보증금 등의 명목으로 교부(제565조 제1항)"},{"이름":"해약금 추정","설명":"다른 약정이 없으면 해약금으로 추정"},{"이름":"해제권 행사","설명":"당사자 일방이 이행에 착수할 때까지 교부자는 포기, 수령자는 배액 상환으로 해제"},{"이름":"효과","설명":"제551조 적용 없음. 손해배상 청구 불가(제565조 제2항)"}]},{"종류":"표","제목":"매매의 효력 규정","머리":["내용","근거"],"행":[["쌍방 의무(권리 이전·대금 지급)는 특약·관습이 없으면 동시이행","제568조"],["타인 권리의 매매: 매도인이 취득해 이전","제569조"],["매매계약 비용은 쌍방이 균분 부담","제566조"],["인도 전 목적물의 과실은 매도인에게 속하고, 매수인은 인도받은 날부터 대금 이자 지급(대금 기한이 있으면 제외)","제587조"],["권리주장자가 있어 권리를 잃을 염려가 있으면 매수인은 위험 한도에서 대금 지급 거절","제588조"],["매매 규정은 유상계약에 준용","제567조"]]}],"함정":"비용을 매수인이 전부 낸다고 외운 경우가 있다. 등기비용 등을 실제로는 매수인이 부담하는 관행이 있지만 법 규정은 균분이다. 5번은 경매에서 물건의 하자만 제외된다는 점이 중요하다. 권리의 하자는 경매에도 담보책임이 있다."},"34회-2차-005":{"한줄":"공인중개사 비율 3분의 1은 대표자를 제외한 임원·사원을 기준으로 센다. 대표자를 포함한다는 2번이 틀렸다.","근거":[{"법령":"공인중개사법 시행령","조문":"제13조제1항제2호","원문":"2. 법인이 중개사무소를 개설하려는 경우\n가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것\n다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것\n라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것"}],"선지":[{"번호":1,"판정":"-","설명":"대표자는 반드시 공인중개사여야 한다(영 제13조제1항제2호다목)."},{"번호":2,"판정":"-","설명":"3분의 1 이상 기준은 \"대표자를 제외한\" 임원·사원이다(같은 목)."},{"번호":3,"판정":"-","설명":"상법상 회사의 자본금은 5천만원 이상이다(같은 호 가목)."},{"번호":4,"판정":"-","설명":"대표자와 임원·사원 전원이 실무교육을 받아야 한다(같은 호 라목)."},{"번호":5,"판정":"-","설명":"분사무소를 설치하려는 경우에는 그 책임자도 실무교육을 받아야 한다(같은 호 라목)."}],"개념":[{"종류":"표","제목":"개설등록 기준: 공인중개사와 법인","머리":["구분","공인중개사","법인"],"행":[["실무교육","본인(신청일 전 1년 이내)","대표자·임원·사원 전원, 분사무소를 둘 때는 그 책임자까지"],["자본금·형태","요건 없음","상법상 회사 또는 협동조합(사회적협동조합 제외), 자본금 5천만원 이상"],["설립 목적","요건 없음","법 제14조에 규정된 업무만 영위할 목적으로 설립"],["공인중개사 요건","본인이 공인중개사","대표자는 공인중개사, 대표자를 제외한 임원·사원의 3분의 1 이상도 공인중개사"],["사무소","건축물대장에 기재된 건물(가설건축물대장 제외)에 소유·전세·임대차·사용대차 등으로 사용권 확보","같음"],["예외","다른 법률에 따라 부동산중개업을 할 수 있는 경우에는 위 기준을 적용하지 않음","같음"]]},{"종류":"표","제목":"등록관청이 개설등록을 해 주지 않는 경우","머리":["번호","사유","근거"],"행":[["1","공인중개사 또는 법인이 아닌 자의 신청","영 제13조제2항제1호"],["2","법 제10조제1항 결격사유에 해당하는 신청인","제2호"],["3","개설등록 기준에 적합하지 않음","제3호"],["4","그 밖에 이 법 또는 다른 법령에 따른 제한에 위반","제4호"]]}],"함정":"\"대표자를 포함하여 3분의 1\"로 읽으면 대표자 1명만 공인중개사여도 되는 구조가 된다. 실제로는 대표자가 공인중개사인 것과 별도로, 나머지 임원·사원의 3분의 1 이상이 공인중개사여야 한다."},"34회-2차-010":{"한줄":"소속공인중개사도 등록 인장을 변경하면 변경일부터 7일 이내에 등록해야 하므로 \"10일 이내\"라는 5번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제9조제1항·제2항·제3항·제6항","원문":"①개업공인중개사 및 소속공인중개사는 법 제16조제1항의 규정에 따라 업무를 개시하기 전에 중개행위에 사용할 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다.\n②제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다.\n그 크기가 가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내인 인장이어야 하며\n다만, 분사무소에서 사용할 인장의 경우에는 「상업등기규칙」 제35조제3항에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다.\n⑥ 제1항에 따른 인장의 등록은 다음 각 호의 신청이나 신고와 같이 할 수 있다.\n2. 제8조에 따른 소속공인중개사ㆍ중개보조원에 대한 고용 신고"}],"선지":[{"번호":1,"판정":"옳음","설명":"개설등록 후라도 업무를 개시하기 전이면 인장을 등록할 수 있다(규칙 제9조제1항)."},{"번호":2,"판정":"옳음","설명":"소속공인중개사의 인장등록은 고용 신고와 같이 할 수 있다(규칙 제9조제6항제2호)."},{"번호":3,"판정":"옳음","설명":"분사무소 사용 인장은 대표자가 보증하는 인장을 등록할 수 있다(규칙 제9조제3항 단서)."},{"번호":4,"판정":"옳음","설명":"등록할 인장의 크기는 가로·세로 각각 7밀리미터 이상 30밀리미터 이내다(규칙 제9조제3항)."},{"번호":5,"판정":"틀림","설명":"인장을 변경한 경우 개업공인중개사와 소속공인중개사 모두 변경일부터 7일 이내에 등록한다(규칙 제9조제2항)."}],"개념":[{"종류":"흐름","제목":"소속공인중개사 고용 신고와 인장등록","단계":[{"이름":"실무교육","설명":"고용 신고일 전 1년 이내에 시·도지사가 실시하는 실무교육을 받는다(법 제34조제2항). 교육시간은 45시간이다(영 제28조제1항)."},{"이름":"고용 신고","설명":"개업공인중개사가 업무개시 전까지 등록관청에 고용 신고를 한다(법 제15조제1항, 규칙 제8조제1항). 인장등록을 같이 할 수 있다(규칙 제9조제6항)."},{"이름":"등록관청 확인","설명":"자격증을 발급한 시·도지사에게 공인중개사 자격 확인을 요청하고, 결격사유와 교육 수료 여부를 확인한다(규칙 제8조제2항·제3항)."},{"이름":"인장 변경","설명":"등록한 인장을 바꾸면 변경일부터 7일 이내에 변경 인장을 등록한다(규칙 제9조제2항)."},{"이름":"고용 종료","설명":"고용관계가 끝난 날부터 10일 이내에 종료 신고를 한다(규칙 제8조제4항)."}]},{"종류":"표","제목":"신고·등록·반납 기한 모음","머리":["사항","기한","근거"],"행":[["등록 인장 변경 등록","변경일부터 7일 이내","규칙 제9조제2항"],["중개사무소 이전신고","이전한 날부터 10일 이내","법 제20조제1항"],["고용관계 종료 신고","종료된 날부터 10일 이내","규칙 제8조제4항"],["자격증 반납","자격취소처분을 받은 날부터 7일 이내","규칙 제21조"],["등록증 반납","등록취소처분을 받은 날부터 7일 이내","규칙 제24조제1항"],["보증보험금·공제금·공탁금 지급 후 보전","15일 이내","영 제26조제2항"],["자격취소처분 통보(시·도지사 → 국토교통부장관 등)","5일 이내","영 제29조제3항"],["등록사항 등 협회 통보","매월 모아 다음 달 10일까지","규칙 제6조"]]}],"함정":"5번의 10일은 이전신고·고용 종료 신고의 기한이다. 인장 변경 등록은 개업공인중개사든 소속공인중개사든 7일이다."},"34회-2차-014":{"한줄":"근저당권이 설정된 경우 채권최고액을 확인·설명하면 되고 실제 피담보채무액까지 조사·확인할 의무는 없다는 것이 판례이므로 2번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제25조제1항·제3항","원문":"개업공인중개사는 중개를 의뢰받은 경우에는 중개가 완성되기 전에 다음 각 호의 사항을 확인하여 이를 해당 중개대상물에 관한 권리를 취득하고자 하는 중개의뢰인에게 성실ㆍ정확하게 설명하고, 토지대장 등본 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등본 등 설명의 근거자료를 제시하여야 한다.\n③개업공인중개사는 중개가 완성되어 거래계약서를 작성하는 때에는 제1항에 따른 확인ㆍ설명사항을 대통령령으로 정하는 바에 따라 서면으로 작성하여 거래당사자에게 교부하고 대통령령으로 정하는 기간 동안 그 원본, 사본 또는 전자문서를 보존하여야 한다."},{"법령":"공인중개사법","조문":"제51조제2항제1호의6","원문":"1의6. 제25조제1항을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 자"},{"판례":"대법원 판례(근저당권이 설정된 중개대상물)","요지":"중개대상물에 근저당권이 설정되어 있으면 개업공인중개사는 채권최고액을 확인·설명하면 충분하고, 실제의 피담보채무액을 조사·확인하여 설명할 의무까지 지지는 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"확인·설명서는 중개가 완성되어 거래계약서를 작성하는 때에 작성해 교부한다(법 제25조제3항)."},{"번호":2,"판정":"틀림","설명":"근저당권은 채권최고액의 확인·설명으로 족하고, 실제 피담보채무액의 조사·확인 의무는 없다는 것이 판례다."},{"번호":3,"판정":"옳음","설명":"중개대상물의 범위 밖 물건·권리·지위를 중개하더라도 선량한 관리자의 주의로 권리관계 등을 조사·확인해 설명할 의무가 있다는 것이 판례다."},{"번호":4,"판정":"옳음","설명":"조사·확인 의무가 없는 사항이라도 의뢰인의 결정에 중요한 사항이면 그릇된 정보를 제공해서는 안 된다는 것이 판례다."},{"번호":5,"판정":"옳음","설명":"성실·정확한 확인·설명을 하지 않거나 근거자료를 제시하지 않으면 500만원 이하 과태료 대상이다(법 제51조제2항제1호의6)."}],"개념":[{"종류":"흐름","제목":"확인·설명 절차","단계":[{"이름":"중개 의뢰","설명":"개업공인중개사가 중개를 의뢰받는다. 필요하면 매도·임대의뢰인 등에게 중개대상물의 상태에 관한 자료를 요구할 수 있다(법 제25조제2항)."},{"이름":"확인·설명","설명":"중개가 완성되기 전에 상태·입지·권리관계, 거래·이용 제한 등을 확인해 권리를 취득하려는 의뢰인에게 설명하고 근거자료를 제시한다(법 제25조제1항)."},{"이름":"자료 요구에 불응한 경우","설명":"불응한 사실을 매수·임차의뢰인 등에게 설명하고 확인·설명서에 적는다(영 제21조제2항)."},{"이름":"확인·설명서 교부","설명":"거래계약서를 작성하는 때에 국토교통부령 서식으로 작성해 거래당사자에게 교부하고 3년간 보존한다(법 제25조제3항, 영 제21조제3항·제4항)."},{"이름":"서명 및 날인","설명":"개업공인중개사(법인은 대표자, 분사무소는 책임자)와 해당 중개행위를 한 소속공인중개사가 함께 서명 및 날인한다(법 제25조제4항)."}]},{"종류":"표","제목":"확인·설명 위반의 제재","머리":["위반","개업공인중개사","소속공인중개사"],"행":[["성실·정확한 확인·설명 안 함, 근거자료 미제시(법 제25조제1항)","500만원 이하 과태료(법 제51조제2항제1호의6)","자격정지 가능(법 제36조제1항제3호)"],["확인·설명서 미교부·미보존(법 제25조제3항)","업무정지 가능(법 제39조제1항제6호)","-"],["확인·설명서에 서명 및 날인 안 함(법 제25조제4항)","업무정지 가능(법 제39조제1항제7호)","자격정지 가능(법 제36조제1항제4호)"],["손해를 발생시킨 경우","손해배상책임(법 제30조제1항)","-"]]}],"함정":"2번은 \"근저당권이 있으면 실제 채무액까지 확인해 줘야 안전하다\"는 상식에서 나오는 오답이다. 의무 범위는 채권최고액까지다. 5번의 과태료는 업무정지가 아니라 500만원 이하 과태료라는 점도 구분해야 한다.","개정":"법 제25조제1항에는 2025.8.14 개정 이력이 붙어 있고, 현행 설명 근거자료는 토지대장 등본 또는 부동산종합증명서, 등기사항증명서, 신탁원부, 건축물대장 등본 등으로 적혀 있다. 이 문항의 정답에는 영향이 없다."},"34회-2차-015":{"한줄":"보증 설정 없이 업무를 개시하면 등록취소 사유(법 제38조제2항제8호)이면서 업무정지 사유(법 제39조제1항제11호)이므로 4번이 틀렸다.","근거":[{"법령":"공인중개사법","조문":"제30조제2항·제3항","원문":"②개업공인중개사는 자기의 중개사무소를 다른 사람의 중개행위의 장소로 제공함으로써 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다.\n③개업공인중개사는 업무를 개시하기 전에 제1항 및 제2항에 따른 손해배상책임을 보장하기 위하여 대통령령으로 정하는 바에 따라 보증보험 또는 제42조에 따른 공제에 가입하거나 공탁을 하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제24조제1항","원문":"①개업공인중개사는 법 제30조제3항에 따라 다음 각 호의 구분에 따른 금액을 보장하는 보증보험 또는 공제에 가입하거나 공탁을 해야 한다.\n1. 법인인 개업공인중개사 : 4억원 이상. 다만, 분사무소를 두는 경우에는 분사무소마다 2억원 이상을 추가로 설정해야 한다.\n2. 법인이 아닌 개업공인중개사 : 2억원 이상"},{"법령":"공인중개사법 시행령","조문":"제26조제2항","원문":"②개업공인중개사는 보증보험금ㆍ공제금 또는 공탁금으로 손해배상을 한 때에는 15일 이내에 보증보험 또는 공제에 다시 가입하거나 공탁금 중 부족하게 된 금액을 보전하여야 한다."},{"법령":"공인중개사법","조문":"제38조제2항제8호·제39조제1항제11호","원문":"8. 제30조제3항에 따른 손해배상책임을 보장하기 위한 조치를 이행하지 아니하고 업무를 개시한 경우\n11. 제38조제2항 각 호의 어느 하나에 해당하는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"손해배상책임 보장 조치는 업무를 개시하기 전에 한다(법 제30조제3항)."},{"번호":2,"판정":"옳음","설명":"공인중개사인 개업공인중개사는 법인이 아니므로 2억원 이상을 보장해야 한다(영 제24조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"손해배상 후 15일 이내에 재가입하거나 공탁금 부족액을 보전한다(영 제26조제2항)."},{"번호":4,"판정":"틀림","설명":"보증 조치 없이 업무를 개시하면 등록취소 사유이면서(법 제38조제2항제8호), 제38조제2항 각 호에 해당하는 경우로서 업무정지 사유이기도 하다(법 제39조제1항제11호)."},{"번호":5,"판정":"옳음","설명":"사무소를 다른 사람의 중개행위 장소로 제공해 손해가 생기면 배상 책임이 있다(법 제30조제2항)."}],"개념":[{"종류":"표","제목":"손해배상책임 보장 기준","머리":["구분","내용","근거"],"행":[["보장 방법","보증보험 또는 공제 가입, 공탁","법 제30조제3항"],["설정 시기","업무를 개시하기 전","법 제30조제3항"],["보장금액(법인 아닌 개업공인중개사)","2억원 이상","영 제24조제1항제2호"],["보장금액(법인)","4억원 이상, 분사무소마다 2억원 이상 추가","영 제24조제1항제1호"],["다른 법률에 따라 중개업을 하는 자","2천만원 이상","영 제24조제3항"],["설정 신고","증명서류를 갖춰 등록관청에 신고, 보증기관이 직접 통보하면 생략","영 제24조제2항"],["보증 변경","이미 설정한 보증의 효력 기간 중에 다른 보증 설정 후 신고, 보증기간 만료 시 만료일까지 재설정","영 제25조"],["공탁금 회수","폐업 또는 사망한 날부터 3년 이내 회수 불가","법 제30조제4항"],["거래당사자에게 설명","중개가 완성된 때 보장금액, 보증기관과 소재지, 보장기간을 설명하고 증서 사본 교부, 위반 시 100만원 이하 과태료","법 제30조제5항, 법 제51조제3항제5호"]]},{"종류":"흐름","제목":"보증보험금 지급과 재가입","단계":[{"이름":"손해 발생","설명":"개업공인중개사의 고의·과실 중개행위나 사무소 제공으로 거래당사자가 재산상 손해를 입는다(법 제30조제1항·제2항)."},{"이름":"청구","설명":"중개의뢰인이 손해배상합의서, 화해조서, 확정판결문 사본 등을 첨부해 보증기관에 지급을 청구한다(영 제26조제1항)."},{"이름":"지급","설명":"보증보험금·공제금·공탁금으로 손해배상을 한다."},{"이름":"재가입·보전","설명":"지급한 때부터 15일 이내에 보증보험·공제에 다시 가입하거나 공탁금 부족액을 보전한다(영 제26조제2항)."}]}],"함정":"4번은 \"보증 미설정은 등록취소만 되고 업무정지는 안 된다\"는 식의 단정이 함정이다. 법 제39조제1항제11호가 제38조제2항 각 호 해당 사유를 업무정지 사유로 함께 규정한다. 1·3·5번은 숫자와 의무 자체를 그대로 묻는다."},"34회-2차-017":{"한줄":"연수교육 통지는 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 하도록 시행령 제28조제4항이 정하고 있다.","근거":[{"법령":"공인중개사법","조문":"제34조제1항","원문":"1. 폐업신고 후 1년 이내에 중개사무소의 개설등록을 다시 신청 하려는 자"},{"법령":"공인중개사법 시행령","조문":"제28조제1항~제4항","원문":"① … 2. 교육시간: 45시간 / ② 법 제34조제3항에 따른 직무교육의 내용 및 시간은 다음 각 호와 같다. 1. 교육내용: 중개보조원의 직무수행에 필요한 직업윤리 등 2. 교육시간: 3시간 이상 4시간 이하 / ③ … 2. 교육시간: 12시간 이상 16시간 이하 / ④ 시ㆍ도지사는 법 제34조제4항에 따른 연수교육을 실시하려는 경우 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 연수교육의 일시ㆍ장소ㆍ내용 등을 대상자에게 통지하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제28조의2제2항","원문":"국토교통부장관, 시ㆍ도지사 및 등록관청은 부동산 거래질서를 확립하고, 부동산거래사고로 인한 피해를 방지하기 위하여 법 제34조의2제2항에 따른 부동산거래사고 예방을 위한 교육을 실시하려는 경우에는 교육일 10일 전까지 교육일시ㆍ교육장소 및 교육내용, 그 밖에 교육에 필요한 사항을 공고하거나 교육대상자에게 통지하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"실무교육이 면제되는 재신청은 폐업신고 후 1년 이내에 하는 경우다. 400일은 1년을 넘으므로 실무교육을 받아야 한다(법 제34조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"중개보조원의 직무교육 시간은 3시간 이상 4시간 이하다(영 제28조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"연수교육 통지 시기는 2년이 되기 2개월 전까지다(영 제28조제4항)."},{"번호":4,"판정":"틀림","설명":"실무교육 시간은 45시간이다(영 제28조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"부동산거래사고 예방교육은 교육일 10일 전까지 공고하거나 통지한다(영 제28조의2제2항). 주체도 국토교통부장관, 시ㆍ도지사, 등록관청이다."}],"개념":[{"종류":"표","제목":"개업공인중개사등 교육의 종류","머리":["구분","대상","받는 시기","시간","실시 주체"],"행":[["실무교육","개설등록 신청자(법인은 사원ㆍ임원, 분사무소는 책임자), 소속공인중개사","등록신청일ㆍ고용신고일 전 1년 이내","45시간","시ㆍ도지사"],["직무교육","중개보조원","고용신고일 전 1년 이내","3시간 이상 4시간 이하","시ㆍ도지사 또는 등록관청"],["연수교육","실무교육을 받은 개업공인중개사ㆍ소속공인중개사","실무교육을 받은 후 2년마다","12시간 이상 16시간 이하","시ㆍ도지사"],["부동산거래사고 예방교육","개업공인중개사등","교육일 10일 전까지 공고 또는 통지","규정 없음","국토교통부장관, 시ㆍ도지사, 등록관청"]]},{"종류":"표","제목":"실무교육ㆍ직무교육이 면제되는 경우","머리":["대상","면제되는 경우"],"행":[["개설등록 신청자","폐업신고 후 1년 이내에 다시 신청하는 자"],["개설등록 신청자","소속공인중개사로서 고용관계 종료 신고 후 1년 이내에 신청하는 자"],["소속공인중개사 고용신고","고용관계 종료 신고 후 1년 이내에 다시 고용 신고를 하는 자"],["소속공인중개사 고용신고","개업공인중개사로서 폐업신고를 한 후 1년 이내에 고용 신고를 하는 자"],["중개보조원 고용신고","고용관계 종료 신고 후 1년 이내에 다시 고용 신고를 하는 자"]]}],"함정":"400일을 「1년 이내」로 읽고 고르기 쉬운 1번, 시간 숫자(45시간, 3~4시간, 12~16시간)를 섞어 쓴 2번ㆍ4번, 통지 시한 10일을 7일로 바꾼 5번이 오답 자리다.","개정":"실무교육 시간은 시행령 제28조제1항제2호 개정(2025.10.21)으로 45시간이다. 시간 숫자는 개정 전 기출과 다르므로 현행 숫자로 외운다."},"34회-2차-019":{"한줄":"재개 신고 위반은 20만원이고, 나머지 선지는 모두 30만원이다.","근거":[{"법령":"공인중개사법 시행령","조문":"별표 2 제2호 더목","원문":"더. 법 제21조제1항을 위반하여 휴업, 폐업, 휴업한 중개업의 재개 또는 휴업기간의 변경 신고를 하지 않은 경우 / 법 제51조제3항제4호 / 20만원"},{"법령":"공인중개사법 시행령","조문":"별표 2 제2호 사목","원문":"사. 법 제34조제4항에 따른 연수교육을 정당한 사유 없이 받지 않은 경우 … 1) 법 위반상태의 기간이 1개월 이내인 경우 20만원 2) 법 위반상태의 기간이 1개월 초과 3개월 이내인 경우 30만원 3) 법 위반상태의 기간이 3개월 초과 6개월 이내인 경우 50만원 4) 법 위반상태의 기간이 6개월 초과인 경우 100만원"},{"법령":"공인중개사법 시행령","조문":"별표 2 제2호 파목ㆍ너목ㆍ러목","원문":"파. 법 제17조를 위반하여 중개사무소등록증 등을 게시하지 않은 경우 … 30만원 / 너. 법 제20조제1항을 위반하여 중개사무소의 이전신고를 하지 않은 경우 … 30만원 / 러. 법 제30조제5항을 위반하여 손해배상책임에 관한 사항을 설명하지 않거나 관계 증서의 사본 또는 관계 증서에 관한 전자문서를 교부하지 않은 경우 … 30만원"}],"선지":[{"번호":1,"판정":"-","설명":"20만원이다(별표 2 더목). 다섯 선지 중 유일하게 20만원이다."},{"번호":2,"판정":"-","설명":"30만원이다(별표 2 파목)."},{"번호":3,"판정":"-","설명":"30만원이다(별표 2 너목)."},{"번호":4,"판정":"-","설명":"위반상태가 50일이면 1개월 초과 3개월 이내 구간이므로 30만원이다(별표 2 사목2))."},{"번호":5,"판정":"-","설명":"30만원이다(별표 2 러목)."}],"개념":[{"종류":"표","제목":"과태료 금액별 주요 위반행위 (시행령 별표 2)","머리":["금액","위반행위"],"행":[["500만원","존재하지 않는 중개대상물 표시ㆍ광고, 표시ㆍ광고 자료 미제출, 시정 조치 불이행, 중개보조원 신분 미고지"],["400만원","운영규정 승인 없이 정보망 운영, 공제업무 개선명령 불이행, 임원 징계ㆍ해임 요구 불이행"],["300만원","가격 등을 거짓으로 표시ㆍ광고, 공제사업 운용실적 미공시"],["200만원","거래정보사업자의 보고ㆍ조사 거부, 법 제42조의3 또는 제44조제1항에 따른 보고ㆍ조사 거부"],["50만원","사무소 명칭에 지정 문자 미사용, 옥외광고물 성명 미표기, 표시ㆍ광고(법 제18조의2제1항ㆍ제2항) 위반, 등록증 미반납"],["30만원","등록증 미게시, 이전신고 미이행, 손해배상책임 설명 미이행, 자격증 미반납"],["20만원","휴업, 폐업, 재개, 휴업기간 변경 신고 미이행"]]},{"종류":"표","제목":"연수교육 미이수 과태료 (별표 2 사목)","머리":["위반상태 기간","과태료"],"행":[["1개월 이내","20만원"],["1개월 초과 3개월 이내","30만원"],["3개월 초과 6개월 이내","50만원"],["6개월 초과","100만원"]]}],"함정":"연수교육 50일을 1개월 이내로 읽으면 20만원이 되어 두 선지가 같아 보인다. 50일은 1개월을 넘으므로 30만원이다."},"34회-2차-049":{"한줄":"기반시설부담구역은 개발밀도관리구역 ‘외’의 지역을 대상으로 하므로, 개발밀도관리구역에는 지정할 수 없다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제19호","원문":"\"기반시설부담구역\"이란 개발밀도관리구역 외의 지역으로서 개발로 인하여 도로, 공원, 녹지 등 대통령령으로 정하는 기반시설의 설치가 필요한 지역을 대상으로 기반시설을 설치하거나 그에 필요한 용지를 확보하게 하기 위하여 제67조에 따라 지정ㆍ고시하는 구역을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제130조제1항","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수나 도시ㆍ군계획시설사업의 시행자는 다음 각 호의 행위를 하기 위하여 필요하면 타인의 토지에 출입하거나 ... 2. 개발밀도관리구역, 기반시설부담구역 및 제67조제4항에 따른 기반시설설치계획에 관한 기초조사"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제5항","원문":"개발밀도관리구역의 지정기준, 개발밀도관리구역의 관리 등에 관하여 필요한 사항은 대통령령으로 정하는 바에 따라 국토교통부장관이 정한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제62조제1항","원문":"법 제66조제2항에서 \"대통령령으로 정하는 범위\"란 해당 용도지역에 적용되는 용적률의 최대한도의 50퍼센트를 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제3항","원문":"특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 제1항에 따라 개발밀도관리구역을 지정하거나 변경하려면 다음 각 호의 사항을 포함하여 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개발밀도관리구역 기초조사는 출입 사유에 포함되고, 도시ㆍ군계획시설사업의 시행자도 출입할 수 있다(법 제130조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"지정기준과 관리 사항은 국토교통부장관이 정한다(법 제66조제5항)."},{"번호":3,"판정":"옳음","설명":"용적률 최대한도의 50퍼센트 범위에서 강화한다(법 제66조제2항, 영 제62조제1항)."},{"번호":4,"판정":"옳음","설명":"지정ㆍ변경 시 해당 지방자치단체의 지방도시계획위원회 심의를 거친다(법 제66조제3항)."},{"번호":5,"판정":"틀림","설명":"기반시설부담구역은 개발밀도관리구역 외의 지역에 지정한다(법 제2조제19호)."}],"개념":[{"종류":"비교","제목":"개발밀도관리구역과 기반시설부담구역","왼쪽":{"이름":"개발밀도관리구역","항목":["대상: 주거ㆍ상업ㆍ공업지역에서 개발행위로 기반시설 수용능력이 부족할 것으로 예상되고 설치가 곤란한 지역(법 제66조제1항)","효과: 건폐율ㆍ용적률 강화, 용적률은 최대한도의 50퍼센트 범위(영 제62조제1항)","절차: 해당 지방자치단체 지방도시계획위원회 심의 후 공보 고시(법 제66조제3항ㆍ제4항, 영 제62조제2항)","지정기준: 국토교통부장관이 정함(법 제66조제5항)"]},"오른쪽":{"이름":"기반시설부담구역","항목":["대상: 개발밀도관리구역 외의 지역(법 제2조제19호)","효과: 200제곱미터 초과 건축물의 신축ㆍ증축 건축행위자에게 기반시설설치비용 부과(법 제68조)","절차: 주민 의견 청취, 지방도시계획위원회 심의, 고시(법 제67조제2항)","지정 후: 기반시설설치계획 수립, 도시ㆍ군관리계획 반영(법 제67조제4항)"]}},{"종류":"표","제목":"개발밀도관리구역 지정기준(영 제63조)","머리":["항목","내용"],"행":[["도로서비스","도로서비스 수준이 매우 낮아 차량통행이 현저히 지체되는 지역"],["도로율","국토교통부령이 정한 용도지역별 도로율에 20퍼센트 이상 미달"],["수도","향후 2년 이내 수요량이 수도시설 용량 초과 예상"],["하수","향후 2년 이내 하수발생량이 하수시설 용량 초과 예상"],["학교","향후 2년 이내 학생수가 학교수용능력을 20퍼센트 이상 초과 예상"],["경계","도로ㆍ하천 등 지형지물 또는 용도지역 경계선을 이용해 분명하게 구분"]]}],"함정":"선지 5는 두 구역이 서로 겹치지 않는다는 점을 모르면 풀리지 않는다. 기반시설부담구역은 정의 자체에서 개발밀도관리구역 외의 지역으로 한정된다."},"34회-2차-062":{"한줄":"설치비용 부담금은 공사 착수 전에 3분의 1 이상을 내고, 잔액은 공사완료 고시일 전까지 낸다.","근거":[{"법령":"도시 및 주거환경정비법 시행규칙","조문":"제16조제4항","원문":"④ 제3항에 따라 부담금의 납부통지를 받은 공동구점용예정자는 공동구의 설치공사가 착수되기 전에 부담금액의 3분의 1 이상을 납부하여야 하며, 그 잔액은 법 제83조제3항 또는 제4항에 따른 공사완료 고시일전까지 납부하여야 한다."},{"법령":"도시 및 주거환경정비법 시행규칙","조문":"제16조제1항제4호","원문":"① 법 제94조제2항에 따른 공동구의 설치에 드는 비용은 다음 각 호와 같다. 다만, 법 제95조에 따른 보조금이 있는 경우에는 설치에 드는 비용에서 해당 보조금의 금액을 빼야 한다. 4. 공동구의 설치로 인한 보상의 필요가 있는 경우에는 그 보상비용"},{"법령":"도시 및 주거환경정비법 시행규칙","조문":"제16조제2항","원문":"② 공동구에 수용될 전기ㆍ가스ㆍ수도의 공급시설과 전기통신시설 등의 관리자(이하 \"공동구점용예정자\"라 한다)가 부담할 공동구의 설치에 드는 비용의 부담비율은 공동구의 점용예정면적비율에 따른다."},{"법령":"도시 및 주거환경정비법 시행규칙","조문":"제17조제3항ㆍ제4항","원문":"③ 공동구 관리비용은 연도별로 산출하여 부과한다. ④ 공동구 관리비용의 납입기한은 매년 3월 31일까지로 하며, 시장ㆍ군수등은 납입기한 1개월 전까지 납입통지서를 발부하여야 한다. 다만, 필요한 경우에는 2회로 분할하여 납부하게 할 수 있으며 이 경우 분할금의 납입기한은 3월 31일과 9월 30일로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"설치비용의 부담비율은 공동구의 점용예정면적비율에 따른다. 시장ㆍ군수등이 정하는 것은 관리비용의 부담비율이다(규칙 제16조제2항, 제17조제2항)."},{"번호":2,"판정":"틀림","설명":"공동구의 설치로 인한 보상의 필요가 있는 경우에는 그 보상비용이 설치비용에 포함된다(규칙 제16조제1항제4호)."},{"번호":3,"판정":"옳음","설명":"납부통지를 받은 공동구점용예정자는 설치공사 착수 전에 부담금액의 3분의 1 이상을, 잔액은 공사완료 고시일 전까지 납부한다(규칙 제16조제4항)."},{"번호":4,"판정":"틀림","설명":"공동구 관리비용은 연도별로 산출하여 부과한다(규칙 제17조제3항)."},{"번호":5,"판정":"틀림","설명":"관리비용은 필요한 경우 2회로 분할해 납부하게 할 수 있고, 분할금의 납입기한은 3월 31일과 9월 30일이다. 분기별 납부 규정은 없다(규칙 제17조제4항)."}],"개념":[{"종류":"비교","제목":"공동구 설치비용과 관리비용","왼쪽":{"이름":"설치비용(규칙 제16조)","항목":["포함 항목: 설치공사, 내부공사, 측량ㆍ설계, 보상(보상 필요 시), 부대시설 설치, 융자금 이자. 보조금이 있으면 그만큼 뺀다","부담자: 공동구점용예정자(전기ㆍ가스ㆍ수도 공급시설과 전기통신시설 등의 관리자)","부담비율: 공동구의 점용예정면적비율","통지: 사업시행계획인가 고시 후 지체 없이 사업시행자가 부담금 납부 통지","납부: 공사 착수 전 3분의 1 이상, 잔액은 공사완료 고시일 전까지"]},"오른쪽":{"이름":"관리비용(규칙 제17조)","항목":["관리자: 시장ㆍ군수등","범위: 유지ㆍ수선비(조명ㆍ배수ㆍ통풍ㆍ방수ㆍ개축ㆍ재축ㆍ그 밖의 시설비와 인건비 포함)","부담: 일부를 점용하는 자에게 부담시킬 수 있고, 비율은 점용면적비율을 고려해 시장ㆍ군수등이 정함","산출: 연도별로 산출해 부과","납입: 매년 3월 31일까지(1개월 전 납입통지서 발부). 필요하면 2회 분할, 3월 31일과 9월 30일"]}},{"종류":"표","제목":"공동구 관련 조문 위치","머리":["항목","내용","근거"],"행":[["설치 시 비용 부담","사업시행자가 다른 법령에 따라 공동구에 수용될 시설을 설치할 의무가 있는 자에게 설치비 부담","법 제94조제2항"],["부담 비율ㆍ방법, 공동구 관리","국토교통부령으로 정함","법 제94조제3항"],["공동구 관리 주체","시장ㆍ군수등","규칙 제17조제1항"],["사업시행계획서 기재","공동구의 설치에 관한 사항","영 제47조제2항제9호"]]}],"함정":"선지 1은 관리비용의 부담비율 문장(점용면적비율을 고려해 시장ㆍ군수등이 정한다)에서 가져와 설치비용에 붙여 놓았다. 설치비용은 점용예정면적비율로 고정이다. 선지 4와 5는 관리비용의 주기를 반기와 분기로 바꾼 것이고, 실제는 연도별 산출에 2회 분할이다."},"34회-2차-119":{"한줄":"국가 소유 토지와 분합하는 농지도 쌍방 토지가액의 차액이 가액이 큰 편의 4분의 1 이하여야 비과세이므로, 4분의 1을 초과해도 비과세라는 ⑤가 틀리다.","근거":[{"법령":"소득세법 시행령","조문":"제153조제1항","원문":"교환 또는 분합하는 쌍방 토지가액의 차액이 가액이 큰편의 4분의 1이하인 경우를 말한다."},{"법령":"소득세법","조문":"제89조제1항제5호","원문":"「지적재조사에 관한 특별법」 제18조에 따른 경계의 확정으로 지적공부상의 면적이 감소되어 같은 법 제20조에 따라 지급받는 조정금"},{"법령":"소득세법 시행령","조문":"제168조제1항제7호","원문":"건설사업자가 「도시개발법」에 따라 공사용역 대가로 취득한 체비지를 토지구획환지처분공고 전에 양도하는 토지"}],"선지":[{"번호":1,"판정":"옳음","설명":"파산선고에 의한 처분으로 발생하는 소득은 비과세다(소득세법 제89조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"경계 확정으로 면적이 감소되어 받는 조정금은 비과세다(소득세법 제89조제1항제5호)."},{"번호":3,"판정":"옳음","설명":"건설사업자가 공사용역 대가로 취득한 체비지를 환지처분공고 전에 양도하는 토지는 미등기양도 제외 자산이다(시행령 제168조제1항제7호)."},{"번호":4,"판정":"옳음","설명":"도시개발사업이 종료되지 않아 취득등기를 하지 않고 양도하는 토지는 미등기양도 제외 자산이다(시행령 제168조제1항제6호)."},{"번호":5,"판정":"틀림","설명":"국가 또는 지방자치단체 소유 토지와 교환ㆍ분합하는 농지는 쌍방 토지가액의 차액이 가액이 큰 편의 4분의 1 이하일 때만 비과세다(시행령 제153조제1항제2호)."}],"개념":[{"종류":"표","제목":"비과세 양도소득(소득세법 제89조제1항)과 농지 교환ㆍ분합","머리":["구분","내용"],"행":[["파산선고에 의한 처분","파산선고에 의한 처분으로 발생하는 소득(제1호)"],["농지의 교환ㆍ분합","쌍방 토지가액 차액이 가액이 큰 편의 4분의 1 이하이면서 ①국가ㆍ지방자치단체 시행 사업, ②국가ㆍ지방자치단체 소유 토지와의 교환ㆍ분합, ③경작상 필요에 의한 교환(새 농지를 3년 이상 농지소재지에 거주하며 경작), ④농어촌정비법ㆍ농지법ㆍ한국농어촌공사 및 농지관리기금법ㆍ농업협동조합법에 의한 교환ㆍ분합(제2호, 시행령 제153조제1항)"],["농지 교환ㆍ분합 제외","특별시ㆍ광역시ㆍ시 지역의 주거ㆍ상업ㆍ공업지역 안 농지(예외 있음), 환지예정지 지정 후 3년이 지난 농지(시행령 제153조제4항)"],["1세대 1주택","양도 당시 실지거래가액 12억원 이하 주택과 주택부수토지(제3호)"],["조합원입주권","1세대가 조합원입주권을 1개 보유하고 일정 요건을 충족하여 양도하는 경우(제4호)"],["지적재조사 조정금","경계 확정으로 면적이 감소되어 지급받는 조정금(제5호)"]]},{"종류":"표","제목":"미등기양도 제외 자산(소득세법 시행령 제168조제1항)","머리":["호","자산"],"행":[["1호","장기할부조건으로 취득한 자산으로서 계약조건상 양도 당시 취득등기가 불가능한 자산"],["2호","법률의 규정 또는 법원의 결정으로 양도 당시 취득등기가 불가능한 자산"],["3호","소득세법 제89조제1항제2호(농지 교환ㆍ분합), 조세특례제한법 제69조제1항ㆍ제70조제1항의 토지"],["4호","1세대 1주택 등 비과세 주택으로서 건축허가를 받지 않아 등기가 불가능한 자산"],["6호","도시개발사업이 종료되지 않아 토지 취득등기를 하지 않고 양도하는 토지"],["7호","건설사업자가 도시개발법에 따라 공사용역 대가로 취득한 체비지를 환지처분공고 전에 양도하는 토지"]]}],"함정":"농지 교환ㆍ분합 비과세는 상대방이 국가나 지방자치단체여도 가액 차이 4분의 1 이하라는 요건이 빠지지 않는다. 미등기양도 제외 자산은 도시개발사업 종료 전 토지, 환지처분공고 전 체비지처럼 등기가 불가능한 사정이 있는 경우다."},"34회-1차-002":{"한줄":"생산요소와 자산은 경제적(자산·자본·생산요소) 개념이고, 물리적(기술적) 개념에는 공간·위치·환경·자연이 들어간다.","근거":[{"법령":"민법","조문":"제99조","원문":"①토지 및 그 정착물은 부동산이다.\n②부동산 이외의 물건은 동산이다."},{"이론":"부동산의 복합개념","내용":"법률적(협의·광의), 경제적(자산·자본·생산요소·상품·소비재), 물리적(공간·위치·환경·자연) 세 측면으로 나눈다."}],"선지":[{"번호":1,"판정":"옳음","설명":"민법 제99조 제1항. 협의의 부동산이 곧 토지와 정착물이다."},{"번호":2,"판정":"옳음","설명":"수익성·수급조절·시장정보는 가치에 영향을 주는 경제적 측면의 내용이다."},{"번호":3,"판정":"틀림","설명":"생산요소와 자산은 경제적 개념이다. 물리적 개념은 공간·위치·환경·자연이다."},{"번호":4,"판정":"옳음","설명":"등기 대상(입목·공장재단·광업재단·20톤 이상 선박)과 등록 대상(자동차·항공기·건설기계)은 준부동산이다."},{"번호":5,"판정":"옳음","설명":"공간적 개념은 지하·지표·공중공간을 포함하는 입체 공간이다."}],"개념":[{"종류":"표","제목":"부동산 복합개념 세 측면","머리":["측면","구분","내용"],"행":[["법률적","협의","민법 제99조의 토지 + 정착물"],["법률적","광의","협의의 부동산 + 준부동산"],["경제적","성격","자산·자본·생산요소·상품·소비재"],["경제적","가치 영향","수익성·수급조절·시장정보"],["물리적(기술적)","대상","공간·위치·환경·자연"]]},{"종류":"표","제목":"준부동산 공시방법","머리":["공시","대상"],"행":[["등기","입목, 공장재단, 광업재단, 20톤 이상 선박"],["등록","자동차, 항공기, 건설기계"],["등록(권리)","광업권, 어업권"],["정착물 구분","종속정착물(구거·교량·담장·다년생 식물) / 독립정착물(건물·등기된 입목·명인방법을 갖춘 수목 집단)"]]}],"함정":"생산요소·자산을 물리적 개념에 넣은 문장에서 걸린다. 생산요소·자산은 경제적 개념이다."},"34회-1차-008":{"한줄":"시장수요곡선은 같은 가격에서 개별 수요량을 더하므로 개별수요곡선을 수평(수량 방향)으로 합해 구한다.","근거":[{"이론":"시장수요곡선의 도출","내용":"각 가격 수준에서 개별 수요량을 합산한다. 수평 합이다. 수직 합은 공공재의 시장수요 도출 방식이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수요량은 실제 구매량이 아니라 일정 가격에서 사려고 하는 최대 수량이다."},{"번호":2,"판정":"옳음","설명":"공급함수는 공급량과 그 결정 요인의 관계를 나타낸다."},{"번호":3,"판정":"옳음","설명":"가격과 공급량은 정(+)의 관계다."},{"번호":4,"판정":"틀림","설명":"개별수요곡선을 수평으로 합한다."},{"번호":5,"판정":"옳음","설명":"원자재 가격 상승은 생산비 증가 요인이어서 공급곡선이 좌상향으로 이동한다."}],"개념":[{"종류":"표","제목":"수요곡선 이동요인과 공급곡선 이동요인","머리":["구분","우측(증가)","좌측(감소)"],"행":[["수요(정상재)","소득 증가, 인구 증가, 대체재 가격 상승, 보완재 가격 하락, 금리 하락","소득 감소, 대체재 가격 하락, 보완재 가격 상승, 금리 상승"],["공급","건축비 하락, 기술 진보, 공급자 수 증가, 세금 감소","건축비·원자재 가격 상승, 규제 강화, 세금 증가"],["해당 재 가격 변화","곡선 위의 이동(수요량·공급량 변화)","곡선 위의 이동"]]},{"종류":"비교","제목":"수요량 변화와 수요 변화","왼쪽":{"이름":"수요량 변화","항목":["해당 재의 가격 변화가 원인","같은 수요곡선 위에서 이동"]},"오른쪽":{"이름":"수요 변화","항목":["가격 이외 요인이 원인","수요곡선 자체가 좌우로 이동"]}}],"함정":"시장수요곡선을 수직합으로 그리는 선택지가 정답이다. 수평합이다."},"34회-1차-007":{"한줄":"공급곡선이 수직선이면 가격이 변해도 공급량이 그대로이므로 탄력성이 0, 곧 완전비탄력적이다.","근거":[{"이론":"가격탄력성의 구분","내용":"ε=0 완전비탄력(수직선), 0<ε<1 비탄력, ε=1 단위탄력, 1<ε<∞ 탄력, ε=∞ 완전탄력(수평선)."}],"선지":[{"번호":1,"판정":"틀림","설명":"가격이 변해도 수요량이 불변이면 완전비탄력적(ε=0)이다."},{"번호":2,"판정":"틀림","설명":"공급량 변화율이 가격 변화율보다 커서 ε>1이면 탄력적이다."},{"번호":3,"판정":"틀림","설명":"ε=0은 완전비탄력적이다."},{"번호":4,"판정":"틀림","설명":"ε<1이면 비탄력적이다."},{"번호":5,"판정":"옳음","설명":"수직선 공급곡선은 ε=0, 완전비탄력적이다."}],"개념":[{"종류":"표","제목":"가격탄력성 구분","머리":["탄력성 값","명칭","곡선 모양","의미"],"행":[["ε = 0","완전비탄력적","수직선","가격이 변해도 수량 불변"],["0 < ε < 1","비탄력적","가파른 곡선","수량 변화율 < 가격 변화율"],["ε = 1","단위탄력적","직각쌍곡선(수요)","수량 변화율 = 가격 변화율"],["1 < ε < ∞","탄력적","완만한 곡선","수량 변화율 > 가격 변화율"],["ε = ∞","완전탄력적","수평선","특정 가격에서 수량이 무한히 변함"]]},{"종류":"표","제목":"소득·교차탄력성 부호","머리":["탄력성","부호","해석"],"행":[["소득탄력성","(+)","정상재, 1보다 크면 사치재"],["소득탄력성","(−)","열등재"],["교차탄력성","(+)","대체재 관계"],["교차탄력성","(−)","보완재 관계"]]}],"함정":"수요량이 전혀 변하지 않는 경우를 완전탄력적으로 고르기 쉽다. 완전비탄력적이다."},"34회-1차-009":{"한줄":"마샬의 준지대는 사람이 만든 기계·기구에서 생기는 일시적 소득이다.","근거":[{"이론":"지대이론","내용":"리카도 차액지대(비옥도 차이), 튀넨 위치지대(시장까지의 거리·운송비), 마르크스 절대지대(최열등지에도 발생), 마샬 준지대(인공 자본의 일시적 소득), 헤이그 마찰비용(지대 + 교통비 = 마찰비용)."}],"선지":[{"번호":1,"판정":"틀림","설명":"위치지대설은 시장까지의 거리(운송비 차이)에 기초한다. 비옥도 차이는 리카도다."},{"번호":2,"판정":"옳음","설명":"준지대는 인공물(기계·기구)로부터 얻는 일시적 소득이다."},{"번호":3,"판정":"틀림","설명":"리카도는 비옥도(생산성) 차이로 설명했다. 운송비는 튀넨의 위치지대다."},{"번호":4,"판정":"틀림","설명":"절대지대는 최열등지에도 발생한다. 최열등지에서 지대가 없다는 것은 리카도의 차액지대다."},{"번호":5,"판정":"틀림","설명":"마찰비용(지대 + 교통비) 중 교통비를 뺀 몫이 지대가 된다. 지대는 교통비 절약분이다."}],"개념":[{"종류":"표","제목":"지대이론 비교","머리":["학자","이론","핵심"],"행":[["리카도","차액지대","비옥도 차이, 최열등지는 지대 없음"],["튀넨","위치지대(고립국)","시장까지의 거리에 따른 운송비 차이"],["마르크스","절대지대","사적 소유 자체로 최열등지에도 발생"],["마샬","준지대","인공 자본의 일시적 소득"],["파레토","경제지대","공급이 비탄력적인 생산요소의 대가 중 전용수입 초과분"],["알론소","입찰지대","중심에서 멀어질수록 입찰지대 하락"],["헤이그","마찰비용","지대 + 교통비 = 마찰비용"]]}],"함정":"리카도와 튀넨을 섞는 오답을 고르기 쉽다. 비옥도는 리카도, 운송비는 튀넨이다."},"34회-1차-013":{"한줄":"등비용선은 최소운송비 지점에서 멀어질 때 추가로 드는 운송비가 같은 지점을 이은 선이다. 운송비와 노동비를 같게 이은 선이 아니다.","근거":[{"이론":"베버의 최소비용이론","내용":"운송비 최소점(입지삼각형)을 기준으로 노동비 절약액과 추가 운송비를 견주고(등비용선·임계등비용선), 집적이익까지 더해 입지를 정한다. 원료지수 = 국지원료 중량 ÷ 제품 중량."}],"선지":[{"번호":1,"판정":"옳음","설명":"운송비, 노동비, 집적이익을 차례로 고려한다."},{"번호":2,"판정":"틀림","설명":"등비용선은 추가 운송비가 같은 지점의 연결선이다."},{"번호":3,"판정":"옳음","설명":"원료지수 > 1이면 원료지향, < 1이면 시장지향."},{"번호":4,"판정":"옳음","설명":"제품이 국지원료보다 무거우면 원료지수가 1 미만이어서 시장지향이다."},{"번호":5,"판정":"옳음","설명":"운송비는 무게와 거리에 비례한다."}],"개념":[{"종류":"흐름","제목":"베버 입지 결정 순서","단계":[{"이름":"최소운송비 지점","설명":"입지삼각형에서 운송비가 가장 적은 지점을 찾는다. 원료지수로 원료지향·시장지향을 판단"},{"이름":"등비용선","설명":"최소운송비 지점에서 멀어질 때 추가 운송비가 같은 지점을 연결"},{"이름":"임계등비용선","설명":"노동비 절약액과 추가 운송비가 같아지는 등비용선"},{"이름":"최소노동비 지점","설명":"임계등비용선 안에 있으면 그 지점으로 이동"},{"이름":"집적이익","설명":"집적으로 비용이 줄면 입지를 다시 조정"}]},{"종류":"표","제목":"원료지수와 입지","머리":["원료지수","의미","입지"],"행":[["MI > 1","국지원료 중량이 제품보다 큼","원료지향"],["MI < 1","제품 중량이 국지원료보다 큼","시장지향"],["MI = 1","양쪽 같음","중간 입지 가능"],["보편원료","어디서나 구함","시장지향(운송비 부담 없음)"]]}],"함정":"등비용선을 운송비와 노동비가 같은 선으로 보는 선택지를 놓친다. 정의는 추가 운송비가 같은 선이다."},"34회-1차-014":{"한줄":"배후지는 중심지가 재화와 서비스를 공급하는 주변지역이다.","근거":[{"이론":"중심지이론의 용어","내용":"도달범위는 수요가 0이 되는 거리, 최소요구치는 중심지 기능 유지에 필요한 최소 수요 규모, 최소요구범위는 정상이윤을 얻을 만큼의 소비자를 포함하는 경계까지의 거리다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이 서술은 최소요구치의 정의다. 최소요구범위는 정상이윤을 얻을 만큼의 소비자가 있는 경계까지의 거리."},{"번호":2,"판정":"틀림","설명":"수요가 0이 되는 곳까지의 거리는 도달범위다."},{"번호":3,"판정":"옳음","설명":"배후지는 재화·서비스를 공급받는 주변지역이다."},{"번호":4,"판정":"틀림","설명":"이 서술은 최소요구범위의 정의다. 도달범위는 수요가 0이 되는 거리."},{"번호":5,"판정":"틀림","설명":"중심지 재화·서비스는 중심지에서 배후지로 제공된다."}],"개념":[{"종류":"표","제목":"중심지이론 용어","머리":["용어","뜻"],"행":[["중심지","재화·서비스를 공급하는 장소"],["배후지","중심지에서 재화·서비스를 공급받는 주변지역"],["도달범위","중심지로부터 수요가 0이 되는 곳까지의 거리"],["최소요구치","중심지 기능이 유지되기 위한 최소 수요 규모"],["최소요구범위","정상이윤을 얻을 만큼의 소비자를 포함하는 경계까지의 거리"]]},{"종류":"표","제목":"상업입지 이론","머리":["이론","핵심"],"행":[["레일리 소매인력법칙","인구에 비례, 거리의 제곱에 반비례"],["컨버스 분기점","경쟁 도시 상권의 분기점 = 거리 ÷ (1 + √(상대 인구 ÷ 자기 인구))"],["허프 확률모형","점포 면적에 비례, 거리의 마찰계수 제곱에 반비례하여 이용 확률 결정"],["넬슨 입지원칙","상업지 선정 8원칙(접근성·성장 가능성·집적이익 등)"]]}],"함정":"최소요구치, 최소요구범위, 도달범위 정의를 서로 바꿔 놓은 보기가 나란히 있다."},"34회-1차-026":{"한줄":"내부수익률은 순현재가치를 0으로, 수익성지수를 1로 만드는 할인율이다.","근거":[{"이론":"내부수익률(IRR)","내용":"유입 현가와 유출 현가를 같게 하는 할인율이다. 따라서 NPV = 0, PI = 1이 된다."},{"이론":"투자분석기법의 분류","내용":"할인법(시간가치 반영): 순현재가치법·내부수익률법·수익성지수법. 비할인법: 단순회수기간법·회계적이익률법·승수법·비율분석법."}],"선지":[{"번호":1,"판정":"틀림","설명":"수익성지수는 1로, 순현재가치는 0으로 만드는 할인율이 내부수익률이다. 0과 1이 바뀌어 있다."},{"번호":2,"판정":"옳음","설명":"회계적이익률법은 회계상 이익을 기준으로 하므로 현금흐름의 시간가치를 반영하지 않는다."},{"번호":3,"판정":"옳음","설명":"IRR이 요구수익률 이상이면 채택하고 미만이면 기각한다."},{"번호":4,"판정":"옳음","설명":"순현재가치법·내부수익률법·수익성지수법이 할인현금수지분석법이다."},{"번호":5,"판정":"옳음","설명":"LTV는 융자액 ÷ 부동산 가치다."}],"개념":[{"종류":"표","제목":"투자분석기법의 분류","머리":["구분","기법","시간가치","특징"],"행":[["할인법","순현재가치법·내부수익률법·수익성지수법","반영","미래 현금흐름을 할인"],["비할인법","단순회수기간법·회계적이익률법","무시","계산은 쉬우나 회수 후 현금흐름을 안 본다"],["어림셈법","승수법·수익률법","무시","소득 한 해분만 사용"],["비율분석법","부채감당률·LTV·DTI·부채비율·채무불이행률","무시","상환능력·위험 점검"]]},{"종류":"표","제목":"세 지표가 만나는 점","머리":["구분","NPV","PI","IRR"],"행":[["채택","0 초과","1 초과","요구수익률 초과"],["무차별","0","1","요구수익률과 같음"],["기각","0 미만","1 미만","요구수익률 미만"],["구하는 값","유입 현가 − 유출 현가","유입 현가 ÷ 유출 현가","NPV를 0으로 만드는 할인율"]]}],"함정":"0과 1을 맞바꾼 선지에 가장 많이 걸린다. NPV의 기준값은 0, PI의 기준값은 1이다."},"34회-1차-030":{"한줄":"고정이자를 지급하는 증권은 시장수익률이 오르면 현재가치가 줄어 가격이 하락한다.","근거":[{"이론":"MBS 가격과 시장수익률","내용":"MBS 가격은 미래 현금흐름의 현재가치다. 시장수익률(할인율)이 오르면 가격이 하락하고, 내리면 상승한다. 듀레이션이 긴 증권일수록 가격 변동폭이 크다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시장수익률 하락이 예상되면 가격이 오른다. 듀레이션이 긴 증권일수록 상승폭이 더 크다."},{"번호":2,"판정":"틀림","설명":"채무불이행 위험이 없어도 할인율인 시장수익률이 변하면 가격이 변한다."},{"번호":3,"판정":"틀림","설명":"동일위험 투자수단의 수익률이 오르면 MBS의 할인율도 올라 가격이 내린다."},{"번호":4,"판정":"틀림","설명":"듀레이션이 긴 증권일수록 시장수익률 변동에 따른 가격 변동폭이 크다."},{"번호":5,"판정":"옳음","설명":"고정이자 MBS는 시장수익률이 오르면 가격이 하락한다."}],"개념":[{"종류":"표","제목":"시장수익률과 MBS 가격","머리":["상황","MBS 가격","듀레이션이 긴 증권","비고"],"행":[["시장수익률 상승","하락","하락폭 더 큼","할인율 상승"],["시장수익률 하락","상승","상승폭 더 큼","할인율 하락"],["동일위험 다른 투자수단 수익률 상승","하락","하락폭 더 큼","경쟁 투자수단 수익률은 할인율에 반영"],["채무불이행 위험 없음","시장수익률 영향은 그대로 받음","—","위험은 요구금리에 반영"]]},{"종류":"비교","제목":"MBS 세 가지","왼쪽":{"이름":"MPTS(지분형)","항목":["저당채권 소유권은 투자자","원리금 수취권은 투자자","조기상환위험은 투자자","초과담보 없음"]},"오른쪽":{"이름":"MBB(채권형)","항목":["소유권·원리금 수취권은 발행자","조기상환위험은 발행자","발행자가 초과담보 제공","MPTB는 소유권은 발행자, 수취권·조기상환위험은 투자자"]}}],"함정":"방향을 잘못 읽는 경우가 대부분이다. 수익률(할인율)과 가격은 반대로 움직인다. 듀레이션은 변동폭의 크기만 키우고 방향은 바꾸지 않는다."},"34회-1차-039":{"한줄":"표준지공시지가는 둘 이상의 감정평가법인등에 의뢰하여 조사·평가한다. 한국부동산원에 의뢰한다는 선지가 틀렸다.","근거":[{"법령":"부동산 가격공시에 관한 법률","조문":"제3조제5항","원문":"⑤ 국토교통부장관이 제1항에 따라 표준지공시지가를 조사ㆍ평가할 때에는 업무실적, 신인도(信認度) 등을 고려하여 둘 이상의 「감정평가 및 감정평가사에 관한 법률」에 따른 감정평가법인등(이하 \"감정평가법인등\"이라 한다)에게 이를 의뢰하여야 한다. 다만, 지가 변동이 작은 경우 등 대통령령으로 정하는 기준에 해당하는 표준지에 대해서는 하나의 감정평가법인등에 의뢰할 수 있다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제7조제1항","원문":"① 표준지공시지가에 이의가 있는 자는 그 공시일부터 30일 이내에 서면(전자문서를 포함한다. 이하 같다)으로 국토교통부장관에게 이의를 신청할 수 있다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제9조","원문":"표준지공시지가는 토지시장에 지가정보를 제공하고 일반적인 토지거래의 지표가 되며, 국가ㆍ지방자치단체 등이 그 업무와 관련하여 지가를 산정하거나 감정평가법인등이 개별적으로 토지를 감정평가하는 경우에 기준이 된다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제10조제2항","원문":"② 제1항에도 불구하고 표준지로 선정된 토지, 조세 또는 부담금 등의 부과대상이 아닌 토지, 그 밖에 대통령령으로 정하는 토지에 대하여는 개별공시지가를 결정ㆍ공시하지 아니할 수 있다. 이 경우 표준지로 선정된 토지에 대하여는 해당 토지의 표준지공시지가를 개별공시지가로 본다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제10조제4항","원문":"④ 시장ㆍ군수 또는 구청장이 개별공시지가를 결정ㆍ공시하는 경우에는 해당 토지와 유사한 이용가치를 지닌다고 인정되는 하나 또는 둘 이상의 표준지의 공시지가를 기준으로 토지가격비준표를 사용하여 지가를 산정하되, 해당 토지의 가격과 표준지공시지가가 균형을 유지하도록 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"표준지공시지가의 효력이다(제9조)."},{"번호":2,"판정":"틀림","설명":"국토교통부장관은 업무실적, 신인도 등을 고려하여 둘 이상의 감정평가법인등에 의뢰하여야 한다. 지가변동이 작은 경우 등 대통령령으로 정한 표준지는 하나의 감정평가법인등에 의뢰할 수 있다(제3조제5항)."},{"번호":3,"판정":"옳음","설명":"표준지공시지가 이의신청은 공시일부터 30일 이내에 서면으로 국토교통부장관에게 한다(제7조제1항)."},{"번호":4,"판정":"옳음","설명":"개별공시지가는 표준지공시지가를 기준으로 토지가격비준표를 사용해 산정하며 균형을 유지해야 한다(제10조제4항)."},{"번호":5,"판정":"옳음","설명":"표준지로 선정된 토지는 개별공시지가를 결정·공시하지 않을 수 있으며, 이때 표준지공시지가가 개별공시지가로 간주된다(제10조제2항)."}],"개념":[{"종류":"표","제목":"표준지공시지가와 개별공시지가","머리":["구분","표준지공시지가","개별공시지가"],"행":[["공시 주체","국토교통부장관","시장·군수·구청장"],["심의 기구","중앙부동산가격공시위원회","시·군·구부동산가격공시위원회"],["산정 방법","표준지를 조사·평가 (둘 이상의 감정평가법인등에 의뢰)","표준지공시지가 + 토지가격비준표, 감정평가법인등의 검증"],["이의신청","공시일부터 30일 이내, 국토교통부장관에게","결정·공시일부터 30일 이내, 시장·군수·구청장에게"],["이의신청 처리","신청기간 만료일부터 30일 이내 심사·통지","신청기간 만료일부터 30일 이내 심사·통지"],["효력·용도","지가정보 제공, 토지거래의 지표, 보상·평가의 기준","세금 부과 등 각종 법령상 지가산정의 기준"]]},{"종류":"흐름","제목":"표준지공시지가의 공시","단계":[{"이름":"표준지 선정","설명":"토지이용상황 등이 일반적으로 유사한 일단의 토지 중에서 선정한다"},{"이름":"토지소유자 의견 청취","설명":"조사·평가할 때 해당 토지 소유자의 의견을 듣는다"},{"이름":"조사·평가","설명":"업무실적·신인도 등을 고려해 둘 이상의 감정평가법인등에 의뢰한다"},{"이름":"심의·공시","설명":"중앙부동산가격공시위원회의 심의를 거쳐 공시한다"},{"이름":"열람 및 이의신청","설명":"시장·군수·구청장을 통해 열람하게 하고, 공시일부터 30일 이내 이의신청을 받는다"}]}],"함정":"평가 의뢰 대상은 둘 이상의 감정평가법인등이다. 기관 이름을 바꿔 놓은 선지에 걸린다. 이의신청 기간 30일과 처리 기간 30일은 표준지·개별 모두 같다."},"34회-1차-042":{"한줄":"대리인이 자기 이익을 위해 배임적 행위를 하고 상대방도 이를 알았다면 제107조 제1항 단서가 유추되어 본인에게 효력이 없다.","근거":[{"법령":"민법","조문":"제107조","원문":"①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다."},{"판례":"대법원 판례(대리권 남용)","요지":"대리인이 자기나 제3자의 이익을 도모하려 대리권을 남용한 경우, 상대방이 이를 알았거나 알 수 있었으면 제107조 제1항 단서를 유추해 본인에게 효력이 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"매매계약 체결 권한이 있으면 특별한 사정이 없는 한 잔금 수령 권한도 있다."},{"번호":2,"판정":"옳음","설명":"해제권은 대리권의 범위에 당연히 포함되지 않는다."},{"번호":3,"판정":"옳음","설명":"계약의 당사자는 본인이므로 원상회복의무도 본인이 진다."},{"번호":4,"판정":"옳음","설명":"대리인은 계약 당사자가 아니어서 손해배상 책임의 상대방이 아니다."},{"번호":5,"판정":"틀림","설명":"상대방이 대리권 남용을 알았거나 알 수 있었으면 본인에게 효력이 없다."}],"개념":[{"종류":"표","제목":"대리권의 범위","머리":["유형","범위","비고"],"행":[["권한을 정하지 않은 대리인","보존행위, 이용·개량행위(제118조)","처분행위는 불가"],["매매 대리인","중도금·잔금 수령 가능","특별한 사정이 없는 한"],["계약 체결 대리인","해제권은 당연히 포함되지 않음","별도 수권 필요"],["대리권 남용","상대방 악의·과실 시 본인에게 무효","제107조 제1항 단서 유추"]]}],"함정":"5번에서 대리인이 권한 내에서 행위했으니 유효라고 생각하기 쉽다. 상대방이 배임 사실을 알면 효력이 없다."},"34회-1차-057":{"한줄":"전유부분의 면적 표시가 잘못된 경우 그 부분만 떼어 보존등기를 말소할 수 없다는 것이 판례다.","근거":[{"법령":"민법","조문":"제185조","원문":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지상권·전세권 등 권리도 저당권·권리질권의 객체가 된다."},{"번호":2,"판정":"틀림","설명":"규칙은 법률이 아니다(제185조)."},{"번호":3,"판정":"옳음","설명":"일부 면적 표시의 오류는 일부 말소의 대상이 되지 않는다."},{"번호":4,"판정":"틀림","설명":"1필 토지의 일부에도 지상권을 설정할 수 있다."},{"번호":5,"판정":"틀림","설명":"기술적 착오로 잘못 작성된 지적도는 경계 확정의 기준이 되지 않고 실제 경계를 따른다."}],"개념":[{"종류":"표","제목":"물권의 객체","머리":["구분","내용"],"행":[["원칙","독립한 특정의 물건(일물일권)"],["일부 객체","1필 토지의 일부에 지상권·지역권·전세권 설정 가능, 소유권은 불가"],["권리","지상권·전세권은 저당권의 객체, 권리질권"],["집합물","구성 부분 특정 가능하면 양도담보 가능"],["구분소유","전유부분 면적 오류만큼의 보존등기 일부 말소 불가"]]}],"함정":"4번의 토지 일부 지상권 불가는 일물일권 때문에 헷갈린다. 지상권은 토지 일부에도 설정된다."},"34회-1차-052":{"한줄":"합유자가 사망하면 합유지분은 상속되지 않고 잔존 합유자의 합유로 귀속된다.","근거":[{"법령":"민법","조문":"제271조","원문":"①법률의 규정 또는 계약에 의하여 수인이 조합체로서 물건을 소유하는 때에는 합유로 한다. 합유자의 권리는 합유물 전부에 미친다."},{"법령":"민법","조문":"제273조","원문":"①합유자는 전원의 동의없이 합유물에 대한 지분을 처분하지 못한다.\n②합유자는 합유물의 분할을 청구하지 못한다."},{"법령":"민법","조문":"제272조","원문":"합유물을 처분 또는 변경함에는 합유자 전원의 동의가 있어야 한다. 그러나 보존행위는 각자가 할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제271조 제1항."},{"번호":2,"판정":"옳음","설명":"제273조 제2항."},{"번호":3,"판정":"틀림","설명":"합유지분은 상속의 대상이 아니다. 특약이 없으면 잔존 합유자에게 귀속된다."},{"번호":4,"판정":"옳음","설명":"제272조 단서."},{"번호":5,"판정":"옳음","설명":"제273조 제1항."}],"개념":[{"종류":"표","제목":"공유·합유·총유 비교","머리":["구분","주체","지분 처분","물건 처분","분할","사망 시"],"행":[["공유","개인 간","자유","전원 동의","자유(제268조)","상속"],["합유","조합체","전원 동의","전원 동의","불가","잔존자에 귀속(상속 안 됨)"],["총유","법인 아닌 사단","지분 없음","사원총회 결의","없음","사원 지위 상실"]]}],"함정":"3번에서 합유자도 사망 시 상속된다고 생각하기 쉽다. 합유 지분은 상속되지 않는다."},"34회-1차-060":{"한줄":"요역지의 불법점유자는 통행지역권을 시효취득할 수 없다는 것이 판례다.","근거":[{"법령":"민법","조문":"제292조","원문":"②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제295조","원문":"①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다."},{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제292조 제2항."},{"번호":2,"판정":"옳음","설명":"제295조 제1항."},{"번호":3,"판정":"옳음","설명":"요역지의 존재는 지역권을 주장하는 자가 증명한다."},{"번호":4,"판정":"틀림","설명":"불법점유자는 요역지를 정당하게 이용하는 자가 아니라서 통행지역권을 시효취득하지 못한다."},{"번호":5,"판정":"옳음","설명":"제294조."}],"개념":[{"종류":"표","제목":"지역권 시효취득","머리":["요건","내용"],"행":[["객체","계속되고 표현된 지역권"],["통행지역권","요역지 소유자가 승역지에 통로를 개설하고 계속 통행"],["취득 주체","요역지의 소유자(불법점유자 제외)"],["공유","1인이 취득하면 전원 취득(제295조 제1항)"],["기간","제245조 준용(20년 점유 등)"]]}],"함정":"4번의 불법점유자 시효취득을 허용된다고 보기 쉽다. 정당한 이용권원이 없어서 불가하다."},"34회-1차-041":{"한줄":"임차인의 필요비상환청구권은 임대인에게 상환을 요구하는 청구권이고 일방적 의사표시로 법률관계를 바꾸는 형성권이 아니다.","근거":[{"법령":"민법","조문":"제626조제1항","원문":"①임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다."},{"법령":"민법","조문":"제450조제1항","원문":"①지명채권의 양도는 양도인이 채무자에게 통지하거나 채무자가 승낙하지 아니하면 채무자 기타 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제245조제1항","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."},{"법령":"민법","조문":"제131조","원문":"제131조(상대방의 최고권) 대리권없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인여부의 확답을 최고할 수 있다. 본인이 그 기간내에 확답을 발하지 아니한 때에는 추인을 거절한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"필요비 상환은 청구권(채권)이다(제626조 제1항). 형성권이 아니다."},{"번호":2,"판정":"옳음","설명":"지명채권 양도는 채권을 직접 처분하는 계약으로 준물권행위다."},{"번호":3,"판정":"옳음","설명":"매매로 소유권을 이전받는 것은 승계취득 중 개별 재산을 취득하는 특정승계다."},{"번호":4,"판정":"옳음","설명":"시효취득은 전 소유자의 권리를 승계하지 않는 원시취득이다(제245조 제1항)."},{"번호":5,"판정":"옳음","설명":"최고는 상대방에게 일정한 행위를 요구하는 의사의 통지다(제131조)."}],"개념":[{"종류":"표","제목":"형성권과 청구권","머리":["권리","성질","근거"],"행":[["취소권·해제권","형성권","제140조, 제543조"],["지상물매수청구권","형성권","제283조, 제643조"],["부속물매수청구권","형성권","제646조"],["지료증감청구권","형성권","제286조"],["필요비·유익비 상환청구권","청구권","제626조"]]},{"종류":"표","제목":"준법률행위의 유형","머리":["유형","예"],"행":[["의사의 통지","최고, 거절"],["관념의 통지","채권양도의 통지, 승낙연착의 통지, 채무의 승인"],["감정의 표시","용서 등"]]}],"함정":"1번의 형성권 연결이 맞다고 착각하기 쉽다. 같은 임대차에서 지상물매수청구권과 부속물매수청구권이 형성권이어서, 필요비 상환까지 형성권으로 묶어 외우는 경우가 많다. 필요비와 유익비의 상환은 형성권이 아니라 청구권이다."},"34회-2차-011":{"한줄":"이전신고서에는 중개사무소등록증(분사무소는 신고확인서)과 사무소 확보 서류를 첨부한다(칙 제11조 제1항).","근거":[{"법령":"공인중개사법","조문":"제20조 제1항 제3항","원문":"①개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다. 다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장(이하 이 조에서 \"이전후 등록관청\"이라 한다)에게 신고하여야 한다.\n③제1항 단서에 따른 신고 전에 발생한 사유로 인한 개업공인중개사에 대한 행정처분은 이전후 등록관청이 이를 행한다."},{"법령":"공인중개사법 시행규칙","조문":"제11조 제1항 제2항 제3항","원문":"①법 제20조제1항에 따라 중개사무소의 이전신고를 하려는 자는 별지 제12호서식의 중개사무소이전신고서에 다음 각 호의 서류를 첨부하여 등록관청(분사무소의 경우에는 주된 사무소의 소재지를 관할하는 등록관청을 말한다. 이하 이 조에서 같다)에 제출해야 한다.\n1. 중개사무소등록증(분사무소의 경우에는 분사무소설치신고확인서를 말한다)\n2. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)하였음을 증명하는 서류. 다만, 건축물대장에 기재되지 아니한 건물에 중개사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류도 함께 내야 한다.\n②제1항에 따라 중개사무소의 이전신고를 받은 등록관청은 그 내용이 적합한 경우에는 중개사무소등록증 또는 분사무소설치신고확인서를 재교부해야 한다. 다만, 개업공인중개사가 등록관청의 관할지역 내로 이전한 경우에는 등록관청은 중개사무소등록증 또는 분사무소설치신고확인서에 변경사항을 적어 교부할 수 있다.\n③등록관청은 분사무소의 이전신고를 받은 때에는 지체 없이 그 분사무소의 이전 전 및 이전 후의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제16조 제2항","원문":"② 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사는 법 제13조제6항 단서에 따라 다음 각 호의 어느 하나에 해당하는 방법으로 다른 개업공인중개사와 중개사무소를 공동으로 사용할 수 없다.\n1. 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사가 다른 개업공인중개사에게 중개사무소의 공동사용을 위하여 제1항에 따른 승낙서를 주는 방법. 다만, 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사가 영업정지 처분을 받기 전부터 중개사무소를 공동사용 중인 다른 개업공인중개사는 제외한다.\n2. 법 제39조에 따른 업무의 정지기간 중에 있는 개업공인중개사가 다른 개업공인중개사의 중개사무소를 공동으로 사용하기 위하여 중개사무소의 이전신고를 하는 방법"}],"선지":[{"번호":1,"판정":"옳음","설명":"관할 밖으로 옮기면 이전 후 등록관청에 신고한다(법 제20조 제1항 단서)."},{"번호":2,"판정":"옳음","설명":"이전신고를 했으면 지체 없이 간판을 철거한다(법 제21조의2 제1항 제1호)."},{"번호":3,"판정":"옳음","설명":"분사무소 이전신고는 주된 사무소 소재지 등록관청에 한다(칙 제11조 제1항)."},{"번호":4,"판정":"옳음","설명":"업무정지 중인 개업공인중개사는 이전신고로 다른 개업공인중개사의 사무소를 공동사용할 수 없다(영 제16조 제2항 제2호)."},{"번호":5,"판정":"틀림","설명":"공인중개사인 개업공인중개사든 법인이든 등록증(분사무소는 신고확인서)을 첨부한다(칙 제11조 제1항 제1호)."}],"개념":[{"종류":"표","제목":"중개사무소 이전신고 비교","머리":["구분","신고할 곳","첨부 서류","등록증 처리"],"행":[["관할 안 이전","종전 등록관청","등록증 + 사무소 확보 서류","재교부 또는 변경사항 적어 교부"],["관할 밖 이전","이전 후 등록관청","등록증 + 사무소 확보 서류","재교부, 종전 등록관청이 관련 서류 송부"],["분사무소 이전","주된 사무소 등록관청","신고확인서 + 사무소 확보 서류","신고확인서 재교부, 이전 전·후 소재지 시장·군수·구청장에게 통보"]]},{"종류":"표","제목":"이전신고 기타","머리":["항목","내용"],"행":[["기한","이전한 날부터 10일 이내"],["미신고","100만원 이하 과태료"],["행정처분","신고 전에 생긴 사유의 처분은 이전 후 등록관청"],["송부 서류","등록대장, 개설등록 신청서류, 최근 1년간 행정처분 관련 서류"]]}],"함정":"공인중개사 개인사무소는 서류가 간단할 것이라 짐작하기 쉽다. 개인·법인 구별 없이 등록증이 필수 첨부 서류다."},"34회-2차-024":{"한줄":"자격취소처분은 자격증을 교부한 시ㆍ도지사가 한다. 개설등록증을 교부한 기관은 등록관청이라 처분권자가 아니다.","근거":[{"법령":"공인중개사법 시행령","조문":"제29조 제1항 제2항","원문":"①법 제35조의 규정에 따른 공인중개사의 자격취소처분 및 법 제36조의 규정에 따른 자격정지처분은 그 공인중개사자격증(이하 \"자격증\"이라 한다)을 교부한 시ㆍ도지사가 행한다.\n②자격증을 교부한 시ㆍ도지사와 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 서로 다른 경우에는 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 자격취소처분 또는 자격정지처분에 필요한 절차를 모두 이행한 후 자격증을 교부한 시ㆍ도지사에게 통보하여야 한다."},{"법령":"공인중개사법","조문":"제35조 제1항 제3호","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n1. 부정한 방법으로 공인중개사의 자격을 취득한 경우\n2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)"},{"법령":"공인중개사법 시행규칙","조문":"제21조","원문":"제21조(공인중개사자격증의 반납) 법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법","조문":"제35조 제4항","원문":"④분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"자격취소와 자격정지는 그 공인중개사자격증을 교부한 시ㆍ도지사가 행한다(시행령 제29조제1항). 중개사무소 개설등록증은 등록관청이 교부한다."},{"번호":2,"판정":"옳음","설명":"자격정지 기간 중에 법인의 임원이 되는 경우도 중개업무를 행한 것에 포함되어 필요적 취소 사유다(법 제35조제1항제3호)."},{"번호":3,"판정":"옳음","설명":"자격취소처분을 받은 날부터 7일 이내에 자격증을 교부한 시ㆍ도지사에게 반납한다(시행규칙 제21조)."},{"번호":4,"판정":"옳음","설명":"처분 후 5일 이내에 국토교통부장관과 다른 시ㆍ도지사에게 통보한다(시행령 제29조제3항)."},{"번호":5,"판정":"옳음","설명":"분실처럼 반납할 수 없으면 사유서로 갈음한다(법 제35조제4항)."}],"개념":[{"종류":"표","제목":"자격취소 사유 4가지 (법 제35조제1항)","머리":["호","사유","특징"],"행":[["1","부정한 방법으로 공인중개사 자격 취득","-"],["2","다른 사람에게 자기 성명을 사용해 중개업무를 하게 하거나 자격증을 양도ㆍ대여","형사처벌: 1년 이하 징역 또는 1천만원 이하 벌금"],["3","자격정지처분을 받고 정지기간 중에 중개업무를 행함","다른 개업공인중개사의 소속공인중개사ㆍ중개보조원이 되거나 법인의 사원ㆍ임원이 되는 경우 포함"],["4","이 법 또는 직무와 관련해 형법 제114조, 제231조, 제234조, 제347조, 제355조, 제356조를 위반하여 금고 이상의 형을 선고받음","집행유예 포함"]]},{"종류":"표","제목":"반납ㆍ통보 기한과 관련 기관","머리":["대상","기한","상대방","근거"],"행":[["자격취소를 받은 자의 자격증 반납","처분을 받은 날부터 7일 이내","자격증을 교부한 시ㆍ도지사","시행규칙 제21조"],["등록취소를 받은 자의 등록증 반납","처분을 받은 날부터 7일 이내","등록관청","시행규칙 제24조제1항"],["자격증 분실 등 반납 불가","반납을 대신해 사유서 제출","시ㆍ도지사","법 제35조제4항"],["시ㆍ도지사의 자격취소 통보","처분을 한 때부터 5일 이내","국토교통부장관, 다른 시ㆍ도지사","시행령 제29조제3항"],["자격증 반납 불이행 과태료","100만원 이하, 시ㆍ도지사가 부과ㆍ징수","-","법 제51조제3항제6호ㆍ제5항제2호"]]}],"함정":"1번은 자격증과 개설등록증을 바꿔 쓴 문장이다. 자격 문제는 자격증을 교부한 시ㆍ도지사, 개설등록 문제는 등록관청으로 나눠 읽는다. 2번의 법인 임원이 되는 경우는 자격취소 사유 제3호의 괄호 안에 적혀 있다.","개정":"자격취소 후 통보 문언이 「국토교통부장관에게 보고」에서 「국토교통부장관과 다른 시ㆍ도지사에게 통보」로 정비되었다(시행령 제29조제3항, 2023.11.16.). 4번은 옳은 문장으로 유지된다."},"34회-2차-032":{"한줄":"최선순위 전세권은 매수인이 인수하는 것이 원칙이고, 전세권자가 배당요구를 하면 매각으로 소멸한다. 배당요구 없이 우선변제를 받는다는 말이 틀렸다.","근거":[{"법령":"민사집행법","조문":"제91조 제2항 제3항 제4항 제5항","원문":"②매각부동산 위의 모든 저당권은 매각으로 소멸된다.\n③지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 저당권ㆍ압류채권ㆍ가압류채권에 대항할 수 없는 경우에는 매각으로 소멸된다.\n④제3항의 경우 외의 지상권ㆍ지역권ㆍ전세권 및 등기된 임차권은 매수인이 인수한다. 다만, 그중 전세권의 경우에는 전세권자가 제88조에 따라 배당요구를 하면 매각으로 소멸된다.\n⑤매수인은 유치권자(留置權者)에게 그 유치권(留置權)으로 담보하는 채권을 변제할 책임이 있다."},{"법령":"민사집행법","조문":"제88조 제1항","원문":"①집행력 있는 정본을 가진 채권자, 경매개시결정이 등기된 뒤에 가압류를 한 채권자, 민법ㆍ상법, 그 밖의 법률에 의하여 우선변제청구권이 있는 채권자는 배당요구를 할 수 있다."},{"법령":"민사집행법","조문":"제84조 제1항","원문":"①경매개시결정에 따른 압류의 효력이 생긴 때(그 경매개시결정전에 다른 경매개시결정이 있은 경우를 제외한다)에는 집행법원은 절차에 필요한 기간을 고려하여 배당요구를 할 수 있는 종기(終期)를 첫 매각기일 이전으로 정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세권자는 배당요구를 해야 우선변제를 받고 그때 전세권이 소멸한다. 배당요구를 하지 않으면 매수인이 인수한다(민사집행법 제91조제4항 단서, 제88조제1항)."},{"번호":2,"판정":"옳음","설명":"매수인은 유치권자에게 유치권으로 담보하는 채권을 변제할 책임이 있다(제91조제5항). 경매개시결정 기입등기로 압류의 효력이 생기기 전에 취득한 유치권은 매수인에게 대항할 수 있고, 압류 효력 발생 후에 취득한 유치권은 대항할 수 없다는 것이 판례다."},{"번호":3,"판정":"옳음","설명":"저당권ㆍ압류ㆍ가압류에 대항할 수 있는 최선순위 지상권은 소멸하지 않고 매수인이 인수한다(제91조제4항)."},{"번호":4,"판정":"옳음","설명":"매각부동산 위의 모든 저당권은 매각으로 소멸한다(제91조제2항). 소멸주의가 적용되어 신청한 사람이 후순위여도 같다."},{"번호":5,"판정":"옳음","설명":"배당요구 종기는 첫 매각기일 이전으로 정한다(제84조제1항)."}],"개념":[{"종류":"표","제목":"경매에서 매수인이 인수하는 권리와 소멸하는 권리","머리":["권리","취급","근거"],"행":[["저당권","모두 매각으로 소멸","민사집행법 제91조제2항"],["지상권ㆍ지역권ㆍ전세권ㆍ등기된 임차권(저당권ㆍ압류ㆍ가압류에 대항할 수 없는 것)","소멸","제91조제3항"],["최선순위 지상권ㆍ지역권","매수인이 인수","제91조제4항"],["최선순위 전세권","인수가 원칙. 전세권자가 배당요구를 하면 소멸","제91조제4항 단서"],["유치권","매수인이 유치권으로 담보하는 채권을 변제할 책임을 짐. 압류 효력 발생 전에 취득한 유치권만 대항 가능(판례)","제91조제5항"],["대항력 있는 임차권(주택임대차보호법)","보증금이 모두 변제되지 않으면 소멸하지 않음","주택임대차보호법 제3조의5"]]},{"종류":"표","제목":"배당요구와 매수신청에 관한 절차 규정","머리":["항목","내용","근거"],"행":[["배당요구 종기 결정","압류 효력이 생긴 때 첫 매각기일 이전, 1주 이내에 결정 및 공고","제84조제1항ㆍ제3항"],["배당요구권자","집행력 있는 정본을 가진 채권자, 경매개시결정 등기 후 가압류채권자, 우선변제청구권이 있는 채권자","제88조제1항"],["배당요구 철회","매수인 인수 부담이 바뀌면 종기 후 철회 불가","제88조제2항"],["차순위매수신고","신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘을 때에 한함","제114조"],["소유권 취득","매각대금을 다 낸 때","제135조"]]}],"함정":"전세권과 지상권은 최선순위이면 인수가 원칙이라는 점은 같지만 전세권에만 배당요구에 따른 소멸 예외가 있다. 1번은 이 예외를 배당요구 없이도 소멸하는 것으로 넓혀 놓았다. 유치권은 기입등기 전에 취득했느냐가 대항 여부를 가른다."},"34회-2차-045":{"한줄":"시가화조정구역의 지정ㆍ변경은 법 제26조제1항이 정한 입안 제안 대상 사항에 들어 있지 않다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제26조제1항","원문":"주민(이해관계자를 포함한다. 이하 같다)은 다음 각 호의 사항에 대하여 제24조에 따라 도시ㆍ군관리계획을 입안할 수 있는 자에게 도시ㆍ군관리계획의 입안을 제안할 수 있다. 이 경우 제안서에는 도시ㆍ군관리계획도서와 계획설명서를 첨부하여야 한다. 1. 기반시설의 설치ㆍ정비 또는 개량에 관한 사항 2. 지구단위계획구역의 지정 및 변경과 지구단위계획의 수립 및 변경에 관한 사항 3. 다음 각 목의 어느 하나에 해당하는 용도지구의 지정 및 변경에 관한 사항 가. 개발진흥지구 중 공업기능 또는 유통물류기능 등을 집중적으로 개발ㆍ정비하기 위한 개발진흥지구로서 대통령령으로 정하는 개발진흥지구 나. 제37조에 따라 지정된 용도지구 중 해당 용도지구에 따른 건축물이나 그 밖의 시설의 용도ㆍ종류 및 규모 등의 제한을 지구단위계획으로 대체하기 위한 용도지구 5. 도시ㆍ군계획시설입체복합구역의 지정 및 변경과 도시ㆍ군계획시설입체복합구역의 건축제한ㆍ건폐율ㆍ용적률ㆍ높이 등에 관한 사항"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제19조의2제1항","원문":"법 제26조제1항제3호가목에서 \"대통령령으로 정하는 개발진흥지구\"란 제31조제2항제8호나목에 따른 산업ㆍ유통개발진흥지구를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"도시ㆍ군계획시설입체복합구역의 지정ㆍ변경과 건축제한ㆍ건폐율ㆍ용적률ㆍ높이 등은 제안 대상이다(법 제26조제1항제5호)."},{"번호":2,"판정":"옳음","설명":"지구단위계획구역의 지정ㆍ변경과 지구단위계획의 수립ㆍ변경은 제안 대상이다(법 제26조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"기반시설의 설치ㆍ정비 또는 개량은 제안 대상이다(법 제26조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"산업ㆍ유통개발진흥지구는 제안 대상 용도지구의 하나이고, 지정뿐 아니라 변경도 제안할 수 있다(법 제26조제1항제3호가목, 영 제19조의2제1항)."},{"번호":5,"판정":"틀림","설명":"시가화조정구역의 지정ㆍ변경은 도시ㆍ군관리계획 내용(법 제2조제4호나목)이지만 주민이 입안을 제안할 수 있는 사항으로 열거되어 있지 않다(법 제26조제1항)."}],"개념":[{"종류":"표","제목":"주민의 도시ㆍ군관리계획 입안 제안 대상(법 제26조제1항)","머리":["호","제안 가능 사항","동의 요건(영 제19조의2제2항)"],"행":[["제1호","기반시설의 설치ㆍ정비 또는 개량","토지 면적 5분의 4 이상"],["제2호","지구단위계획구역의 지정ㆍ변경, 지구단위계획의 수립ㆍ변경","토지 면적 3분의 2 이상"],["제3호가목","산업ㆍ유통개발진흥지구의 지정ㆍ변경","토지 면적 3분의 2 이상"],["제3호나목","지구단위계획으로 제한을 대체하는 용도지구의 지정ㆍ변경","토지 면적 3분의 2 이상"],["제4호","삭제(입지규제최소구역, 2024.2.6)","-"],["제5호","도시ㆍ군계획시설입체복합구역의 지정ㆍ변경과 건축제한 등","토지 면적 5분의 4 이상"],["제안 불가","시가화조정구역, 용도지역, 개발제한구역 등","-"]]},{"종류":"흐름","제목":"입안 제안의 처리","단계":[{"이름":"제안","설명":"제안서에 도시ㆍ군관리계획도서와 계획설명서 첨부(법 제26조제1항)"},{"이름":"검토","설명":"필요하면 중앙 또는 지방도시계획위원회 자문(영 제20조제2항)"},{"이름":"통보","설명":"제안일부터 45일 이내 반영 여부 통보, 부득이하면 1회 30일 연장(영 제20조제1항)"},{"이름":"비용 부담","설명":"제안자와 협의해 입안ㆍ결정 비용의 전부 또는 일부를 제안자에게 부담시킬 수 있음(법 제26조제3항)"}]}],"함정":"입지규제최소구역이 삭제된 뒤 제안 대상은 입체복합구역으로 바뀌었다. 용도구역 가운데 제안할 수 있는 것은 입체복합구역뿐이고, 시가화조정구역을 같은 용도구역으로 묶어 제안 대상으로 착각하기 쉽다.","개정":"씨앗 선지 1의 ‘입지규제최소구역의 지정 및 변경과 입지규제최소구역계획의 수립 및 변경’은 2024.2.6 개정으로 법 제26조제1항제4호와 제40조의2가 삭제되어 제안 대상이 아니다. 이대로 두면 선지 1도 제안할 수 없는 사항이 되어 정답이 둘이 되므로, 후신 제도인 도시ㆍ군계획시설입체복합구역(법 제26조제1항제5호)으로 고쳤다. 정답은 5번 그대로다."},"34회-2차-044":{"한줄":"도시지역 안에서 복합적 토지 이용을 증진할 지구단위계획구역은 일반주거ㆍ준주거ㆍ준공업ㆍ상업지역에서만 지정할 수 있어 일반공업지역은 들어가지 않는다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제1항제6호ㆍ제8호의2","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 어느 하나에 해당하는 지역의 전부 또는 일부에 대하여 지구단위계획구역을 지정할 수 있다. 6. 「산업입지 및 개발에 관한 법률」 제2조제8호의 산업단지와 같은 조 제12호의 준산업단지 8의2. 도시지역 내 주거ㆍ상업ㆍ업무 등의 기능을 결합하는 등 복합적인 토지 이용을 증진시킬 필요가 있는 지역으로서 대통령령으로 정하는 요건에 해당하는 지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제43조제1항","원문":"법 제51조제1항제8호의2에서 \"대통령령으로 정하는 요건에 해당하는 지역\"이란 일반주거지역, 준주거지역, 준공업지역 및 상업지역에서 낙후된 도심 기능을 회복하거나 도시균형발전을 위한 중심지 육성이 필요한 경우로서 다음 각 호의 어느 하나에 해당하는 지역을 말한다. 1. 주요 역세권, 고속버스 및 시외버스 터미널, 간선도로의 교차지 등 양호한 기반시설을 갖추고 있어 대중교통 이용이 용이한 지역 2. 역세권의 체계적ㆍ계획적 개발이 필요한 지역 3. 세 개 이상의 노선이 교차하는 대중교통 결절지(結節地)로부터 1킬로미터 이내에 위치한 지역 4. 「역세권의 개발 및 이용에 관한 법률」에 따른 역세권개발구역, 「도시재정비 촉진을 위한 특별법」에 따른 고밀복합형 재정비촉진지구로 지정된 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제2항제1호","원문":"국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 어느 하나에 해당하는 지역은 지구단위계획구역으로 지정하여야 한다. 다만, 관계 법률에 따라 그 지역에 토지 이용과 건축에 관한 계획이 수립되어 있는 경우에는 그러하지 아니하다. 1. 제1항제3호 및 제4호의 지역에서 시행되는 사업이 끝난 후 10년이 지난 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제51조제3항제1호ㆍ제2호","원문":"도시지역 외의 지역을 지구단위계획구역으로 지정하려는 경우 다음 각 호의 어느 하나에 해당하여야 한다. 1. 지정하려는 구역 면적의 100분의 50 이상이 제36조에 따라 지정된 계획관리지역으로서 대통령령으로 정하는 요건에 해당하는 지역 2. 제37조에 따라 지정된 개발진흥지구로서 대통령령으로 정하는 요건에 해당하는 지역"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제44조제2항","원문":"법 제51조제3항제2호에서 \"대통령령으로 정하는 요건\"이란 다음 각 호의 요건을 말한다. 1. 제1항제2호부터 제4호까지의 요건에 해당할 것 2. 당해 개발진흥지구가 다음 각 목의 지역에 위치할 것 가. 주거개발진흥지구, 복합개발진흥지구(주거기능이 포함된 경우에 한한다) 및 특정개발진흥지구 : 계획관리지역 나. 산업ㆍ유통개발진흥지구 및 복합개발진흥지구(주거기능이 포함되지 아니한 경우에 한한다) : 계획관리지역ㆍ생산관리지역 또는 농림지역 다. 관광ㆍ휴양개발진흥지구 : 도시지역외의 지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"산업입지법상 산업단지와 준산업단지는 지구단위계획구역으로 지정할 수 있는 지역이다(법 제51조제1항제6호)."},{"번호":2,"판정":"옳음","설명":"복합적 토지 이용 증진이 필요한 지역은 일반주거지역, 준주거지역, 준공업지역 및 상업지역에 한한다. 일반공업지역은 해당하지 않는다(법 제51조제1항제8호의2, 영 제43조제1항)."},{"번호":3,"판정":"틀림","설명":"택지개발지구와 정비구역은 사업이 끝난 뒤 10년이 지나면 지정하여야 한다. 5년이 아니다(법 제51조제2항제1호)."},{"번호":4,"판정":"틀림","설명":"도시지역 외에서는 지정하려는 구역 면적의 100분의 50 이상이 계획관리지역이어야 한다(법 제51조제3항제1호). 3분의 2가 아니다."},{"번호":5,"판정":"틀림","설명":"산업ㆍ유통개발진흥지구는 계획관리지역ㆍ생산관리지역 또는 농림지역에 있으면 지정 대상이다(법 제51조제3항제2호, 영 제44조제2항제2호나목)."}],"개념":[{"종류":"표","제목":"지구단위계획구역 지정 대상(법 제51조)","머리":["구분","대상","근거"],"행":[["임의 지정(도시지역)","용도지구, 도시개발구역, 정비구역, 택지개발지구, 대지조성사업지구, 산업단지ㆍ준산업단지, 관광단지ㆍ관광특구","제1항제1호~제7호"],["임의 지정(도시지역)","개발제한구역 등에서 해제되는 구역, 복합적 토지 이용이 필요한 지역(제8호의2), 유휴토지ㆍ이전 시설 정비 지역(제8호의3)","제1항제8호~제8호의3"],["의무 지정","정비구역ㆍ택지개발지구에서 사업이 끝난 후 10년이 지난 지역","제2항제1호"],["의무 지정","제1항 각 호 중 체계적 관리가 필요한 지역으로 영이 정한 지역(30만제곱미터 이상 등)","제2항제2호, 영 제43조제5항"],["도시지역 외","구역 면적의 100분의 50 이상이 계획관리지역, 개발진흥지구, 용도지구를 폐지하고 지구단위계획으로 대체하는 지역","제3항"]]},{"종류":"표","제목":"도시지역 외 지구단위계획구역의 요건(영 제44조)","머리":["구분","요건"],"행":[["면적(아파트ㆍ연립 건설계획 포함)","30만제곱미터 이상(자연보전권역이거나 초등학교 용지를 확보하는 등 일정한 경우 10만제곱미터 이상)"],["면적(그 밖)","3만제곱미터 이상"],["산업ㆍ유통개발진흥지구","계획관리지역ㆍ생산관리지역 또는 농림지역"],["주거개발진흥지구","계획관리지역"],["관광ㆍ휴양개발진흥지구","도시지역 외의 지역"]]}],"함정":"시기 숫자는 사업 종료 후 10년이고 면적 비율은 100분의 50이다. 선지 3과 4는 이 숫자를 5년과 3분의 2로 바꾸어 놓았다. 선지 5는 산업ㆍ유통개발진흥지구의 지정 대상 지역에 농림지역이 포함된다는 점(영 제44조제2항제2호나목)을 묻는다. 이 문항의 정답률은 15퍼센트였다."},"34회-2차-057":{"한줄":"구역 지정 후에 개발계획에 포함할 수 있는 사항은 제13호~제16호이고, 임대주택건설계획 등 세입자 주거ㆍ생활 안정 대책이 그중 하나다.","근거":[{"법령":"도시개발법","조문":"제5조제1항","원문":"개발계획에는 다음 각 호의 사항이 포함되어야 한다. 다만, 제13호부터 제16호까지의 규정에 해당하는 사항은 도시개발구역을 지정한 후에 개발계획에 포함시킬 수 있다. 3. 제3조의2에 따라 도시개발구역을 둘 이상의 사업시행지구로 분할하거나 서로 떨어진 둘 이상의 지역을 하나의 구역으로 결합하여 도시개발사업을 시행하는 경우에는 그 분할이나 결합에 관한 사항 7의2. 제25조의2에 따라 원형지로 공급될 대상 토지 및 개발 방향 9. 환경보전계획 10. 보건의료시설 및 복지시설의 설치계획 13. 도시개발구역 밖의 지역에 기반시설을 설치하여야 하는 경우에는 그 시설의 설치에 필요한 비용의 부담 계획 14. 수용(收用) 또는 사용의 대상이 되는 토지ㆍ건축물 또는 토지에 정착한 물건과 이에 관한 소유권 외의 권리, 광업권, 어업권, 양식업권, 물의 사용에 관한 권리(이하 \"토지등\"이라 한다)가 있는 경우에는 그 세부목록 15. 임대주택건설계획 등 세입자 등의 주거 및 생활 안정 대책 16. 제21조의2에 따른 순환개발 등 단계적 사업추진이 필요한 경우 사업추진 계획 등에 관한 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"환경보전계획은 제9호 사항이어서 구역을 지정할 때 개발계획에 담아야 한다(법 제5조제1항제9호)."},{"번호":2,"판정":"틀림","설명":"보건의료시설 및 복지시설의 설치계획은 제10호 사항으로 구역 지정 때 포함한다(법 제5조제1항제10호)."},{"번호":3,"판정":"틀림","설명":"원형지로 공급될 대상 토지 및 개발 방향은 제7호의2 사항으로 구역 지정 때 포함한다(법 제5조제1항제7호의2)."},{"번호":4,"판정":"옳음","설명":"임대주택건설계획 등 세입자 등의 주거 및 생활 안정 대책은 제15호 사항이어서 구역 지정 후에 포함할 수 있다(법 제5조제1항 단서)."},{"번호":5,"판정":"틀림","설명":"구역을 둘 이상의 사업시행지구로 분할하거나 결합하는 사항은 제3호 사항으로 구역 지정 때 포함한다(법 제5조제1항제3호)."}],"개념":[{"종류":"표","제목":"개발계획 포함사항의 시기(법 제5조제1항)","머리":["시기","호","내용"],"행":[["구역 지정 때 포함","제1호~제12호","명칭ㆍ위치ㆍ면적, 지정 목적과 시행기간, 분할ㆍ결합, 시행자, 시행방식, 인구수용계획, 토지이용계획, 원형지, 교통처리, 환경보전, 보건의료ㆍ복지시설, 기반시설, 재원조달"],["구역 지정 후 포함 가능","제13호","구역 밖 기반시설 설치 비용 부담 계획"],["구역 지정 후 포함 가능","제14호","수용 또는 사용 대상 토지등의 세부목록"],["구역 지정 후 포함 가능","제15호","임대주택건설계획 등 세입자 등의 주거ㆍ생활 안정 대책"],["구역 지정 후 포함 가능","제16호","순환개발 등 단계적 사업추진 계획"],["대통령령 사항","제17호","학교시설계획, 국가유산 보호계획, 공동구 등 지하매설물계획 등(영 제8조제1항)"]]},{"종류":"표","제목":"개발계획을 구역 지정 후에 수립하는 경우(법 제4조, 제5조제3항, 영 제9조)","머리":["구분","내용"],"행":[["사유","개발계획안을 공모하거나 대통령령으로 정하는 지역에 구역을 지정하는 경우(법 제4조제1항 단서)"],["지정 때 정할 계획","구역의 명칭ㆍ위치ㆍ면적, 지정 목적, 시행방식, 시행자, 개략적 인구수용계획, 개략적 토지이용계획(영 제9조제1항)"],["환지 방식의 동의","환지 방식이 적용되는 토지 면적의 3분의 2 이상 토지소유자와 소유자 총수의 2분의 1 이상(법 제4조제4항)"],["대규모 구역","330만제곱미터 이상이면 주거ㆍ생산ㆍ교육ㆍ유통ㆍ위락 등 기능이 조화되도록 노력(영 제9조제3항)"]]}],"함정":"지정 후에 넣을 수 있는 호는 마지막 네 개(제13호~제16호)다. 선지 5의 구역 분할(제3호)과 제16호의 단계적 사업추진은 둘 다 사업을 나누는 내용이라 구분이 어렵지만, 분할은 지정 때 정하고 단계적 추진 계획만 지정 후에 넣는다."},"34회-2차-056":{"한줄":"시행자가 주택건설사업자 등에게 대행시킬 수 있는 범위는 실시설계, 부지조성공사, 기반시설공사, 조성된 토지의 분양 네 가지뿐이어서 토지상환채권 발행은 대행 대상이 아니다.","근거":[{"법령":"도시개발법","조문":"제11조제11항","원문":"제1항제1호부터 제4호까지의 규정에 해당하는 자는 도시개발사업을 효율적으로 시행하기 위하여 필요한 경우에는 대통령령으로 정하는 바에 따라 설계ㆍ분양 등 도시개발사업의 일부를 「주택법」 제4조에 따른 주택건설사업자 등으로 하여금 대행하게 할 수 있다."},{"법령":"도시개발법 시행령","조문":"제25조의2제1항","원문":"법 제11조제11항에 따라 주택건설사업자 등에게 대행하게 할 수 있는 도시개발사업의 범위는 다음 각 호와 같다. 1. 실시설계 2. 부지조성공사 3. 기반시설공사 4. 조성된 토지의 분양"},{"법령":"도시개발법","조문":"제23조제1항","원문":"시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(이하 \"토지상환채권\"이라 한다)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"실시설계는 대행 범위다(영 제25조의2제1항제1호)."},{"번호":2,"판정":"옳음","설명":"부지조성공사는 대행 범위다(영 제25조의2제1항제2호)."},{"번호":3,"판정":"옳음","설명":"기반시설공사는 대행 범위다(영 제25조의2제1항제3호)."},{"번호":4,"판정":"옳음","설명":"조성된 토지의 분양은 대행 범위다(영 제25조의2제1항제4호)."},{"번호":5,"판정":"틀림","설명":"토지상환채권은 시행자가 발행하고(법 제23조제1항), 영 제25조의2제1항의 대행 범위에 들어 있지 않다."}],"개념":[{"종류":"흐름","제목":"도시개발사업의 대행(법 제11조제11항, 영 제25조의2)","단계":[{"이름":"대행 주체","설명":"시행자 중 국가ㆍ지방자치단체, 대통령령으로 정한 공공기관, 정부출연기관, 지방공사(법 제11조제1항제1호~제4호)"},{"이름":"대행 범위","설명":"실시설계, 부지조성공사, 기반시설공사, 조성된 토지의 분양(영 제25조의2제1항)"},{"이름":"공고","설명":"개발사업의 목적ㆍ종류ㆍ시행기간, 대행개발사업자의 자격요건ㆍ선정기준 등을 공고(영 제25조의2제2항)"},{"이름":"선정","설명":"경쟁입찰 방식으로 대행개발사업자 선정(영 제25조의2제2항)"},{"이름":"계약","설명":"대행에 관한 계약 체결(영 제25조의2제3항)"}]},{"종류":"표","제목":"도시개발사업의 시행자(법 제11조제1항)","머리":["호","시행자"],"행":[["제1호~제4호","국가ㆍ지방자치단체, 대통령령으로 정하는 공공기관, 정부출연기관, 지방공사"],["제5호","도시개발구역의 토지 소유자"],["제6호","토지 소유자가 설립한 조합(사업 전부를 환지 방식으로 시행하는 경우만)"],["제7호~제8호","과밀억제권역에서 이전하는 법인, 주택법에 따라 등록한 주택건설사업자"],["제9호ㆍ제9호의2","토목공사업 등 시행능력이 있는 자, 등록 부동산개발업자"],["제10호ㆍ제11호","부동산투자회사, 시행자가 출자해 설립한 법인"],["토지상환채권(법 제23조)","시행자가 발행, 제5호~제11호의 시행자는 지급보증을 받은 경우에만 발행, 발행계획은 지정권자 승인"]]}],"함정":"대행 범위는 열거된 네 가지로 한정된다. 분양까지 맡길 수 있다는 점과, 채권 발행처럼 자금 조달에 속하는 일은 시행자가 직접 한다는 점을 구분해야 한다."},"34회-2차-066":{"한줄":"사업주체가 파산 등으로 사용검사를 받을 수 없을 때 대신 받을 수 있는 자는 시공보증자 또는 입주예정자이고, 시공자는 들어가지 않는다.","근거":[{"법령":"주택법","조문":"제49조제3항","원문":"제1항에도 불구하고 다음 각 호의 구분에 따라 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자는 대통령령으로 정하는 바에 따라 사용검사를 받을 수 있다. 1. 사업주체가 파산 등으로 사용검사를 받을 수 없는 경우에는 해당 주택의 시공을 보증한 자 또는 입주예정자 2. 사업주체가 정당한 이유 없이 사용검사를 위한 절차를 이행하지 아니하는 경우에는 해당 주택의 시공을 보증한 자, 해당 주택의 시공자 또는 입주예정자 …"},{"법령":"주택법 시행령","조문":"제54조제2항·제4항","원문":"법 제49조제1항 단서에서 … 2. 하나의 주택단지의 입주자를 분할 모집하여 전체 단지의 사용검사를 마치기 전에 입주가 필요한 경우 … / 제3항에 따른 사용검사는 신청일부터 15일 이내에 하여야 한다."},{"법령":"주택법 시행령","조문":"제56조제1항제1호","원문":"법 제49조제4항 단서에서 \"대통령령으로 정하는 경우\"란 다음 각 호의 구분에 따른 경우를 말한다. 1. 주택건설사업의 경우: 건축물의 동별로 공사가 완료된 경우"},{"법령":"주택법","조문":"제50조제1항","원문":"제49조제3항에 따라 사업주체의 파산 등으로 입주예정자가 사용검사를 받을 때에는 「공동주택관리법」 제38조제1항에도 불구하고 입주예정자의 대표회의가 사용검사권자에게 사용검사를 신청할 때 하자보수보증금을 예치하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"입주자를 분할 모집해 전체 사용검사 전 입주가 필요한 경우는 동별 사용검사 사유다(영 제54조제2항제2호)."},{"번호":2,"판정":"옳음","설명":"사용검사는 신청일부터 15일 이내에 한다(영 제54조제4항)."},{"번호":3,"판정":"옳음","설명":"동별 공사 완료 시 임시 사용승인을 받으면 사용검사 전에 사용하게 할 수 있다(법 제49조제4항, 영 제56조제1항제1호)."},{"번호":4,"판정":"틀림","설명":"사업주체의 파산 등에는 시공보증자 또는 입주예정자만 사용검사를 받을 수 있다. 시공자까지 들어가는 경우는 사업주체가 정당한 이유 없이 절차를 이행하지 않을 때다(법 제49조제3항제1호·제2호)."},{"번호":5,"판정":"옳음","설명":"입주예정자 대표회의가 사용검사를 신청할 때 하자보수보증금을 예치한다(법 제50조제1항)."}],"개념":[{"종류":"표","제목":"사용검사 정리","머리":["항목","내용","조문"],"행":[["원칙","사업계획승인 사업을 완료하면 시장·군수·구청장의 사용검사(국가·한국토지주택공사 사업 등은 국토교통부장관)","법 제49조제1항"],["분할 사용검사","공구별 분할 승인을 받은 경우 완공된 주택에 공구별로","법 제49조제1항 단서"],["동별 사용검사","승인조건 미이행, 입주자 분할 모집 후 전체 사용검사 전 입주 필요, 승인권자가 필요하다고 인정","영 제54조제2항"],["검사 기한·확인","신청일부터 15일 이내. 사업계획 적합 여부와 사용검사 전 조치할 하자 조치 여부 확인","영 제54조제3항·제4항"],["사용검사 전 사용","금지. 동별 공사 완료 + 임시 사용승인(공동주택은 세대별도 가능)이면 예외","법 제49조제4항, 영 제56조"],["사업주체 파산 등","시공보증자 또는 입주예정자가 사용검사","법 제49조제3항제1호"],["정당한 이유 없는 미이행","시공보증자·시공자·입주예정자가 사용검사. 사용검사권자는 사업주체에게 이유 제출 요청, 사업주체는 7일 이내 의견 통지","법 제49조제3항제2호, 영 제55조제4항"],["입주예정자 사용검사 시","입주예정자 대표회의가 신청 시 하자보수보증금 예치","법 제50조제1항"]]},{"종류":"흐름","제목":"사업주체 파산 시 사용검사","단계":[{"이름":"사업주체 파산 등","설명":"주택건설사업을 계속할 수 없는 상태(영 제55조제1항)"},{"이름":"시공보증자 시공","설명":"시공보증자가 잔여공사를 시공하고 사용검사를 받음(영 제55조제1항 본문)"},{"이름":"보증자 부재","설명":"시공보증자가 없거나 파산 등으로 시공할 수 없으면 입주예정자 대표회의가 시공자를 정해 잔여공사를 시공하고 사용검사(영 제55조제1항 단서)"},{"이름":"하자보수보증금 예치","설명":"입주예정자 대표회의가 신청할 때 예치(법 제50조제1항)"},{"이름":"명의 등재","설명":"시공보증자 또는 세대별 입주자 명의로 건축물관리대장 등재, 소유권보존등기 가능(영 제55조제2항)"}]}],"함정":"사업주체 파산 때 사용검사를 받는 자는 시공보증자·입주예정자이고, 시공자는 정당한 이유 없이 절차를 이행하지 않는 경우에만 들어간다. 15일 이내 검사, 동별 임시 사용승인은 맞는 문장이다."},"34회-2차-088":{"한줄":"확정공고에는 지역별 제곱미터당 금액조서가 들어가지 않는다. 포함 사항은 토지의 소재 및 지역명, 축척변경 지번별 조서, 청산금 조서, 지적도의 축척 네 가지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제1항","원문":"① 영 제78조제1항에 따른 축척변경의 확정공고에는 다음 각 호의 사항이 포함되어야 한다. 1. 토지의 소재 및 지역명 2. 영 제73조에 따른 축척변경 지번별 조서 3. 영 제75조제4항에 따른 청산금 조서 4. 지적도의 축척"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조","원문":"① 청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다. ② 지적소관청은 제1항에 따른 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다. ③ 축척변경 시행지역의 토지는 제1항에 따른 확정공고일에 토지의 이동이 있는 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"토지의 소재 및 지역명은 확정공고 사항이다(규칙 제92조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"축척변경 지번별 조서는 확정공고 사항이다(규칙 제92조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"청산금 조서는 확정공고 사항이다(규칙 제92조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"지적도의 축척은 확정공고 사항이다(규칙 제92조제1항제4호)."},{"번호":5,"판정":"틀림","설명":"제곱미터당 금액은 축척변경위원회 의결로 지번별로 정해 청산금 산정에 쓴다(영 제75조제2항). 이를 정리한 조서는 확정공고 사항 네 가지에 들지 않는다."}],"개념":[{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"승인 신청","설명":"소유자 3분의 2 이상 동의와 위원회 의결을 거쳐 시·도지사 또는 대도시 시장에게 승인 신청(법 제83조제3항, 영 제70조)"},{"이름":"시행공고","설명":"승인을 받으면 지체 없이 20일 이상 공고(영 제71조제1항)"},{"이름":"경계점표지 설치","설명":"토지소유자·점유자가 시행공고일부터 30일 이내 점유 경계에 설치(영 제71조제3항)"},{"이름":"측량과 지번별 조서","설명":"새 축척으로 지번·지목·면적·경계 또는 좌표를 정하고, 시행공고일 현재 면적과 측량 후 면적을 비교한 지번별 조서 작성(영 제72조, 제73조)"},{"이름":"청산금 산정·공고","설명":"위원회 의결로 지번별 제곱미터당 금액 결정, 청산금 조서 작성, 15일 이상 공고(영 제75조)"},{"이름":"납부고지·수령통지","설명":"공고한 날부터 20일 이내, 납부는 고지받은 날부터 6개월 이내, 지급은 통지한 날부터 6개월 이내(영 제76조)"},{"이름":"이의신청","설명":"납부고지·수령통지를 받은 날부터 1개월 이내, 위원회 심의를 거쳐 1개월 이내 결정(영 제77조)"},{"이름":"확정공고","설명":"청산금 납부·지급 완료 후 지체 없이 확정공고, 지적공부 등록, 확정공고일에 토지의 이동이 있는 것으로 봄(영 제78조)"}]},{"종류":"표","제목":"축척변경 확정공고 사항","머리":["확정공고에 포함","확정공고에 포함되지 않음"],"행":[["토지의 소재 및 지역명","지번별 제곱미터당 금액조서"],["축척변경 지번별 조서","축척변경 시행계획"],["청산금 조서","축척변경 승인신청서"],["지적도의 축척","토지소유자 동의서"]]}],"함정":"청산금 조서와 제곱미터당 금액조서는 둘 다 청산금 서류라 한 묶음으로 보인다. 확정공고에 들어가는 서류는 청산금 조서까지다."},"34회-2차-099":{"한줄":"가등기에 의한 본등기는 가등기의 순위번호를 사용하여 하므로 가등기를 말소하는 표시를 하지 않는다.","근거":[{"법령":"부동산등기규칙","조문":"제146조","원문":"가등기를 한 후 본등기의 신청이 있을 때에는 가등기의 순위번호를 사용하여 본등기를 하여야 한다."},{"법령":"부동산등기법","조문":"제91조","원문":"가등기에 의한 본등기(本登記)를 한 경우 본등기의 순위는 가등기의 순위에 따른다."},{"법령":"부동산등기법","조문":"제88조","원문":"가등기는 제3조 각 호의 어느 하나에 해당하는 권리의 설정, 이전, 변경 또는 소멸의 청구권(請求權)을 보전(保全)하려는 때에 한다. 그 청구권이 시기부(始期附) 또는 정지조건부(停止條件附)일 경우나 그 밖에 장래에 확정될 것인 경우에도 같다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제88조가 가등기를 허용하는 청구권은 시기부·정지조건부·장래 확정될 청구권이다. 해제조건부 청구권은 이미 효력이 발생한 청구권이어서 가등기 대상이 아니다."},{"번호":2,"판정":"옳음","설명":"소유권이전청구권 가등기는 주등기로 한다. 부기로 하는 등기는 법 제52조에 열거된 소유권 외의 권리에 관한 등기 등이다."},{"번호":3,"판정":"옳음","설명":"원칙대로 권리자와 의무자가 공동으로 신청한다(법 제23조제1항). 승낙이나 가처분명령이 있으면 권리자 단독신청도 가능하다(법 제89조)."},{"번호":4,"판정":"옳음","설명":"가등기에 기한 본등기를 금지하는 가처분은 등기할 사항이 아니므로 각하한다(법 제29조제2호)."},{"번호":5,"판정":"틀림","설명":"본등기는 가등기의 순위번호를 사용해서 하고, 그 순위는 가등기의 순위에 따른다. 가등기 말소 표시는 하지 않는다(규칙 제146조, 법 제91조)."}],"개념":[{"종류":"표","제목":"가등기 대상 청구권","머리":["청구권","가등기 가능 여부","비고"],"행":[["시기부 청구권","가능","법 제88조"],["정지조건부 청구권","가능","법 제88조"],["장래 확정될 청구권","가능","법 제88조"],["해제조건부 청구권","불가","현재 효력이 있는 청구권"],["소유권 외 권리의 이전청구권(임차권 등)","가능","제3조 각 호의 권리"]]},{"종류":"흐름","제목":"가등기에서 본등기까지","단계":[{"이름":"가등기 신청","설명":"권리자와 의무자 공동신청. 의무자 승낙이나 가처분명령이 있으면 권리자 단독(법 제23조제1항, 제89조)"},{"이름":"가등기 기록","설명":"소유권이전청구권 가등기는 주등기로 기록"},{"이름":"본등기 신청","설명":"가등기의 순위번호를 사용하여 본등기(규칙 제146조)"},{"이름":"직권말소","설명":"가등기 후 본등기 전에 마쳐진 침해 등기를 말소하고 말소한 뜻을 기록(법 제92조, 규칙 제149조)"}]}],"함정":"선지 5 가 정답이다. 본등기 후 가등기가 말소 표시되어 없어질 것으로 생각하기 쉽다. 본등기는 가등기의 순위번호로 하며, 말소 표시를 하는 대상은 가등기 후 본등기 전에 마쳐진 침해 등기다."},"34회-2차-105":{"한줄":"감사원법에 따른 심사청구 결정으로 명의대여 사실이 확인되면, 결정이 확정된 날부터 1년 이내에 당초 처분을 취소하고 실제 경영자에게 경정 등을 할 수 있다.","근거":[{"법령":"국세기본법","조문":"제26조의2제7항","원문":"⑦ 제1항부터 제5항까지의 규정에도 불구하고 제6항제1호의 결정 또는 판결에 의하여 다음 각 호의 어느 하나에 해당하게 된 경우에는 당초의 부과처분을 취소하고 그 결정 또는 판결이 확정된 날부터 1년 이내에 다음 각 호의 구분에 따른 자에게 경정이나 그 밖에 필요한 처분을 할 수 있다."},{"법령":"국세기본법","조문":"제26조의2제7항제1호","원문":"1. 명의대여 사실이 확인된 경우: 실제로 사업을 경영한 자"},{"법령":"국세기본법","조문":"제26조의2제6항제1호","원문":"1. 제7장에 따른 이의신청, 심사청구, 심판청구, 「감사원법」에 따른 심사청구 또는 「행정소송법」에 따른 소송에 대한 결정이나 판결이 확정된 경우: 결정 또는 판결이 확정된 날부터 1년"},{"법령":"국세기본법","조문":"제26조의2제2항제1호","원문":"1. 납세자가 법정신고기한까지 과세표준신고서를 제출하지 아니한 경우: 해당 국세를 부과할 수 있는 날부터 7년(역외거래의 경우 10년)"},{"법령":"국세기본법","조문":"제26조의2제2항제2호","원문":"2. 납세자가 대통령령으로 정하는 사기나 그 밖의 부정한 행위(이하 \"부정행위\"라 한다)로 국세를 포탈(逋脫)하거나 환급ㆍ공제를 받은 경우: 그 국세를 부과할 수 있는 날부터 10년(역외거래에서 발생한 부정행위로 국세를 포탈하거나 환급ㆍ공제받은 경우에는 15년)"},{"법령":"국세기본법 시행령","조문":"제12조의3제1항제2호","원문":"2. 종합부동산세 및 인지세의 경우 해당 국세의 납세의무가 성립한 날"}],"선지":[{"번호":1,"판정":"틀림","설명":"부정행위로 종합소득세를 포탈한 경우 부과제척기간은 10년이다. 15년은 역외거래에서 발생한 부정행위일 때만 적용한다(국세기본법 제26조의2제2항제2호)."},{"번호":2,"판정":"틀림","설명":"소송 판결이 확정되면 확정일부터 1년이 지나기 전까지 경정 등 필요한 처분을 할 수 있다. 2년이 아니다(국세기본법 제26조의2제6항제1호)."},{"번호":3,"판정":"옳음","설명":"감사원법에 따른 심사청구 결정으로 명의대여가 확인되면 당초 부과처분을 취소하고 결정 확정일부터 1년 이내에 실제 사업 경영자에게 경정 등을 한다(국세기본법 제26조의2제7항제1호)."},{"번호":4,"판정":"틀림","설명":"종합부동산세는 신고기한 다음 날이 아니라 납세의무 성립일(과세기준일 6월 1일)부터 제척기간을 센다(국세기본법 시행령 제12조의3제1항제2호)."},{"번호":5,"판정":"틀림","설명":"법정신고기한까지 신고서를 내지 않은 경우 제척기간은 7년이고, 역외거래일 때 10년이다(국세기본법 제26조의2제2항제1호)."}],"개념":[{"종류":"표","제목":"부과제척기간 한눈에","머리":["사유","국세(역외거래 아님)","국세(역외거래)","지방세"],"행":[["원칙","5년","7년","5년"],["법정신고기한까지 무신고","7년","10년","7년(상속·증여·명의신탁·과점주주 취득은 10년)"],["사기·부정행위로 포탈·환급","10년","15년","10년"],["상속세·증여세","10년(부정행위·미신고·거짓신고는 15년)","-","-"],["기산일(신고하는 국세)","신고기한 다음 날","-","부과할 수 있는 날(대통령령)"],["기산일(종합부동산세·인지세)","납세의무 성립일","-","-"]]},{"종류":"표","제목":"제척기간이 지나도 처분이 가능한 경우(국세)","머리":["사유","처분 가능 기간","처분 상대방"],"행":[["이의신청·심사청구·심판청구·감사원 심사청구·행정소송 결정·판결 확정","확정일부터 1년","-"],["위 결정·판결로 명의대여 사실 확인","확정일부터 1년(당초 처분 취소)","실제로 사업을 경영한 자"],["위 결정·판결로 재산 귀속이 명의일 뿐임이 확인","확정일부터 1년(당초 처분 취소)","재산의 사실상 귀속자"],["국제조세 경정청구·조정권고","청구일·권고일부터 2개월","-"],["조세조약 상호합의 종결","절차 종료일부터 1년","-"]]}],"함정":"1번은 15년을 부정행위 일반의 기간으로 외우면 고르게 된다. 15년은 역외거래에서 발생한 부정행위, 상속·증여세의 특수 사유에 붙는 숫자다. 2번은 1년을 2년으로 바꿨고, 4번은 종합부동산세를 다른 신고 세목처럼 신고기한 다음 날로 센 것이다."},"34회-2차-111":{"한줄":"재산세 표준세율을 조례로 가감하는 경우 가감한 세율은 해당 연도에만 적용한다.","근거":[{"법령":"지방세법","조문":"제111조제3항","원문":"③ 지방자치단체의 장은 특별한 재정수요나 재해 등의 발생으로 재산세의 세율 조정이 불가피하다고 인정되는 경우 조례로 정하는 바에 따라 제1항의 표준세율의 100분의 50의 범위에서 가감할 수 있다. 다만, 가감한 세율은 해당 연도에만 적용한다."},{"법령":"지방세법","조문":"제111조제1항제4호가목","원문":"가. 제13조제5항제5호에 따른 고급선박: 과세표준의 1천분의 50"},{"법령":"지방세법","조문":"제111조제1항제2호가목","원문":"가. 제13조제5항에 따른 골프장, 고급오락장용 건축물: 과세표준의 1천분의 40"},{"법령":"지방세법","조문":"제111조제1항제2호나목","원문":"지정된 주거지역 및 해당 지방자치단체의 조례로 정하는 지역의 대통령령으로 정하는 공장용 건축물: 과세표준의 1천분의 5"},{"법령":"지방세법","조문":"제111조제1항제4호나목","원문":"나. 그 밖의 선박: 과세표준의 1천분의 3"},{"법령":"지방세법","조문":"제111조제1항제5호","원문":"5. 항공기: 과세표준의 1천분의 3"},{"법령":"지방세법","조문":"제111조의2제1항","원문":"대통령령으로 정하는 1세대 1주택(제4조제1항에 따른 시가표준액이 9억원 이하인 주택에 한정한다)에 대해서는 다음의 세율을 적용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"고급선박은 1천분의 50, 고급오락장용 건축물은 1천분의 40이다(지방세법 제111조제1항제4호가목, 제2호가목)."},{"번호":2,"판정":"옳음","설명":"특별시 등 지역의 주거지역과 조례로 정한 지역에 있는 대통령령 정한 공장용 건축물은 1천분의 5다(지방세법 제111조제1항제2호나목)."},{"번호":3,"판정":"옳음","설명":"1세대 1주택 특례(제111조의2)에 해당하지 않는 일반 주택은 과세표준 6천만원 이하 1천분의 1에서 3억원 초과 1천분의 4까지 4단계 초과누진세율이다(지방세법 제111조제1항제3호나목)."},{"번호":4,"판정":"옳음","설명":"항공기 1천분의 3은 고급선박을 뺀 그 밖의 선박의 세율과 같다(지방세법 제111조제1항제4호나목, 제5호)."},{"번호":5,"판정":"틀림","설명":"표준세율의 100분의 50 범위에서 가감한 세율은 해당 연도에만 적용한다. 3년간 적용하는 규정은 없다(지방세법 제111조제3항)."}],"개념":[{"종류":"표","제목":"재산세 표준세율","머리":["대상","세율"],"행":[["종합합산과세대상 토지","5천만원 이하 1천분의 2 / 1억원 이하 1천분의 3 / 1억원 초과 1천분의 5 (초과누진)"],["별도합산과세대상 토지","2억원 이하 1천분의 2 / 10억원 이하 1천분의 3 / 10억원 초과 1천분의 4 (초과누진)"],["분리과세 토지(전·답·과수원·목장용지·임야)","1천분의 0.7"],["분리과세 토지(골프장·고급오락장용)","1천분의 40"],["분리과세 토지(그 밖의 토지)","1천분의 2"],["건축물(골프장·고급오락장용)","1천분의 40"],["건축물(시 지역 주거지역 등의 공장용)","1천분의 5"],["건축물(그 밖)","1천분의 2.5"],["주택","6천만원 이하 1천분의 1 / 1억5천만원 이하 1천분의 1.5 / 3억원 이하 1천분의 2.5 / 3억원 초과 1천분의 4 (초과누진)"],["선박(고급선박 / 그 밖)","1천분의 50 / 1천분의 3"],["항공기","1천분의 3"]]},{"종류":"계산","제목":"주택 재산세 산출 예","단계":[{"설명":"주택 과세표준 4억원은 3억원 초과 구간이다. 57만원에 3억원 초과금액의 1천분의 4를 더한다","식":"570,000원 + (4억원 − 3억원) × 0.4%","값":"570,000원 + 400,000원 = 970,000원"}]}],"함정":"5번은 가감 범위(100분의 50)는 맞고 적용 기간만 3년으로 바꾼 문장이다. 숫자 하나만 틀려서 앞부분이 맞다는 이유로 넘기기 쉽다. 1번의 고급선박 1천분의 50과 고급오락장 1천분의 40은 순서를 바꿔 외우는 경우가 많다."},"34회-1차-004":{"한줄":"보완재 가격이 하락하면 보완재 수요가 늘면서 함께 쓰는 해당 부동산의 수요도 늘어 수요곡선이 우측으로 이동한다.","근거":[{"이론":"수요변화의 요인","내용":"해당 재화의 가격 변화는 수요곡선 위의 이동(수요량 변화)이고, 소득·선호·관련재 가격·금리·인구·기대 등의 변화는 수요곡선 자체의 이동(수요 변화)이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대출금리가 상승하면 구입 부담이 늘어 수요가 감소하고 수요곡선이 좌측으로 이동한다."},{"번호":2,"판정":"옳음","설명":"보완재 가격이 하락하면 보완재 수요가 늘고, 함께 소비하는 해당 부동산의 수요도 증가한다."},{"번호":3,"판정":"틀림","설명":"대체재 수요량의 증가는 대체재 가격 하락 같은 원인에서 나올 수 있고, 이 경우 해당 부동산 수요는 감소한다. 수요 증가 요인으로 확정할 수 없다."},{"번호":4,"판정":"틀림","설명":"해당 부동산 가격의 상승은 수요곡선 위에서 수요량이 줄어드는 이동이다."},{"번호":5,"판정":"틀림","설명":"선호도가 감소하면 수요곡선은 좌측으로 이동한다."}],"개념":[{"종류":"표","제목":"수요곡선을 이동시키는 요인","머리":["요인","수요 증가(우측 이동)","수요 감소(좌측 이동)"],"행":[["소득(정상재)","소득 증가","소득 감소"],["대체재 가격","상승","하락"],["보완재 가격","하락","상승"],["대출금리","하락","상승"],["선호도","증가","감소"],["인구·가구 수","증가","감소"],["가격 상승 기대","있음(투자·투기 수요)","하락 기대"]]},{"종류":"비교","제목":"수요량의 변화와 수요의 변화","왼쪽":{"이름":"수요량의 변화","항목":["해당 재화 가격 변화가 원인","같은 수요곡선 위의 점 이동"]},"오른쪽":{"이름":"수요의 변화","항목":["가격 이외 요인이 원인","수요곡선 자체가 좌·우로 이동"]}}],"함정":"해당 부동산 가격 변화(4번)를 수요 변화로 고르기 쉽다. 자기 가격은 수요량 변화이므로 곡선이 움직이지 않는다."},"34회-1차-005":{"한줄":"가격을 세로축에 놓을 때 수요곡선이 공급곡선보다 완만하면(수요의 기울기 절댓값이 더 작으면) 가격 변동폭이 시간이 갈수록 줄어 수렴한다.","근거":[{"이론":"거미집모형(에치켈)","내용":"수요는 당기 가격에 즉각 반응하고 공급은 한 기간 시차를 두고 전기 가격에 반응한다. 수요의 가격탄력성이 공급의 가격탄력성보다 크면(|수요 기울기| < |공급 기울기|) 수렴, 작으면 발산, 같으면 순환한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요의 가격탄력성이 공급보다 크면 수렴형이다."},{"번호":2,"판정":"틀림","설명":"수요는 당기 가격에 즉각 반응하나 공급은 생산 시차 때문에 전기 가격에 반응한다."},{"번호":3,"판정":"옳음","설명":"수요곡선 기울기 절댓값이 공급곡선 기울기 절댓값보다 작으면(탄력성은 수요가 더 큼) 수렴형이다."},{"번호":4,"판정":"틀림","설명":"시차를 두고 균형이 변해 가는 과정을 보는 동태적 분석 모형이다."},{"번호":5,"판정":"틀림","설명":"공급자는 현재(전기) 가격이 계속될 것으로 보고 공급을 결정하며 미래 가격은 고려하지 않는다."}],"개념":[{"종류":"표","제목":"거미집모형의 형태(가격 Y축 기준)","머리":["구분","탄력성 비교","기울기 절댓값 비교","결과"],"행":[["수렴형","수요 > 공급","수요 < 공급","균형으로 접근"],["발산형","수요 < 공급","수요 > 공급","균형에서 멀어짐"],["순환형","수요 = 공급","수요 = 공급","일정 폭으로 반복"]]},{"종류":"표","제목":"거미집모형의 가정","머리":["항목","내용"],"행":[["수요","당기 가격에 즉각 반응"],["공급","전기 가격에 반응(생산 시차)"],["공급자 예상","현재 가격이 미래에도 계속된다고 가정"],["분석 성격","동태적 분석"],["적용 시장","공급 시차가 긴 농산물·부동산 등"]]}],"함정":"탄력성과 기울기는 크고 작음이 반대다. 탄력성은 수요가 클 때, 기울기는 수요가 작을 때 수렴한다. 이 대응이 1번과 3번의 갈림길이다."},"34회-1차-010":{"한줄":"버제스 동심원이론은 중심업무지대에서 바깥으로 점이지대, 노동자주거지대, 중산층주거지대, 통근자지대 순이어서 통근자지대가 가장 바깥이다.","근거":[{"이론":"도시공간구조이론","내용":"버제스 동심원(중심업무→점이→노동자주거→중산층주거→통근자), 호이트 선형(교통망 축 따라 부채꼴 확대), 해리스·울만 다핵심(여러 핵이 독자 형성)."}],"선지":[{"번호":1,"판정":"옳음","설명":"동심원이론의 5개 지대 중 통근자지대가 가장 외곽이다."},{"번호":2,"판정":"틀림","설명":"호이트는 도시가 교통망 축을 따라 부채꼴(선형)로 확대된다고 보았다. 점이지대를 향한 확대가 아니다."},{"번호":3,"판정":"틀림","설명":"다핵심이론에도 중심업무지구(CBD)와 점이지대 등이 핵의 하나로 존재한다."},{"번호":4,"판정":"틀림","설명":"뢰쉬의 최대수요이론은 수요 측면에서 시장구역이 육각형으로 형성된다고 보며, 운송비·집적이익 중심의 설명이 아니다."},{"번호":5,"판정":"틀림","설명":"점포 입지의 8원칙은 넬슨의 소매입지이론이다. 레일리는 두 도시의 상권 경계를 설명했다."}],"개념":[{"종류":"표","제목":"도시공간구조 3대 이론","머리":["이론","학자","구조"],"행":[["동심원이론","버제스","중심업무 → 점이 → 노동자주거 → 중산층주거 → 통근자"],["선형(扇形)이론","호이트","교통망 축을 따라 부채꼴로 확대, 고급주거 지역이 한 방향으로 확대"],["다핵심이론","해리스·울만","CBD 외에 여러 핵이 독립적으로 형성"]]},{"종류":"표","제목":"입지이론 구분","머리":["이론","학자","핵심"],"행":[["최소비용","베버","운송비·노동비·집적이익 최소 지점"],["최대수요","뢰쉬","수요 극대화, 육각형 시장구역"],["중심지","크리스탈러","재화의 도달범위·최소요구범위, 육각형 계층"],["소매인력","레일리","두 도시 상권 경계 (인구에 비례, 거리 제곱에 반비례)"],["소매입지 8원칙","넬슨","점포 입지 원칙(고객 흡인력, 접근성 등)"]]}],"함정":"다핵심이론에 CBD가 없다고 보는 3번과, 8원칙을 레일리 것으로 외운 5번이 흔한 오답이다. 8원칙은 넬슨이다."},"34회-1차-033":{"한줄":"AIDA 원리는 공급자가 아니라 소비자의 구매심리 단계(주의·관심·욕망·행동)를 따르는 고객점유 마케팅 전략이다. 시장점유 마케팅은 STP가 중심이다.","근거":[{"이론":"부동산마케팅 전략의 구분","내용":"시장점유 전략은 시장세분화·표적시장 선정·포지셔닝(STP)과 마케팅믹스(4P)로 공급자가 시장을 나누고 겨냥하는 전략이다. 고객점유 전략은 AIDA 원리로 소비자의 구매심리 단계에 맞추는 전략이다. 관계 마케팅은 고객과 장기적 관계를 유지하는 전략이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동산마케팅은 상품 개발, 가격 결정, 유통·촉진·판매 관리로 이어지는 과정이다."},{"번호":2,"판정":"옳음","설명":"STP는 시장세분화, 표적시장 선정, 포지셔닝으로 구성된다."},{"번호":3,"판정":"옳음","설명":"시장세분화는 수요자 집단을 세분하는 활동이다."},{"번호":4,"판정":"옳음","설명":"표적시장 전략은 세분된 시장에서 선정한 집단을 대상으로 마케팅활동을 하는 것이다."},{"번호":5,"판정":"틀림","설명":"AIDA는 공급자가 아니라 소비자의 구매심리를 파악하는 고객점유 마케팅 전략이다. 시장점유 마케팅 전략에 해당하는 것은 STP이다."}],"개념":[{"종류":"표","제목":"마케팅 전략 구분","머리":["구분","내용","중심"],"행":[["시장점유 전략","STP(시장세분화→표적시장 선정→포지셔닝)와 4P 믹스","공급자가 시장을 나누고 겨냥함"],["고객점유 전략","AIDA(주의→관심→욕망→행동)","소비자의 구매심리 단계"],["관계 마케팅","고객과의 장기적 관계 유지, 충성도 확보","기존 고객"]]},{"종류":"표","제목":"마케팅믹스 4P","머리":["요소","내용","부동산 예"],"행":[["제품(Product)","수요자 욕구에 맞는 상품 개발","입지·평면·단지 설계"],["가격(Price)","가격 결정","분양가·임대료·할인 정책"],["유통(Place)","판매 경로 관리","분양대행사·모델하우스·중개업소"],["촉진(Promotion)","광고·홍보·인적판매·판매촉진","광고, 견본주택 행사"]]}],"함정":"AIDA 문장은 앞부분이 맞아 보여 끝까지 읽지 않으면 놓친다. 공급자의 욕구와 시장점유 마케팅이라는 두 곳이 틀렸다."},"34회-1차-064":{"한줄":"법정지상권(제366조)은 경매 당시 토지와 건물이 다른 소유자에 속하게 될 때 저당권 설정 당시 건물이 있었던 경우에 성립한다. 나대지에 설정한 저당권은 건축에 동의했어도 법정지상권이 성립하지 않는다.","근거":[{"법령":"민법","조문":"제366조","원문":"저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"법령":"민법","조문":"제365조","원문":"토지를 목적으로 저당권을 설정한 후 그 설정자가 그 토지에 건물을 축조한 때에는 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 그러나 그 건물의 경매대가에 대하여는 우선변제를 받을 권리가 없다."},{"법령":"민법","조문":"제367조","원문":"저당물의 제삼취득자가 그 부동산의 보존, 개량을 위하여 필요비 또는 유익비를 지출한 때에는 제203조제1항, 제2항의 규정에 의하여 저당물의 경매대가에서 우선상환을 받을 수 있다."},{"법령":"민법","조문":"제371조제1항","원문":"본장의 규정은 지상권 또는 전세권을 저당권의 목적으로 한 경우에 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세권도 저당권의 목적이 된다. 지상권·전세권을 목적으로 한 저당권에는 저당권 규정을 준용한다(제371조제1항)."},{"번호":2,"판정":"틀림","설명":"저당권 설정은 소유권 위에 제한물권을 새로 만드는 설정적(창설적) 승계다. 이전적 승계는 소유권 양도처럼 권리가 그대로 넘어가는 경우다."},{"번호":3,"판정":"틀림","설명":"일괄경매를 청구해도 건물의 경매대가에서는 우선변제를 받지 못한다. 우선변제는 토지의 경매대가에서만 받는다(제365조 단서)."},{"번호":4,"판정":"옳음","설명":"저당권 설정 당시 건물이 없던 나대지는 법정지상권이 성립하지 않는다. 저당권자가 건축에 동의했더라도 같다는 것이 판례다."},{"번호":5,"판정":"틀림","설명":"저당물의 제3취득자가 지출한 필요비·유익비는 제203조에 따라 경매대가에서 우선상환을 받는다(제367조)."}],"개념":[{"종류":"비교","제목":"저당토지 위 건물의 법적 취급","왼쪽":{"이름":"저당권 설정 당시 건물이 있던 경우","항목":["토지와 건물이 동일 소유자 소유였을 것","경매로 토지와 건물의 소유자가 달라지면 법정지상권 성립(제366조)","지료는 당사자 청구로 법원이 정함","건물이 개축·신축되어도 구건물을 기준으로 한 범위에서 성립(판례)"]},"오른쪽":{"이름":"나대지에 저당권이 설정된 후 건물이 지어진 경우","항목":["법정지상권 성립하지 않음(저당권자가 건축에 동의했어도 같음, 판례)","저당권자는 토지와 건물의 일괄경매 청구 가능(제365조 본문)","일괄경매에서도 건물 경매대가에서는 우선변제 불가(제365조 단서)","건물 소유자에게 법정지상권이 없으므로 경매 후 매수인은 건물 철거를 청구할 수 있음"]}},{"종류":"비교","제목":"승계의 구분","왼쪽":{"이름":"설정적(창설적) 승계","항목":["소유권 위에 제한물권을 새로 만드는 것","지상권·전세권·저당권의 설정","저당권 설정이 여기에 해당"]},"오른쪽":{"이름":"이전적 승계","항목":["권리가 동일성을 유지한 채 이전","소유권 양도, 저당권부 채권의 양도","이 경우 저당권도 수반성에 따라 함께 이전"]}}],"함정":"3번은 일괄경매를 청구하면 건물 대가에서도 우선변제를 받는다고 오해하기 쉽다. 제365조 단서가 이를 막는다. 4번은 정답률 21%로, 건축 동의 사실이 법정지상권을 만든다고 생각하면 틀린다. 법정지상권은 설정 당시 건물이 있었는지를 본다."},"34회-2차-016":{"한줄":"법률 제7638호 부칙 제6조제2항의 개업공인중개사도 사무소 명칭에 '부동산중개'를 사용하여야 한다. 사용이 금지되는 것은 '공인중개사사무소'다.","근거":[{"법령":"공인중개사법","조문":"제18조제1항","원문":"개업공인중개사는 그 사무소의 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"라는 문자를 사용하여야 한다."},{"법령":"공인중개사법","조문":"제18조제3항","원문":"개업공인중개사가 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률」 제2조제1호에 따른 옥외광고물을 설치하는 경우 중개사무소등록증에 표기된 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 제13조제4항의 규정에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 표기하여야 한다."},{"법령":"공인중개사법","조문":"제17조","원문":"개업공인중개사는 중개사무소등록증ㆍ중개보수표 그 밖에 국토교통부령으로 정하는 사항을 해당 중개사무소 안의 보기 쉬운 곳에 게시하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제10조제3호","원문":"개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당되는 자가 있는 경우로 한정한다)"},{"법령":"공인중개사법 시행규칙","조문":"제10조제5호","원문":"「부가가치세법 시행령」 제11조에 따른 사업자등록증"}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사와 소속공인중개사의 자격증 원본을 게시한다. 해당자가 있는 경우에 한한다(시행규칙 제10조제3호)."},{"번호":2,"판정":"옳음","설명":"사업자등록증도 게시 대상이다(시행규칙 제10조제5호)."},{"번호":3,"판정":"옳음","설명":"법인도 개업공인중개사이므로 '공인중개사사무소' 또는 '부동산중개' 중 하나를 사용하여야 한다(법 제18조제1항)."},{"번호":4,"판정":"옳음","설명":"분사무소의 옥외광고물에는 분사무소설치신고확인서에 기재된 책임자의 성명을 표기한다(법 제18조제3항)."},{"번호":5,"판정":"틀림","설명":"부칙(법률 제7638호) 제6조의 개업공인중개사는 '공인중개사사무소'를 쓸 수 없고, '부동산중개'를 쓰도록 되어 있다. 두 문자를 모두 쓰지 못하는 것이 아니다(법 제18조제1항 참조)."}],"개념":[{"종류":"표","제목":"중개사무소 안에 게시할 사항(법 제17조, 시행규칙 제10조)","머리":["게시 대상","비고","근거"],"행":[["중개사무소등록증 원본","법인의 분사무소는 분사무소설치신고확인서 원본","시행규칙 제10조제1호"],["중개보수ㆍ실비의 요율 및 한도액표","주택 외 대상은 실제 받으려는 상한요율 명시","시행규칙 제10조제2호, 제20조제7항"],["개업공인중개사ㆍ소속공인중개사의 공인중개사자격증 원본","해당자가 있는 경우로 한정","시행규칙 제10조제3호"],["보증의 설정을 증명할 수 있는 서류","보증보험증서ㆍ공제증서ㆍ공탁증서 사본 등","시행규칙 제10조제4호"],["사업자등록증","「부가가치세법 시행령」 제11조에 따른 것","시행규칙 제10조제5호"]]},{"종류":"표","제목":"사무소 명칭과 옥외광고물 규정 비교","머리":["대상","명칭","옥외광고물 성명 표기","위반 시"],"행":[["공인중개사인 개업공인중개사","'공인중개사사무소' 또는 '부동산중개' 사용","등록증에 표기된 개업공인중개사 성명","과태료 100만원 이하(법 제51조제3항제2호)"],["법인인 개업공인중개사","같음","대표자 성명","같음"],["법인의 분사무소","같음","신고확인서에 기재된 책임자 성명","같음"],["부칙(법률 제7638호) 제6조제2항 개업공인중개사","'공인중개사사무소' 사용 금지, '부동산중개' 사용","등록증에 표기된 성명","같음"],["개업공인중개사가 아닌 자","'공인중개사사무소'ㆍ'부동산중개'ㆍ유사 명칭 사용 금지","해당 없음","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제6호), 등록관청의 간판 철거 명령ㆍ대집행(법 제18조제5항)"]]}],"함정":"법 제18조제1항의 '또는'을 '및'으로 읽으면 안 된다. ⑤처럼 두 문자를 모두 못 쓴다고 쓴 선지가 틀린 이유는 부칙 대상 개업공인중개사도 '부동산중개'는 써야 하기 때문이다."},"34회-2차-007":{"한줄":"소속공인중개사나 중개보조원과의 고용관계가 종료되면 종료일부터 10일 이내에 등록관청에 신고한다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제8조제4항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원과의 고용관계가 종료된 때에는 법 제15조제1항에 따라 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제8조제1항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원을 고용한 경우에는 법 제34조제2항 또는 제3항에 따른 교육을 받도록 한 후 법 제15조제1항에 따라 업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."},{"법령":"공인중개사법","조문":"제15조제2항","원문":"소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법 시행규칙","조문":"제8조제5항","원문":"이 경우 소속공인중개사 또는 중개보조원으로 외국인을 고용하는 경우에는 제4조제1항제6호가목의 서류를 첨부하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"고용인의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다(법 제15조제2항)."},{"번호":2,"판정":"틀림","설명":"고용 신고는 업무개시 전까지 하면 된다. 고용 전에 미리 하라는 규정은 없다(시행규칙 제8조제1항)."},{"번호":3,"판정":"옳음","설명":"고용관계 종료 신고는 종료된 날부터 10일 이내다(시행규칙 제8조제4항)."},{"번호":4,"판정":"틀림","설명":"교육을 받도록 한 후 신고하며, 등록관청이 교육 수료 여부를 확인한다(시행규칙 제8조제1항ㆍ제3항). 수료확인증 제출 규정은 없다."},{"번호":5,"판정":"틀림","설명":"외국인도 고용할 수 있다. 이때 결격사유에 해당하지 않음을 증명하는 외국 서류를 첨부한다(시행규칙 제8조제5항)."}],"개념":[{"종류":"표","제목":"소속공인중개사와 중개보조원 비교","머리":["항목","소속공인중개사","중개보조원"],"행":[["고용 신고","업무개시 전까지 등록관청에 신고(시행규칙 제8조제1항)","같음"],["고용종료 신고","종료일부터 10일 이내(시행규칙 제8조제4항)","같음"],["고용 전 교육","고용 신고일 전 1년 이내 실무교육 45시간(법 제34조제2항, 영 제28조제1항)","고용 신고일 전 1년 이내 직무교육 3시간 이상 4시간 이하(법 제34조제3항, 영 제28조제2항)"],["연수교육","실무교육 후 2년마다 12시간 이상 16시간 이하(법 제34조제4항, 영 제28조제3항)","대상 아님"],["결격사유","법 제10조제1항제1호~제11호 해당자는 될 수 없음(법 제10조제2항)","같음"],["이중소속","다른 개업공인중개사의 소속이 될 수 없음(법 제12조제2항)","같음"],["인원 제한","없음","개업공인중개사와 소속공인중개사를 합한 수의 5배 초과 불가(법 제15조제3항)"],["인장등록","필요(법 제16조)","없음"],["고지의무","없음","현장안내 등 보조 시 중개의뢰인에게 중개보조원이라는 사실을 미리 고지(법 제18조의4)"]]},{"종류":"흐름","제목":"고용 신고 절차와 위반 효과","단계":[{"이름":"사전 확인","설명":"결격사유(법 제10조제2항)와 다른 사무소 소속 여부(법 제12조제2항)를 확인한다."},{"이름":"교육","설명":"소속공인중개사는 실무교육, 중개보조원은 직무교육을 받도록 한다(시행규칙 제8조제1항)."},{"이름":"신고","설명":"업무개시 전까지 별지 제11호서식으로 신고한다. 전자문서 신고가 가능하고, 외국인은 서류를 첨부한다(시행규칙 제8조제1항ㆍ제5항)."},{"이름":"등록관청 확인","설명":"시ㆍ도지사에게 자격 확인을 요청하고, 결격사유와 교육 수료 여부를 확인한다(시행규칙 제8조제2항ㆍ제3항)."},{"이름":"종료 신고","설명":"고용관계 종료일부터 10일 이내에 신고한다(시행규칙 제8조제4항)."},{"이름":"위반 효과","설명":"결격자를 고용하면 업무정지(사유 발생일부터 2개월 내 해소 시 제외, 법 제39조제1항제1호). 중개보조원 수 초과 고용은 등록취소(법 제38조제1항제5호의2)와 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제5호의2) 대상이다."}]}],"함정":"신고 시기를 '고용 전에 미리'로 쓴 ②와 '수료확인증 제출'을 요구하는 ④가 그럴듯하다. 고용 신고는 업무개시 전까지, 종료 신고는 10일 이내다."},"34회-2차-041":{"한줄":"지구단위계획구역으로 지정된 지역도 개발행위허가 제한 대상 지역에 포함된다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제63조제1항","원문":"① … 다음 각 호의 어느 하나에 해당되는 지역으로서 도시ㆍ군관리계획상 특히 필요하다고 인정되는 지역에 대해서는 … 한 차례만 3년 이내의 기간 동안 개발행위허가를 제한할 수 있다. 다만, 제3호부터 제5호까지에 해당하는 지역에 대해서는 중앙도시계획위원회나 지방도시계획위원회의 심의를 거치지 아니하고 한 차례만 2년 이내의 기간 동안 개발행위허가의 제한을 연장할 수 있다.\n  4. 지구단위계획구역으로 지정된 지역\n  5. 기반시설부담구역으로 지정된 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제56조제1항제5호","원문":"5. 녹지지역ㆍ관리지역 또는 자연환경보전지역에 물건을 1개월 이상 쌓아놓는 행위"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제59조제2항제7호","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 개발행위는 중앙도시계획위원회와 지방도시계획위원회의 심의를 거치지 아니한다.\n  7. 「산림자원의 조성 및 관리에 관한 법률」에 따른 산림사업 및 「사방사업법」에 따른 사방사업을 위한 개발행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"물건을 쌓아놓는 행위가 허가 대상인 곳은 녹지지역·관리지역·자연환경보전지역이다. 농림지역은 빠진다(법 제56조제1항제5호)."},{"번호":2,"판정":"옳음","설명":"사방사업을 위한 개발행위는 도시계획위원회 심의 면제 대상이다(법 제59조제2항제7호)."},{"번호":3,"판정":"틀림","설명":"지구단위계획구역으로 지정된 지역은 허가 제한 대상 지역의 하나다(법 제63조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"기반시설부담구역은 제3호부터 제5호에 해당하여 위원회 심의 없이 연장할 수 있다(법 제63조제1항 단서)."},{"번호":5,"판정":"옳음","설명":"연장은 한 차례, 2년 이내다(법 제63조제1항 단서)."}],"개념":[{"종류":"표","제목":"개발행위허가 제한 대상 지역(법 제63조제1항)","머리":["호","지역","제한(위원회 심의 필요)","연장"],"행":[["제1호","녹지지역·계획관리지역으로서 수목이 집단적으로 자라거나 조수류가 집단 서식하는 지역, 우량 농지 등 보전 필요 지역","한 차례 3년 이내","법에 연장 규정 없음"],["제2호","개발행위로 주변 환경·경관·미관·국가유산이 크게 오염·손상될 우려가 있는 지역","한 차례 3년 이내","법에 연장 규정 없음"],["제3호","도시·군기본계획 또는 도시·군관리계획 수립 중이고 결정되면 용도지역 등이 변경되어 허가 기준이 크게 달라질 지역","한 차례 3년 이내","심의 없이 한 차례 2년 이내"],["제4호","지구단위계획구역으로 지정된 지역","한 차례 3년 이내","심의 없이 한 차례 2년 이내"],["제5호","기반시설부담구역으로 지정된 지역","한 차례 3년 이내","심의 없이 한 차례 2년 이내"]]},{"종류":"표","제목":"도시계획위원회 심의를 거치지 않는 개발행위(법 제59조제2항)","머리":["호","개발행위"],"행":[["1","제8조·제9조 또는 다른 법률에 따라 도시계획위원회의 심의를 받는 구역에서 하는 개발행위"],["2","지구단위계획 또는 성장관리계획을 수립한 지역에서 하는 개발행위"],["3","주거·상업·공업지역에서 하는 개발행위 중 조례가 정한 규모·위치에 해당하지 않는 것"],["4","환경영향평가를 받은 개발행위"],["5","교통영향평가에 대한 검토를 받은 개발행위"],["6","농어촌정비사업 중 대통령령으로 정하는 사업을 위한 개발행위"],["7","산림사업 및 사방사업을 위한 개발행위"]]}],"함정":"허가 제한 대상 5개 지역 가운데 지구단위계획구역을 빠뜨리기 쉽다. 연장 규정과 심의 면제는 제3호부터 제5호에만 있다."},"34회-2차-074":{"한줄":"자동차영업소와 노래연습장은 모두 제2종 근린생활시설로 근린생활시설군(7군)이다. 같은 시설군 안의 변경이므로 허가·신고가 아니라 건축물대장 기재내용 변경을 신청한다. 노래연습장은 영 제14조제4항 단서의 예외라 신청 면제도 없다.","근거":[{"법령":"건축법","조문":"제19조제2항·제3항","원문":"② 제22조에 따라 사용승인을 받은 건축물의 용도를 변경하려는 자는 다음 각 호의 구분에 따라 국토교통부령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장의 허가를 받거나 신고를 하여야 한다.\n1. 허가 대상: 제4항 각 호의 어느 하나에 해당하는 시설군(施設群)에 속하는 건축물의 용도를 상위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 작은 시설군을 말한다)에 해당하는 용도로 변경하는 경우\n2. 신고 대상: 제4항 각 호의 어느 하나에 해당하는 시설군에 속하는 건축물의 용도를 하위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 큰 시설군을 말한다)에 해당하는 용도로 변경하는 경우\n③ 제4항에 따른 시설군 중 같은 시설군 안에서 용도를 변경하려는 자는 국토교통부령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 건축물대장 기재내용의 변경을 신청하여야 한다. 다만, 대통령령으로 정하는 변경의 경우에는 그러하지 아니하다."},{"법령":"건축법 시행령","조문":"제14조제4항","원문":"④ 법 제19조제3항 단서에서 \"대통령령으로 정하는 변경\"이란 다음 각 호의 어느 하나에 해당하는 건축물 상호 간의 용도변경을 말한다. 다만, 별표 1 제3호다목(목욕장만 해당한다)ㆍ라목, 같은 표 제4호가목ㆍ사목ㆍ카목ㆍ파목(골프연습장, 놀이형시설만 해당한다)ㆍ더목ㆍ러목ㆍ머목, 같은 표 제7호다목2), 같은 표 제15호가목(생활숙박시설만 해당한다) 및 같은 표 제16호가목ㆍ나목에 해당하는 용도로 변경하는 경우는 제외한다.\n1. 별표 1의 같은 호에 속하는 건축물 상호 간의 용도변경\n2. 「국토의 계획 및 이용에 관한 법률」이나 그 밖의 관계 법령에서 정하는 용도제한에 적합한 범위에서 제1종 근린생활시설과 제2종 근린생활시설 상호 간의 용도변경"},{"법령":"건축법 시행령","조문":"별표 1 제4호 다목·러목","원문":"다. 자동차영업소로서 같은 건축물에 해당 용도로 쓰는 바닥면적의 합계가 1천제곱미터 미만인 것\n러. 안마시술소, 노래연습장"},{"법령":"건축법","조문":"제19조제5항·제6항","원문":"⑤ 제2항에 따른 허가나 신고 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 100제곱미터 이상인 경우의 사용승인에 관하여는 제22조를 준용한다. 다만, 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 미만으로서 대수선에 해당되는 공사를 수반하지 아니하는 경우에는 그러하지 아니하다.\n⑥ 제2항에 따른 허가 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 이상인 용도변경(대통령령으로 정하는 경우는 제외한다)의 설계에 관하여는 제23조를 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"허가 대상은 상위군으로 올리는 경우다(법 제19조제2항제1호). 같은 7군 안의 변경이라 허가 대상이 아니다."},{"번호":2,"판정":"틀림","설명":"신고 대상은 하위군으로 내리는 경우다(법 제19조제2항제2호). 같은 시설군이라 신고 대상도 아니다."},{"번호":3,"판정":"틀림","설명":"사용승인 준용은 허가·신고 대상 용도변경에서 바닥면적 합계 100㎡ 이상일 때다(법 제19조제5항). 허가·신고 대상이 아니다."},{"번호":4,"판정":"옳음","설명":"같은 시설군 안에서 변경하면 건축물대장 기재내용의 변경을 신청한다(법 제19조제3항). 노래연습장으로 바꾸는 경우는 영 제14조제4항 단서의 예외라 신청해야 한다."},{"번호":5,"판정":"틀림","설명":"용도변경 설계에 건축사 설계를 준용하는 경우는 허가 대상이면서 바닥면적 합계 500㎡ 이상일 때다(법 제19조제6항). 허가 대상이 아니다."}],"개념":[{"종류":"표","제목":"용도변경 시설군 9개(법 제19조제4항, 영 제14조제5항)","머리":["번호","시설군","속하는 용도"],"행":[["1","자동차 관련 시설군","자동차 관련 시설"],["2","산업 등 시설군","운수·창고·공장·위험물저장 및 처리·자원순환 관련·묘지 관련·장례시설"],["3","전기통신시설군","방송통신시설, 발전시설"],["4","문화집회시설군","문화 및 집회, 종교, 위락, 관광휴게시설"],["5","영업시설군","판매, 운동, 숙박시설, 제2종 근린생활시설 중 다중생활시설"],["6","교육 및 복지시설군","의료, 교육연구, 노유자, 수련시설, 야영장 시설"],["7","근린생활시설군","제1종 근린생활시설, 제2종 근린생활시설(다중생활시설 제외)"],["8","주거업무시설군","단독주택, 공동주택, 업무시설, 교정시설, 국방·군사시설"],["9","그 밖의 시설군","동물 및 식물 관련 시설"]]},{"종류":"흐름","제목":"용도변경 처리 판단","단계":[{"이름":"시설군 확인","설명":"변경 전과 변경 후 용도가 속한 시설군 번호를 비교한다(영 제14조제5항)"},{"이름":"상위군(번호가 작아짐)","설명":"허가. 시장·군수·구청장의 허가(법 제19조제2항제1호)"},{"이름":"하위군(번호가 커짐)","설명":"신고(법 제19조제2항제2호)"},{"이름":"같은 시설군","설명":"건축물대장 기재내용 변경 신청. 같은 호 안의 변경, 제1종·제2종 근린생활시설 상호 변경은 신청도 면제이나 노래연습장·안마시술소·학원 등 열거된 용도로 바꾸면 신청(영 제14조제4항)"},{"이름":"부수 절차","설명":"허가·신고 대상이고 변경 부분 100㎡ 이상이면 사용승인 준용(500㎡ 미만이고 대수선 없으면 제외). 허가 대상이고 500㎡ 이상이면 건축사 설계 준용(법 제19조제5항, 제6항)"}]}],"함정":"허가냐 신고냐만 보다가 시설군이 같다는 점을 놓친다. 자동차영업소와 노래연습장은 둘 다 제2종 근린생활시설이다. 노래연습장은 면제 예외에 열거돼 있어서 대장 변경 신청이 필요하다. 정답률이 18%로 낮았다."},"34회-2차-078":{"한줄":"준공업지역은 설치 대상 지역이고, 여객용 운수시설은 바닥면적 합계 5천㎡ 이상이면 설치 대상 용도다.","근거":[{"법령":"건축법","조문":"제43조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 지역의 환경을 쾌적하게 조성하기 위하여 대통령령으로 정하는 용도와 규모의 건축물은 일반이 사용할 수 있도록 대통령령으로 정하는 기준에 따라 소규모 휴식시설 등의 공개 공지(空地: 공터) 또는 공개 공간(이하 \"공개공지등\"이라 한다)을 설치하여야 한다.\n1. 일반주거지역, 준주거지역\n2. 상업지역\n3. 준공업지역\n4. 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 도시화의 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정하여 지정ㆍ공고하는 지역"},{"법령":"건축법 시행령","조문":"제27조의2제1항","원문":"① 법 제43조제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물의 대지에는 공개 공지 또는 공개 공간(이하 이 조에서 \"공개공지등\"이라 한다)을 설치해야 한다. 이 경우 공개 공지는 필로티의 구조로 설치할 수 있다.\n1. 문화 및 집회시설, 종교시설, 판매시설(「농수산물 유통 및 가격안정에 관한 법률」에 따른 농수산물유통시설은 제외한다), 운수시설(여객용 시설만 해당한다), 업무시설 및 숙박시설로서 해당 용도로 쓰는 바닥면적의 합계가 5천 제곱미터 이상인 건축물\n2. 그 밖에 다중이 이용하는 시설로서 건축조례로 정하는 건축물"}],"선지":[{"번호":1,"판정":"틀림","설명":"일반주거지역은 설치 지역이지만 초등학교(교육연구시설)는 대상 용도가 아니다(영 제27조의2제1항제1호)."},{"번호":2,"판정":"틀림","설명":"준주거지역은 설치 지역이지만 판매시설 중 농수산물유통시설은 제외된다(영 제27조의2제1항제1호)."},{"번호":3,"판정":"틀림","설명":"일반상업지역은 설치 지역이지만 관망탑(관광휴게시설)은 대상 용도가 아니다."},{"번호":4,"판정":"틀림","설명":"자연녹지지역은 설치 지역이 아니다(법 제43조제1항). 유스호스텔(수련시설)도 대상 용도가 아니다."},{"번호":5,"판정":"옳음","설명":"준공업지역(법 제43조제1항제3호)의 운수시설 중 여객용 시설은 대상 용도다(영 제27조의2제1항제1호)."}],"개념":[{"종류":"표","제목":"공개공지등 설치 대상(법 제43조, 영 제27조의2)","머리":["구분","내용"],"행":[["대상 지역","일반주거지역, 준주거지역, 상업지역, 준공업지역, 시장·군수·구청장이 도시화 가능성이 크거나 노후 산업단지 정비가 필요하다고 보아 지정·공고한 지역"],["대상 용도","문화 및 집회시설, 종교시설, 판매시설(농수산물유통시설 제외), 운수시설(여객용 시설만), 업무시설, 숙박시설"],["규모","해당 용도로 쓰는 바닥면적 합계 5천㎡ 이상"],["그 밖에","다중이 이용하는 시설로서 건축조례로 정하는 건축물"],["설치 면적","대지면적의 100분의 10 이하 범위에서 건축조례로 정함"],["완화","용적률은 해당 지역 용적률의 1.2배 이하, 높이 제한은 1.2배 이하(조례 기준이 더 크면 조례)"],["활용","연간 60일 이내 문화행사·판촉활동 가능. 울타리 설치 등 이용을 막는 행위는 금지"]]}],"함정":"지역과 용도를 둘 다 맞춰야 한다. 1번과 2번과 3번은 지역은 맞고 용도가 어긋나며, 4번은 지역 자체가 어긋난다. 판매시설과 운수시설에 붙은 괄호 조건이 고르는 기준이다."},"34회-2차-087":{"한줄":"지적삼각보조점성과와 지적도근점성과의 열람·등본 발급은 지적소관청에 신청한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제26조제1항","원문":"제26조(지적기준점성과의 열람 및 등본발급)\n① 법 제27조에 따라 지적측량기준점성과 또는 그 측량부를 열람하거나 등본을 발급받으려는 자는 지적삼각점성과에 대해서는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다) 또는 지적소관청에 신청하고, 지적삼각보조점성과 및 지적도근점성과에 대해서는 지적소관청에 신청하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제27조","원문":"제27조(지적기준점성과의 보관 및 열람 등)\n① 시ㆍ도지사나 지적소관청은 지적기준점성과(지적기준점에 의한 측량성과를 말한다. 이하 같다)와 그 측량기록을 보관하고 일반인이 열람할 수 있도록 하여야 한다.\n② 지적기준점성과의 등본이나 그 측량기록의 사본을 발급받으려는 자는 국토교통부령으로 정하는 바에 따라 시ㆍ도지사나 지적소관청에 그 발급을 신청하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"지적삼각점성과의 신청기관 일부다. 보조점성과는 지적소관청이다."},{"번호":2,"판정":"-","설명":"지적삼각점성과의 신청기관이다. 보조점성과는 시·도지사에게 신청하지 않는다."},{"번호":3,"판정":"-","설명":"규칙 제26조제1항 그대로다."},{"번호":4,"판정":"-","설명":"한국국토정보공사는 지적측량수행자이지 성과 등본 발급기관이 아니다."},{"번호":5,"판정":"-","설명":"한국국토정보공사는 신청기관이 아니다."}],"개념":[{"종류":"비교","제목":"지적기준점성과 신청기관","왼쪽":{"이름":"지적삼각점성과","항목":["시·도지사 또는 지적소관청에 신청"]},"오른쪽":{"이름":"지적삼각보조점성과·지적도근점성과","항목":["지적소관청에 신청"]}},{"종류":"표","제목":"지적측량 기간(규칙 제25조)","머리":["구분","기간"],"행":[["측량기간","5일"],["측량검사기간","4일"],["지적기준점 15점 이하","4일(측량·검사 각각)"],["15점 초과","4일에 15점을 초과하는 4점마다 1일 가산"],["의뢰인과 수행자 합의","합의 기간. 전체의 4분의 3은 측량기간, 4분의 1은 검사기간"]]}],"함정":"삼각점은 시·도지사 또는 지적소관청, 보조점·도근점은 지적소관청이다. 보조점을 삼각점과 같이 보면 ①②를 고르게 된다."},"34회-2차-102":{"한줄":"공용부분이라는 뜻을 정한 규약을 폐지하면 공용부분의 취득자는 지체 없이 소유권보존등기를 신청한다.","근거":[{"법령":"부동산등기법","조문":"제47조제2항","원문":"제47조(규약상 공용부분의 등기와 규약폐지에 따른 등기)\n② 공용부분이라는 뜻을 정한 규약을 폐지한 경우에 공용부분의 취득자는 지체 없이 소유권보존등기를 신청하여야 한다."},{"법령":"부동산등기법","조문":"제40조제3항·제4항","원문":"제40조(등기사항)\n③ 구분건물에 「집합건물의 소유 및 관리에 관한 법률」 제2조제6호의 대지사용권(垈地使用權)으로서 건물과 분리하여 처분할 수 없는 것[이하 \"대지권\"(垈地權)이라 한다]이 있는 경우에는 등기관은 제2항에 따라 기록하여야 할 사항 외에 1동 건물의 등기기록의 표제부에 대지권의 목적인 토지의 표시에 관한 사항을 기록하고 전유부분의 등기기록의 표제부에는 대지권의 표시에 관한 사항을 기록하여야 한다.\n④ 등기관이 제3항에 따라 대지권등기를 하였을 때에는 직권으로 대지권의 목적인 토지의 등기기록에 소유권, 지상권, 전세권 또는 임차권이 대지권이라는 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제61조제4항·제5항","원문":"제61조(구분건물의 등기기록에 대지권등기가 되어 있는 경우)\n④ 토지의 소유권이 대지권인 경우에 대지권이라는 뜻의 등기가 되어 있는 토지의 등기기록에는 소유권이전등기, 저당권설정등기, 그 밖에 이와 관련이 있는 등기를 할 수 없다.\n⑤ 지상권, 전세권 또는 임차권이 대지권인 경우에는 제4항을 준용한다."},{"법령":"부동산등기법","조문":"제41조제3항","원문":"제41조(변경등기의 신청)\n③ 구분건물로서 그 대지권의 변경이나 소멸이 있는 경우에는 구분건물의 소유권의 등기명의인은 1동의 건물에 속하는 다른 구분건물의 소유권의 등기명의인을 대위하여 그 등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제46조제1항","원문":"제46조(구분건물의 표시에 관한 등기)\n① 1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 나머지 구분건물의 표시에 관한 등기를 동시에 신청하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전유부분의 표제부에 대지권의 표시에 관한 사항을 기록한다(법 제40조제3항)."},{"번호":2,"판정":"옳음","설명":"지상권·전세권·임차권이 대지권인 경우 토지 등기기록에는 대지권이라는 뜻의 등기 후 해당 권리와 관련된 등기를 할 수 없다(법 제61조제4항·제5항)."},{"번호":3,"판정":"옳음","설명":"대지권의 변경·소멸 시 구분소유자는 다른 구분건물의 소유권 등기명의인을 대위하여 신청할 수 있다(법 제41조제3항)."},{"번호":4,"판정":"옳음","설명":"일부 구분건물만 보존등기를 신청하면 나머지 구분건물의 표시등기를 동시에 신청해야 한다(법 제46조제1항)."},{"번호":5,"판정":"틀림","설명":"규약을 폐지하면 공용부분의 취득자는 소유권이전등기가 아니라 소유권보존등기를 신청한다(법 제47조제2항)."}],"개념":[{"종류":"표","제목":"구분건물 등기 요점","머리":["항목","내용","근거"],"행":[["1동 건물 표제부","소재와 지번, 건물명칭, 번호 기록. 대지권의 목적인 토지 표시 기록","법 제40조제2항·제3항"],["전유부분 표제부","건물번호, 대지권의 표시 기록","법 제40조제2항·제3항"],["대지권 토지 등기기록","대지권이라는 뜻을 직권 기록","법 제40조제4항"],["대지권 등기 후 건물 등기","대지권에도 같은 효력. 건물만 처분하는 등기는 불가","법 제61조제1항·제3항"],["일부만 보존등기","나머지 구분건물의 표시등기 동시 신청","법 제46조제1항"],["대지권 변경·소멸","다른 구분건물 소유자를 대위하여 신청 가능","법 제41조제3항"]]},{"종류":"비교","제목":"규약상 공용부분 등기","왼쪽":{"이름":"공용부분이라는 뜻의 등기","항목":["소유권의 등기명의인이 신청","소유권 외의 권리가 있으면 그 권리자의 승낙 필요"]},"오른쪽":{"이름":"규약 폐지","항목":["공용부분의 취득자가 신청","지체 없이 소유권보존등기를 신청"]}}],"함정":"규약을 폐지하면 공용부분이 일반 건물이 되므로 새로 소유권의 등기를 해야 한다. 등기명의인이 없으니 이전이 아니라 보존이다. ②는 저당권의 대상이 대지권인 전세권으로 한정된 문장이다.","개정":"선지 ②는 원 기출에서 「저당권설정등기」였던 부분을 「그 전세권을 목적으로 하는 저당권설정등기」로 한정했다. 법 제61조제5항이 제4항을 준용하는 문언이 토지소유권에 대한 저당권과 구분되지 않아 공식 복수정답(②,⑤)이던 문항을 ⑤ 단일정답으로 정리한 것이며, 법령 개정에 따른 변경은 아니다."},"34회-2차-106":{"한줄":"상속으로 취득세 과세물건을 공동상속인이 취득하면 상속인 각자가 자기 지분을 취득한 것으로 보되, 그 취득세는 공동상속인이 연대하여 납부한다.","근거":[{"법령":"지방세법","조문":"제7조제7항","원문":"⑦ 상속(피상속인이 상속인에게 한 유증 및 포괄유증과 신탁재산의 상속을 포함한다. 이하 이 장과 제3장에서 같다)으로 인하여 취득하는 경우에는 상속인 각자가 상속받는 취득물건(지분을 취득하는 경우에는 그 지분에 해당하는 취득물건을 말한다)을 취득한 것으로 본다. 이 경우 상속인의 납부의무에 관하여는 「지방세기본법」 제44조제1항 및 제5항을 준용한다."},{"법령":"지방세기본법","조문":"제44조제1항","원문":"① 공유물(공동주택의 공유물은 제외한다), 공동사업 또는 그 공동사업에 속하는 재산에 관계되는 지방자치단체의 징수금은 공유자 또는 공동사업자가 연대하여 납부할 의무를 진다."},{"법령":"소득세법","조문":"제2조의2제1항","원문":"① 제43조에 따라 공동사업에 관한 소득금액을 계산하는 경우에는 해당 공동사업자별로 납세의무를 진다. 다만, 제43조제3항에 따른 주된 공동사업자(이하 이 항에서 \"주된 공동사업자\"라 한다)에게 합산과세되는 경우 그 합산과세되는 소득금액에 대해서는 주된 공동사업자의 특수관계인은 같은 조 제2항에 따른 손익분배비율에 해당하는 그의 소득금액을 한도로 주된 공동사업자와 연대하여 납세의무를 진다."},{"법령":"소득세법","조문":"제2조의2제5항","원문":"⑤ 공동으로 소유한 자산에 대한 양도소득금액을 계산하는 경우에는 해당 자산을 공동으로 소유하는 각 거주자가 납세의무를 진다."},{"법령":"민법","조문":"제421조","원문":"제421조(소멸시효의 절대적 효력) 어느 연대채무자에 대하여 소멸시효가 완성한 때에는 그 부담부분에 한하여 다른 연대채무자도 의무를 면한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공유물에 관계되는 지방자치단체의 징수금은 공유자가 연대하여 납부한다. 다만 공동주택의 공유물은 연대납세 대상에서 뺀다(지방세기본법 제44조제1항)."},{"번호":2,"판정":"틀림","설명":"공동으로 소유한 자산의 양도소득세는 공유자 각자가 자기 몫의 납세의무를 진다. 연대하지 않는다(소득세법 제2조의2제5항)."},{"번호":3,"판정":"틀림","설명":"공동사업의 소득금액은 공동사업자별로 납세의무를 진다. 연대는 주된 공동사업자에게 합산과세되는 경우에 특수관계인이 손익분배비율에 해당하는 소득금액을 한도로 지는 것뿐이다(소득세법 제2조의2제1항)."},{"번호":4,"판정":"옳음","설명":"상속 취득은 상속인 각자가 지분만큼 취득한 것으로 보고, 납부의무는 지방세기본법 제44조제1항·제5항을 준용해 공동상속인이 연대한다(지방세법 제7조제7항)."},{"번호":5,"판정":"틀림","설명":"어느 연대납세의무자에 대해 소멸시효가 완성되면 그 부담부분에 한하여 다른 연대납세의무자도 의무를 면한다(민법 제421조, 국세기본법 제25조의2, 지방세기본법 제44조제5항 준용)."}],"개념":[{"종류":"표","제목":"연대납세의무가 생기는 경우와 각자 납세의무를 지는 경우","머리":["구분","납세의무","근거"],"행":[["공유물·공동사업·공동사업 재산에 관계되는 지방세 징수금","공유자·공동사업자 연대","지방세기본법 제44조제1항"],["공동주택의 공유물","연대 아님(제외)","지방세기본법 제44조제1항 괄호"],["공유물·공동사업 관계 국세 및 강제징수비","공유자·공동사업자 연대","국세기본법 제25조제1항"],["공동상속인의 취득세","공동상속인 연대","지방세법 제7조제7항"],["과점주주의 간주취득 취득세","과점주주 연대(지방세기본법 제44조 준용)","지방세법 제7조제5항"],["공동 소유 자산의 양도소득세","공유자 각자(연대 아님)","소득세법 제2조의2제5항"],["공동사업의 종합소득세","공동사업자별 각자","소득세법 제2조의2제1항"],["주된 공동사업자에게 합산과세되는 소득","특수관계인은 손익분배비율 소득금액 한도로 연대","소득세법 제2조의2제1항 단서"],["증여자가 직접 양도한 것으로 보는 양도소득","증여자와 수증자 연대","소득세법 제2조의2제3항"]]},{"종류":"표","제목":"연대납세의무에 준용하는 민법 규정(국세기본법 제25조의2, 지방세기본법 제44조제5항)","머리":["민법 조문","내용","효력"],"행":[["제413조·제414조","연대채무의 내용, 각 연대채무자에 대한 이행청구","채권자는 어느 연대채무자에게든 전부·일부 청구"],["제415조","한 사람에게 생긴 무효·취소","다른 연대채무자에 영향 없음"],["제416조","이행청구","다른 연대채무자에게도 효력"],["제419조","면제","그 채무자의 부담부분에 한하여 다른 연대채무자 이익"],["제421조","소멸시효 완성","그 부담부분에 한하여 다른 연대채무자도 의무를 면함"],["제423조","효력의 상대성","위 사항 외에는 다른 연대채무자에게 효력 없음"],["제425조~제427조","구상권","출재채무자의 구상, 통지, 무자력자의 부담부분 분담"]]}],"함정":"1번은 공유물이면 모두 연대한다고 외우면 속는다. 지방세기본법 제44조제1항 괄호에서 공동주택의 공유물이 빠진다. 2번과 3번은 소득세가 공유·공동사업을 각자 납세의무로 규정한다는 점을 놓친 선지다. 소득세에서 연대가 나오는 대표적인 경우는 주된 공동사업자 합산과세와 증여자 직접 양도 간주(제101조제2항)다. 5번은 소멸시효 완성이 부담부분 범위에서 다른 연대납세의무자에게도 미치는데 전혀 영향이 없다고 쓴 선지다."},"34회-2차-117":{"한줄":"분양권은 보유기간 1년 미만이면 양도소득과세표준의 100분의 70이다.","근거":[{"법령":"소득세법","조문":"제104조제1항제1호","원문":"1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 자산 제55조제1항에 따른 세율(분양권의 경우에는 양도소득 과세표준의 100분의 60)"},{"법령":"소득세법","조문":"제104조제1항제2호","원문":"2. 제94조제1항제1호 및 제2호에서 규정하는 자산으로서 그 보유기간이 1년 이상 2년 미만인 것 양도소득 과세표준의 100분의 40[주택(이에 딸린 토지로서 대통령령으로 정하는 토지를 포함한다. 이하 이 항에서 같다), 조합원입주권 및 분양권의 경우에는 100분의 60]"},{"법령":"소득세법","조문":"제104조제1항제3호","원문":"3. 제94조제1항제1호 및 제2호에 따른 자산으로서 그 보유기간이 1년 미만인 것 양도소득 과세표준의 100분의 50(주택, 조합원입주권 및 분양권의 경우에는 100분의 70)"}],"선지":[{"번호":1,"판정":"틀림","설명":"등기된 상가건물을 1년 미만 보유하고 양도하면 100분의 50이다. 100분의 40은 1년 이상 2년 미만 구간이다(소득세법 제104조제1항제3호·제2호)."},{"번호":2,"판정":"옳음","설명":"분양권은 보유기간 1년 미만이면 100분의 70이다(소득세법 제104조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"상가건물을 1년 이상 2년 미만 보유하면 100분의 40이다(소득세법 제104조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"조합원입주권을 1년 이상 2년 미만 보유하고 양도하면 100분의 60이다. 100분의 70은 1년 미만이다(소득세법 제104조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"분양권은 2년 이상 보유해도 100분의 60이다(소득세법 제104조제1항제1호 괄호)."}],"개념":[{"종류":"표","제목":"양도소득세율(소득세법 제104조제1항, 등기된 자산·2023년 양도 기준)","머리":["자산","1년 미만","1년 이상 2년 미만","2년 이상"],"행":[["토지·건물(주택 제외), 부동산에 관한 권리(조합원입주권·분양권 제외)","100분의 50","100분의 40","기본세율(제55조)"],["주택, 조합원입주권","100분의 70","100분의 60","기본세율(제55조)"],["분양권","100분의 70","100분의 60","100분의 60"],["미등기양도자산","100분의 70","100분의 70","100분의 70"],["비사업용 토지","기본세율+100분의 10 세율 적용 세액과 100분의 50 적용 세액 중 큰 세액","기본세율+100분의 10 세율 적용 세액과 100분의 40 적용 세액 중 큰 세액","기본세율+100분의 10(제104조제1항제8호 표)"]]},{"종류":"계산","제목":"양도소득과세표준 2억원일 때 산출세액(가정)","단계":[{"설명":"등기된 상가, 보유 2년 6개월: 1억5천만원 초과 3억원 이하 구간","식":"3,706만원 + (2억원 − 1억5천만원) × 38%","값":"5,606만원"},{"설명":"미등기양도자산","식":"2억원 × 70%","값":"1억4천만원"},{"설명":"분양권, 보유 10개월","식":"2억원 × 70%","값":"1억4천만원"},{"설명":"분양권, 보유 2년 6개월","식":"2억원 × 60%","값":"1억2천만원"},{"설명":"등기된 상가, 보유 6개월","식":"2억원 × 50%","값":"1억원"}]}],"함정":"분양권만 따로 외워야 한다. 상가·토지는 50, 40, 기본세율로 내려가지만 분양권은 70, 60, 60이어서 2년을 넘겨도 기본세율로 내려가지 않는다. 4번은 조합원입주권을 주택과 같은 구간표로 읽어야 하는데 70과 60을 섞은 선지다. 1번과 3번은 상가의 50, 40을 40, 30으로 한 단계씩 낮춰 쓴 숫자 함정이다."},"34회-1차-001":{"한줄":"용도의 다양성 때문에 한 토지에 둘 이상의 용도가 경합할 수 있고, 용도 전환과 합병·분할도 가능하다.","근거":[{"이론":"토지의 특성","내용":"자연적 특성은 부동성·영속성·부증성·개별성이다. 인문적 특성에는 용도의 다양성, 합병·분할의 가능성, 위치의 가변성이 있다. 용도의 다양성은 하나의 토지를 여러 용도로 쓸 수 있다는 뜻이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"용도의 다양성은 두 개 이상의 용도가 경합할 수 있게 하고, 용도 전환과 합병·분할을 가능하게 한다."},{"번호":2,"판정":"옳음","설명":"부증성은 토지의 물리적 공급을 늘릴 수 없게 하므로 이미 있는 토지를 집약적으로 이용해야 한다."},{"번호":3,"판정":"옳음","설명":"부동성으로 이동이 불가능해 주변 환경의 영향을 그대로 받으며, 외부효과가 나타난다."},{"번호":4,"판정":"옳음","설명":"영속성 때문에 토지에는 소모를 전제로 한 재생산이론과 물리적 감가상각이 적용되지 않는다."},{"번호":5,"판정":"옳음","설명":"개별성으로 같은 토지가 둘 있을 수 없어 완전한 대체재가 제약되고 비교가 어렵다."}],"개념":[{"종류":"표","제목":"자연적 특성과 파생현상","머리":["특성","뜻","파생현상"],"행":[["부동성(지리적 위치의 고정성)","위치를 옮길 수 없다","지역분석, 국지적 시장, 외부효과, 임장활동"],["영속성(비소모성)","사용해도 닳아 없어지지 않는다","재생산이론·감가상각 배제, 가격 보존, 소유이익과 이용이익 분리"],["부증성(비생산성)","물리적 양을 늘릴 수 없다","물리적 공급 한계, 지대·지가 발생, 토지이용 집약화"],["개별성(비동질성)","똑같은 토지가 없다","비교 곤란, 완전한 대체재 없음, 시장 비표준화"]]},{"종류":"표","제목":"인문적 특성","머리":["특성","뜻"],"행":[["용도의 다양성","한 토지에 여러 용도가 경합하고 전환될 수 있다"],["합병·분할의 가능성","필지 단위로 합치거나 나눌 수 있다"],["위치의 가변성","사회적·경제적·행정적 위치가 변한다"],["부동산의 인문적 위치","도로·교통 같은 인문 환경에 따라 가치가 달라진다"]]}],"함정":"용도의 다양성을 '동시에 경합 불가'로 뒤집은 선지를 맞는 말로 읽기 쉽다. 용도 경합과 전환이 가능하다는 것이 이 특성의 요지다."},"34회-1차-040":{"한줄":"동일수급권은 대상부동산과 대체·경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 다른 부동산이 존재하는 권역이며, 인근지역과 유사지역을 포함한다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제15호","원문":"\"동일수급권(同一需給圈)\"이란 대상부동산과 대체ㆍ경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 관계에 있는 다른 부동산이 존재하는 권역(圈域)을 말하며, 인근지역과 유사지역을 포함한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제13호","원문":"\"인근지역\"이란 감정평가의 대상이 된 부동산(이하 \"대상부동산\"이라 한다)이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제14호","원문":"\"유사지역\"이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"동일수급권의 정의 그대로이며 인근지역과 유사지역을 포함한다(규칙 제2조제15호)."},{"번호":2,"판정":"틀림","설명":"지역분석은 지역요인을 분석해 그 지역의 표준적 이용과 가격수준을 판정하는 것이다. 대상부동산의 최유효이용을 판정하는 것은 개별분석이다."},{"번호":3,"판정":"틀림","설명":"인근지역은 가치형성요인 중 개별요인이 아니라 지역요인을 공유하는 지역이다(규칙 제2조제13호)."},{"번호":4,"판정":"틀림","설명":"개별분석은 대상부동산의 개별요인을 분석해 최유효이용을 판정한다. 표준적 이용과 가격수준의 판정은 지역분석이다."},{"번호":5,"판정":"틀림","설명":"지역분석을 먼저 하고 그 결과를 바탕으로 개별분석을 한다."}],"개념":[{"종류":"비교","제목":"지역분석과 개별분석","왼쪽":{"이름":"지역분석","항목":["분석 대상: 대상부동산이 속한 지역","분석 요인: 일반요인·지역요인","판정 내용: 지역의 표준적 이용과 가격수준","순서: 먼저 실시","범위: 거시적·전체적"]},"오른쪽":{"이름":"개별분석","항목":["분석 대상: 대상부동산 자체","분석 요인: 개별요인","판정 내용: 대상부동산의 최유효이용과 구체적 가격","순서: 지역분석 다음","범위: 미시적·개별적"]}},{"종류":"표","제목":"인근지역·유사지역·동일수급권","머리":["용어","정의 요지","조문"],"행":[["인근지역","대상부동산이 속한 지역으로서 이용이 동질적이고 지역요인을 공유하는 지역","규칙 제2조제13호"],["유사지역","대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역","규칙 제2조제14호"],["동일수급권","대체·경쟁 관계가 성립하고 가치 형성에 서로 영향을 미치는 부동산이 존재하는 권역. 인근지역과 유사지역을 포함","규칙 제2조제15호"],["비교표준지 선정 순서","인근지역의 표준지를 먼저 고르고, 적절한 표준지가 없으면 동일수급권 안 유사지역의 표준지를 고름","규칙 제14조제2항제1호"]]}],"함정":"③에서 인근지역은 지역요인을 공유하는 지역인데 개별요인으로 바꿔 쓴다. ②와 ④는 지역분석의 결과(표준적 이용·가격수준)와 개별분석의 결과(최유효이용)를 서로 바꿔 썼다. 분석은 지역분석이 먼저다."},"34회-1차-072":{"한줄":"묵시갱신이 되면 전임대차에 대하여 제3자가 제공한 담보는 기간 만료로 소멸한다.","근거":[{"법령":"민법","조문":"제639조제2항","원문":"전항의 경우에 전임대차에 대하여 제삼자가 제공한 담보는 기간의 만료로 인하여 소멸한다."},{"법령":"민법","조문":"제626조제1항","원문":"임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다."},{"법령":"민법","조문":"제618조","원문":"임대차는 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"임대차는 임대인에게 처분권한이 없어도 채권계약으로서 유효하다(제618조)."},{"번호":2,"판정":"옳음","설명":"임대차 존속기간 20년 상한을 정한 제651조가 2016.1.6. 삭제되어 영구 약정도 허용된다."},{"번호":3,"판정":"옳음","설명":"필요비상환청구권과 차임지급의무는 대가 관계에 있어 임차인은 필요비 한도에서 차임 지급을 거절할 수 있다(제626조제1항, 판례)."},{"번호":4,"판정":"틀림","설명":"묵시갱신 때 전임대차의 제3자 담보는 소멸한다(제639조제2항). 보증인·물상보증인이 계속 책임을 지지 않는다."},{"번호":5,"판정":"옳음","설명":"원상회복의무에는 임대인이 목적물을 종전 용도에 맞게 다시 사용할 수 있게 하는 협력 의무가 포함된다(판례)."}],"개념":[{"종류":"표","제목":"묵시의 갱신(제639조)","머리":["쟁점","내용","근거"],"행":[["요건","기간 만료 후 임차인이 사용·수익을 계속하고 임대인이 상당한 기간 내에 이의하지 않음","제639조제1항"],["효과","전임대차와 동일한 조건으로 다시 임대차한 것으로 봄","제639조제1항"],["존속기간","기간의 약정 없는 임대차로 보아 각 당사자가 해지통고 가능","제639조제1항 단서, 제635조"],["제3자 담보","기간 만료로 소멸(보증, 저당권 등)","제639조제2항"],["주택·상가","주택임대차보호법은 묵시갱신 2년, 상가건물 임대차보호법은 1년","주임법 제6조, 상임법 제10조제4항"]]},{"종류":"표","제목":"임대차 존속기간 관련 정리","머리":["구분","내용","근거"],"행":[["최장 기간 제한","없음(영구 약정 허용)","제651조 삭제 <2016.1.6>"],["처분권한 없는 자의 단기임대차","건물 3년, 토지 5년 등으로 제한","제619조"],["기간 약정 없는 임대차","언제든 해지통고, 토지·건물은 임대인 6개월 임차인 1개월","제635조"],["차임연체 해지(건물)","2기의 차임액에 달하면 해지","제640조"]]}],"함정":"임대차 기간은 20년을 넘지 못한다는 구법 지식으로 2번을 틀린 선지로 고르기 쉽다. 제651조는 삭제되어 영구 약정도 허용된다. 묵시갱신 때 제3자 담보가 소멸하는 점은 보증인 보호 취지다.","개정":"제651조(임대차 존속기간 20년 제한)는 2016.1.6. 삭제되었다. 이전에는 20년을 넘는 약정 기간이 20년으로 단축되었다."},"34회-1차-078":{"한줄":"확정일자를 받은 임차인도 경매에서 우선변제를 받으려면 배당요구종기까지 배당요구를 해야 한다.","근거":[{"법령":"주택임대차보호법","조문":"제3조의2제2항","원문":"제3조제1항ㆍ제2항 또는 제3항의 대항요건(對抗要件)과 임대차계약증서(제3조제2항 및 제3항의 경우에는 법인과 임대인 사이의 임대차계약증서를 말한다)상의 확정일자(確定日字)를 갖춘 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매(公賣)를 할 때에 임차주택(대지를 포함한다)의 환가대금(換價代金)에서 후순위권리자(後順位權利者)나 그 밖의 채권자보다 우선하여 보증금을 변제(辨濟)받을 권리가 있다."},{"법령":"주택임대차보호법","조문":"제6조제1항·제2항·제3항","원문":"①…그 기간이 끝난 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 임차인이 임대차기간이 끝나기 2개월 전까지 통지하지 아니한 경우에도 또한 같다. ②제1항의 경우 임대차의 존속기간은 2년으로 본다. ③2기(期)의 차임액(借賃額)에 달하도록 연체하거나 그 밖에 임차인으로서의 의무를 현저히 위반한 임차인에 대하여는 제1항을 적용하지 아니한다."},{"법령":"주택임대차보호법","조문":"제3조제4항","원문":"임차주택의 양수인(讓受人)(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인(賃貸人)의 지위를 승계한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"인도와 주민등록을 마친 다음 날 오전 영시부터 대항력이 생긴다(제3조제1항, 판례). 계약일이 1월 5일이므로 1월 6일 오전 영시다."},{"번호":2,"판정":"틀림","설명":"대항요건과 확정일자를 갖춘 임차인도 배당요구종기까지 배당요구를 해야 우선변제를 받는다(판례). 배당요구가 없으면 배당에서 제외된다."},{"번호":3,"판정":"옳음","설명":"대항력 있는 임차주택의 양수인은 임대인의 지위를 승계하므로 양도인 乙은 보증금반환의무를 면한다(제3조제4항)."},{"번호":4,"판정":"옳음","설명":"2기의 차임액에 달하는 연체가 있으면 묵시적 갱신이 인정되지 않는다(제6조제3항)."},{"번호":5,"판정":"옳음","설명":"묵시적 갱신의 존속기간은 2년으로 본다(제6조제2항)."}],"개념":[{"종류":"표","제목":"주택임대차 갱신 정리","머리":["구분","요건·효과","근거"],"행":[["묵시적 갱신","임대인은 기간 만료 6개월~2개월 전, 임차인은 2개월 전까지 통지하지 않으면 전 임대차와 동일 조건으로 갱신. 존속기간 2년","제6조제1항·제2항"],["묵시적 갱신 배제","2기 차임 연체 또는 의무 현저 위반","제6조제3항"],["묵시적 갱신 후 해지","임차인은 언제든 통지, 임대인이 통지를 받은 날부터 3개월 후 효력","제6조의2"],["계약갱신요구권","1회 행사, 갱신 존속기간 2년, 임대인은 법정 사유 없이 거절 못 함(실거주 포함)","제6조의3"],["최단 존속기간","기간 미정 또는 2년 미만이면 2년으로 봄","제4조제1항"]]},{"종류":"흐름","제목":"경매 시 임차인의 보증금 회수 절차","단계":[{"이름":"대항요건과 확정일자","설명":"인도 + 주민등록 + 임대차계약증서의 확정일자 (우선변제권은 대항요건과 확정일자를 모두 갖춘 때부터)"},{"이름":"경매 개시","설명":"경매가 개시되면 법원이 배당요구종기를 정해 공고"},{"이름":"배당요구","설명":"배당요구종기까지 배당요구를 해야 우선변제를 받을 수 있음(판례)"},{"이름":"인도","설명":"임차주택을 양수인에게 인도해야 보증금을 받을 수 있음(제3조의2제3항)"}]}],"함정":"대항력과 확정일자가 있으면 배당요구 없이도 순위대로 배당받는다고 오해하기 쉽다. 우선변제는 배당요구를 전제로 한다. 대항력이 있는 임차인은 낙찰자에게 보증금을 청구할 수도 있어서 배당요구 여부를 선택할 수 있다."},"34회-2차-008":{"한줄":"자격증 사본은 제출 서류 목록에 없고 등록관청이 자격증을 발급한 시·도지사에게 자격 확인을 요청하므로 1번이 틀렸다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제4조제1항 본문(후단)","원문":"이 경우 등록관청은 법 제5조제2항에 따라 공인중개사 자격증을 발급한 시ㆍ도지사에게 개설등록을 하려는 자(법인의 경우에는 대표자를 포함한 공인중개사인 임원 또는 사원을 말한다)의 공인중개사 자격 확인을 요청하여야 하고, 「전자정부법」 제36조제1항에 따라 행정정보의 공동이용을 통하여 법인 등기사항증명서(신청인이 법인인 경우에만 해당한다)과 건축물대장(「건축법」 제20조제5항에 따른 가설건축물대장은 제외한다. 이하 같다)을 확인하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제4조제1항제3호·제4호","원문":"3. 법 제34조제1항의 규정에 따른 실무교육의 수료확인증 사본(영 제36조제1항에 따라 실무교육을 위탁받은 기관 또는 단체가 실무교육 수료 여부를 등록관청이 전자적으로 확인할 수 있도록 조치한 경우는 제외한다) 4. 여권용 사진"},{"법령":"공인중개사법 시행규칙","조문":"제4조제1항제5호","원문":"5. 건축물대장에 기재된 건물(…)에 중개사무소를 확보(…)하였음을 증명하는 서류. 다만, 건축물대장에 기재되지 아니한 건물에 중개사무소를 확보하였을 경우에는 건축물대장 기재가 지연되는 사유를 적은 서류도 함께 내야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제4조제1항제6호나목","원문":"나. 「상법」 제614조의 규정에 따른 영업소의 등기를 증명할 수 있는 서류"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격증 사본은 제출 서류가 아니다. 등록관청이 시·도지사에게 자격 확인을 요청한다(칙 제4조제1항)."},{"번호":2,"판정":"옳음","설명":"사용승인 후 대장 미기재 건물이면 기재 지연 사유서를 함께 낸다(칙 제4조제1항제5호 단서)."},{"번호":3,"판정":"옳음","설명":"여권용 사진을 낸다(칙 제4조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"위탁기관이 전자 확인 조치를 한 경우 수료확인증 사본 제출이 면제된다(칙 제4조제1항제3호 괄호)."},{"번호":5,"판정":"옳음","설명":"외국에 주된 영업소를 둔 법인은 상법 제614조의 영업소 등기 증명서류를 낸다(칙 제4조제1항제6호나목)."}],"개념":[{"종류":"흐름","제목":"중개사무소 개설등록 절차","단계":[{"이름":"실무교육","설명":"등록신청일 전 1년 이내 시·도지사 실시 실무교육 수료(법인은 사원·임원 전원). 폐업 후 1년 이내 재신청, 소속공인중개사 고용관계 종료 신고 후 1년 이내 신청은 면제(법 제34조제1항)"},{"이름":"신청서 제출","설명":"중개사무소 소재지 관할 등록관청에 개설등록신청서와 첨부서류 제출(칙 제4조제1항)"},{"이름":"자격·대장 확인","설명":"등록관청이 자격증 발급 시·도지사에게 자격 확인 요청, 법인 등기사항증명서·건축물대장은 행정정보 공동이용으로 확인"},{"이름":"등록·통지","설명":"신청받은 날부터 7일 이내에 법인/공인중개사로 구분해 등록하고 서면 통지(칙 제4조제2항)"},{"이름":"보증 설정·신고","설명":"업무개시 전 손해배상책임 보증을 설정하고 증명서류를 갖춰 등록관청에 신고(영 제24조제2항)"}]},{"종류":"표","제목":"개설등록 신청 시 서류","머리":["서류","제출 여부","근거"],"행":[["공인중개사자격증 사본","제출하지 않음(시·도지사에게 자격 확인 요청)","칙 제4조제1항"],["실무교육 수료확인증 사본","제출(전자 확인 조치된 경우 제외)","칙 제4조제1항제3호"],["여권용 사진","제출","칙 제4조제1항제4호"],["사무소 확보 증명서류","제출(대장 미기재 시 지연 사유서 추가)","칙 제4조제1항제5호"],["외국인·외국법인 서류","결격사유 부존재 증명서류 / 외국법인은 영업소 등기 증명서류","칙 제4조제1항제6호"]]}],"함정":"법인 등기사항증명서와 건축물대장은 등록관청이 직접 확인하므로 신청인이 낼 서류가 아니다. 자격증 사본도 같은 방식이라 1번이 그럴듯해 보인다."},"34회-2차-025":{"한줄":"협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리해야 하므로 5번이 옳다.","근거":[{"법령":"공인중개사법","조문":"제42조제4항","원문":"협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다."},{"법령":"공인중개사법 시행령","조문":"제32조제1항","원문":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다."},{"법령":"공인중개사법","조문":"제41조제2항","원문":"협회는 법인으로 하며, 정관을 제정하거나 변경하려는 경우에는 국토교통부장관의 인가를 받아야 한다. <개정 2026.2.27>"},{"법령":"공인중개사법 시행령","조문":"제34조제3호","원문":"책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."},{"법령":"공인중개사법 시행령","조문":"제35조","원문":"협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"총회 의결내용은 지체 없이 국토교통부장관에게 보고한다(법 제41조의2제3항, 영 제32조제1항)."},{"번호":2,"판정":"틀림","설명":"일간신문 또는 협회보에 공시하고 홈페이지에도 게시해야 한다. 어느 하나만 하면 되는 것이 아니다(영 제35조)."},{"번호":3,"판정":"틀림","설명":"정관 제정·변경은 국토교통부장관의 인가다(법 제41조제2항)."},{"번호":4,"판정":"틀림","설명":"공제료 수입액의 100분의 10 이상이다(영 제34조제3호)."},{"번호":5,"판정":"옳음","설명":"법 제42조제4항."}],"개념":[{"종류":"표","제목":"협회 관련 보고·인가·승인 주체","머리":["사항","내용","근거"],"행":[["정관 제정·변경","국토교통부장관 인가(총회 의결 사항)","법 제41조제2항, 제41조의2제3항"],["총회 의결내용","지체 없이 국토교통부장관에게 보고","법 제41조의2제3항, 영 제32조제1항"],["윤리규정","국토교통부장관 승인을 받아 제정","법 제41조의3제1항"],["공제규정 제정·변경","국토교통부장관 승인","법 제42조제2항"],["책임준비금 다른 용도 사용","국토교통부장관 승인","법 제42조제4항"],["시·도회·지회 설치","시·도회는 시·도지사에게, 지회는 등록관청에 신고","영 제32조제2항"]]},{"종류":"표","제목":"공제사업 수치","머리":["항목","내용","근거"],"행":[["회계","다른 회계와 구분해 별도 관리, 손해배상기금과 복지기금으로 구분","법 제42조제4항, 영 제34조제2호"],["책임준비금 적립비율","공제료 수입액의 100분의 10 이상","영 제34조제3호"],["운용실적 공시","회계연도 종료 후 3개월 이내, 일간신문 또는 협회보 공시 + 협회 홈페이지 게시","영 제35조. 위반 시 500만원 이하 과태료(법 제51조제2항제7호)"],["운영위원회","공제사업을 심의하고 업무집행을 감독, 위원 19명 이내","법 제42조의2"],["공제사업의 성격","비영리, 회원 간 상호부조","영 제31조제6호"]]}],"함정":"협회가 법정단체가 되면서 협회 관련 인가·보고 주체는 모두 국토교통부장관이다. 시·도지사로 바꿔 놓은 선지(1, 3)를 먼저 걸러낸다. 영 제35조는 '또는 협회보에 공시하고 홈페이지에 게시'로, 두 방식을 모두 해야 한다.","개정":"법 제41조가 2026.2.27 개정되어 협회는 법률로 설립되고(설립인가·창립총회 제도 삭제, 제41조제3항 삭제), 정관 제정·변경만 국토교통부장관의 인가를 받는다. 명칭도 '한국공인중개사협회'로 쓴다. 이에 따라 구 선지(창립총회 개최 인원)를 정관 변경 인가 주체를 묻는 선지로 바꿨고 정답은 5번 그대로다."},"34회-2차-028":{"한줄":"단독주택 중 다중주택과 공관은 일부 임대 예외에서 빠진다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제14조","원문":"① 법 제17조제1항에서 \"대통령령으로 정하는 사유가 있는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n9. 다음 각 목의 건축물을 취득하여 실제로 이용하는 자가 해당 건축물의 일부를 임대하는 경우\n가. 「건축법 시행령」 별표 1 제1호의 단독주택[다중주택 및 공관(公館)은 제외한다]\n나. 「건축법 시행령」 별표 1 제2호의 공동주택(기숙사는 제외한다)\n다. 「건축법 시행령」 별표 1 제3호의 제1종 근린생활시설\n라. 「건축법 시행령」 별표 1 제4호의 제2종 근린생활시설\n10. 「산업집적활성화 및 공장설립에 관한 법률」 제2조제1호에 따른 공장을 취득하여 실제로 이용하는 자가 해당 공장의 일부를 임대하는 경우"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제17조","원문":"① 제11조에 따라 토지거래계약을 허가받은 자는 대통령령으로 정하는 사유가 있는 경우 외에는 5년의 범위에서 대통령령으로 정하는 기간에 그 토지를 허가받은 목적대로 이용하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제1종 근린생활시설을 취득하여 실제로 이용하는 자가 일부를 임대하는 경우는 예외사유이다(시행령 제14조제1항제9호다목)."},{"번호":2,"판정":"틀림","설명":"단독주택 중 다중주택은 예외에서 제외된다(시행령 제14조제1항제9호가목). 일부 임대는 이용의무 위반이다."},{"번호":3,"판정":"옳음","설명":"공장을 취득하여 실제로 이용하는 자가 일부를 임대하는 경우는 예외사유이다(시행령 제14조제1항제10호)."},{"번호":4,"판정":"옳음","설명":"제2종 근린생활시설의 일부 임대는 예외사유이다(시행령 제14조제1항제9호라목)."},{"번호":5,"판정":"옳음","설명":"공동주택(기숙사 제외)인 다세대주택의 일부 임대는 예외사유이다(시행령 제14조제1항제9호나목)."}],"개념":[{"종류":"표","제목":"토지 이용의무 기간(시행령 제14조제2항)","머리":["허가 목적","기간"],"행":[["자기 거주용 주택용지, 주민 복지·편익시설, 농업·임업·어업 경영","토지 취득일부터 2년"],["공익사업, 지정 지역·지구 사업, 허가구역 지정 당시 사업 시행자 등(법 제12조제1호 라~바목)","토지 취득일부터 4년(분양 목적은 개발 착수 후 4년 이내 분양 완료 시 완료한 때)"],["협의양도·수용 대체토지 취득","토지 취득일부터 2년"],["현상 보존 목적","토지 취득일부터 5년"],["그 밖의 경우","토지 취득일부터 5년"]]},{"종류":"표","제목":"이행강제금(시행령 제16조제3항)","머리":["위반 유형","금액"],"행":[["방치","토지 취득가액의 10%"],["직접 이용하지 않고 임대","토지 취득가액의 7%"],["허가관청 승인 없이 이용목적 변경","토지 취득가액의 5%"],["그 밖의 경우","토지 취득가액의 7%"],["부과 절차","문서 이행명령(이행기간 3개월 이내) → 문서 계고 → 부과. 이의제기는 부과처분 고지일부터 30일 이내"]]}],"함정":"일부 임대 예외는 단독주택 중 다중주택·공관과 공동주택 중 기숙사만 빠진다. 다중주택을 다가구주택이나 다세대주택과 섞어 기억하면 오답으로 간다."},"34회-2차-030":{"한줄":"법인묘지에는 폭 5미터 이상의 도로와 각 분묘로 통하는 진출입로를 설치한다.","근거":[{"법령":"장사 등에 관한 법률 시행령","조문":"별표 2 제2호가목","원문":"가족묘지는 가족당 1개소로 제한하되, 그 면적은 100제곱미터 이하여야 한다."},{"법령":"장사 등에 관한 법률 시행령","조문":"별표 2 제4호라목","원문":"법인묘지에는 폭 5미터 이상의 도로와 그 도로로부터 각 분묘로 통하는 충분한 진출입로를 설치하고, 주차장을 마련하여야 한다."},{"법령":"장사 등에 관한 법률","조문":"제14조","원문":"① 국가, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장이 아닌 자는 다음 각 호의 구분에 따른 묘지(이하 \"사설묘지\"라 한다)를 설치ㆍ관리할 수 있다.\n1. 개인묘지 : 1기의 분묘 또는 해당 분묘에 매장된 자와 배우자 관계였던 자의 분묘를 같은 구역 안에 설치하는 묘지\n⑤ 시장등은 묘지의 설치ㆍ관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정하여 법인묘지의 설치ㆍ관리를 허가할 수 있다."},{"법령":"장사 등에 관한 법률 시행령","조문":"제7조","원문":"법 제9조제2항에 따른 매장ㆍ화장 및 개장의 방법과 기준은 다음 각 호와 같다.\n나. 화장한 유골을 매장하는 경우 매장 깊이는 지면으로부터 30센티미터 이상이어야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"가족묘지는 가족당 1개소, 100㎡ 이하이다(시행령 별표 2 제2호가목)."},{"번호":2,"판정":"옳음","설명":"개인묘지의 정의이다(법 제14조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"도로 폭은 5미터 이상이다(시행령 별표 2 제4호라목)."},{"번호":4,"판정":"옳음","설명":"화장한 유골의 매장 깊이는 30센티미터 이상이다. 시신이나 화장하지 않은 유골은 1미터 이상이다(시행령 제7조제1호)."},{"번호":5,"판정":"옳음","설명":"법인묘지는 묘지의 설치·관리를 목적으로 「민법」에 따라 설립된 재단법인에 한정하여 허가할 수 있다(법 제14조제5항). 사단법인은 허가받을 수 없다."}],"개념":[{"종류":"표","제목":"사설묘지 4종","머리":["구분","내용","절차","면적"],"행":[["개인묘지","1기의 분묘 또는 그 분묘에 묻힌 자와 배우자 관계였던 자의 분묘","설치 후 30일 이내 시장등에게 신고(법 제14조제2항)","30㎡ 초과 금지(법 제18조제2항)"],["가족묘지","「민법」에 따라 친족관계였던 자의 분묘","시장등의 허가","가족당 1개소, 100㎡ 이하"],["종중·문중묘지","종중·문중 구성원의 분묘","시장등의 허가","종중·문중별 1개소, 1천㎡ 이하"],["법인묘지","법인이 불특정 다수인의 분묘를 설치","시장등의 허가(재단법인에 한정)","10만㎡ 이상"]]},{"종류":"표","제목":"설치기준 숫자","머리":["항목","기준","근거"],"행":[["매장 깊이","시신·화장하지 않은 유골 1미터 이상, 화장한 유골 30센티미터 이상","시행령 제7조"],["봉분·평분 높이","봉분 1미터, 평분 50센티미터 이하","시행령 별표 2"],["분묘 1기 구역","10㎡(합장 15㎡) 초과 금지. 개인묘지는 해당 없음","법 제18조제1항"],["분묘 설치기간","30년. 연장 신청 시 1회에 한하여 30년 연장","법 제19조제1·2항"],["법인묘지 도로","폭 5미터 이상 도로와 진출입로, 주차장","시행령 별표 2 제4호라목"]]}],"함정":"법인묘지 도로 폭 5미터를 4미터로 바꿔 놓았다. 개인묘지는 신고, 나머지 셋은 허가이고, 법인묘지는 재단법인만 받을 수 있다는 점도 함께 묻는다."},"34회-2차-051":{"한줄":"행정청인 시행자도 타인의 토지에 출입하려는 날의 7일 전까지 소유자·점유자·관리인에게 일시와 장소를 알려야 한다. 면제되는 것은 허가이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제130조제2항~제6항","원문":"② 제1항에 따라 타인의 토지에 출입하려는 자는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아야 하며, 출입하려는 날의 7일 전까지 그 토지의 소유자ㆍ점유자 또는 관리인에게 그 일시와 장소를 알려야 한다. 다만, 행정청인 도시ㆍ군계획시설사업의 시행자는 허가를 받지 아니하고 타인의 토지에 출입할 수 있다.\n③ 제1항에 따라 타인의 토지를 재료 적치장 또는 임시통로로 일시사용하거나 나무, 흙, 돌,  그 밖의 장애물을 변경 또는 제거하려는 자는 토지의 소유자 ㆍ점유자 또는 관리인의 동의를 받아야 한다.\n④ 제3항의 경우 토지나 장애물의 소유자ㆍ점유자 또는 관리인이 현장에 없거나 주소 또는 거소가 불분명하여 그 동의를 받을 수 없는 경우에는 행정청인 도시ㆍ군계획시설사업의 시행자는 관할 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 그 사실을 통지하여야 하며, 행정청이 아닌 도시ㆍ군계획시설사업의 시행자는 미리 관할 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 허가를 받아야 한다.\n⑤ 제3항과 제4항에 따라 토지를 일시 사용하거나 장애물을 변경 또는 제거하려는 자는 토지를 사용하려는 날이나 장애물을 변경 또는 제거하려는 날의 3일 전까지 그 토지나 장애물의 소유자ㆍ점유자 또는 관리인에게 알려야 한다.\n⑥ 일출 전이나 일몰 후에는 그 토지 점유자의 승낙 없이 택지나 담장 또는 울타리로 둘러싸인 타인의 토지에 출입할 수 없다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"법 제131조제2항·제3항","원문":"② 제1항에 따른 손실 보상에 관하여는 그 손실을 보상할 자와 손실을 입은 자가 협의하여야 한다.\n③ 손실을 보상할 자나 손실을 입은 자는 제2항에 따른 협의가 성립되지 아니하거나 협의를 할 수 없는 경우에는 관할 토지수용위원회에 재결을 신청할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"행정청인 도시·군계획시설사업 시행자는 허가를 받지 않을 뿐 출입 7일 전 통지 의무는 그대로다(법 제130조제2항)."},{"번호":2,"판정":"틀림","설명":"동의 없이 일시 사용하는 경우 행정청이 아닌 시행자는 미리 허가를 받아야 하고, 행정청인 시행자는 시장·군수에게 통지한다. 사용한 날부터 14일 이내라는 기한은 없다(법 제130조제4항)."},{"번호":3,"판정":"틀림","설명":"일출 전이나 일몰 후에는 점유자의 승낙 없이 택지나 담장·울타리로 둘러싸인 타인의 토지에 출입할 수 없다. 허가가 있어도 같다(법 제130조제6항)."},{"번호":4,"판정":"틀림","설명":"손실보상 협의가 성립하지 않거나 협의할 수 없으면 관할 토지수용위원회에 재결을 신청할 수 있다. 국토교통부장관 조정을 먼저 거치는 규정은 없다(법 제131조제3항)."},{"번호":5,"판정":"틀림","설명":"행정청인 도시·군계획시설사업 시행자는 허가 없이 출입할 수 있다(법 제130조제2항 단서)."}],"개념":[{"종류":"표","제목":"타인 토지 출입·일시 사용(법 제130조)","머리":["항목","내용"],"행":[["허가","특별시장·광역시장·특별자치시장·특별자치도지사·시장 또는 군수의 허가. 행정청인 시행자는 불요(제130조②)"],["출입 통지","출입하려는 날의 7일 전까지 소유자·점유자·관리인에게 일시와 장소 통지(제130조②)"],["재료 적치장·임시통로 일시 사용, 장애물 변경·제거","소유자·점유자·관리인의 동의(제130조③)"],["동의를 받을 수 없을 때","행정청인 시행자는 시장·군수에게 통지, 행정청이 아닌 시행자는 미리 허가(제130조④)"],["일시 사용 통지","사용하려는 날 3일 전까지(제130조⑤)"],["시간 제한","일출 전·일몰 후 택지·울타리 안은 점유자 승낙 필요(제130조⑥)"]]},{"종류":"흐름","제목":"출입에 따른 손실보상(법 제131조)","단계":[{"이름":"손실 발생","설명":"출입·일시 사용·장애물 제거로 손실을 입은 자(제131조①)"},{"이름":"협의","설명":"보상할 자와 손실을 입은 자가 협의(제131조②)"},{"이름":"재결 신청","설명":"협의가 안 되거나 할 수 없으면 관할 토지수용위원회에 신청(제131조③)"},{"이름":"준용","설명":"재결에는 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제83조~제87조 준용(제131조④)"}]}],"함정":"행정청은 허가를 받지 않는다는 규정을 통지까지 면제된다고 넓혀 읽기 쉽다. 면제 대상은 허가뿐이다."},"34회-2차-054":{"한줄":"원형지를 공장 부지로 직접 사용하는 자는 경쟁입찰로 선정하고, 2회 이상 유찰되면 수의계약을 할 수 있다.","근거":[{"법령":"도시개발법 시행령","조문":"영 제55조의2제6항","원문":"⑥ 법 제25조의2제9항에 따른 원형지개발자의 선정은 수의계약의 방법으로 한다. 다만, 법 제25조의2제1항제5호에 해당하는 원형지개발자의 선정은 경쟁입찰의 방식으로 하며, 경쟁입찰이 2회 이상 유찰된 경우에는 수의계약의 방법으로 할 수 있다."},{"법령":"도시개발법","조문":"법 제25조의2제1항·제5항·제6항","원문":"① 시행자는 도시를 자연친화적으로 개발하거나 복합적ㆍ입체적으로 개발하기 위하여 필요한 경우에는 대통령령으로 정하는 절차에 따라 미리 지정권자의 승인을 받아 다음 각 호의 어느 하나에 해당하는 자에게 원형지를 공급하여 개발하게 할 수 있다. 이 경우 공급될 수 있는 원형지의 면적은 도시개발구역 전체 토지 면적의 3분의 1 이내로 한정한다.\n5. 원형지를 학교나 공장 등의 부지로 직접 사용하는 자\n⑤ 지정권자는 제1항에 따라 승인을 할 때에는 용적률 등 개발밀도, 토지용도별 면적 및 배치, 교통처리계획 및 기반시설의 설치 등에 관한 이행조건을 붙일 수 있다.\n⑥ 원형지개발자(국가 및 지방자치단체는 제외한다)는 10년의 범위에서 대통령령으로 정하는 기간 안에는 원형지를 매각할 수 없다. 다만, 이주용 주택이나 공공ㆍ문화 시설 등 대통령령으로 정하는 경우로서 미리 지정권자의 승인을 받은 경우에는 예외로 한다."},{"법령":"도시개발법 시행령","조문":"영 제55조의2제3항·제5항·제7항","원문":"③ 법 제25조의2제6항 본문에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 기간 중 먼저 끝나는 기간을 말한다.\n1. 원형지에 대한 공사완료 공고일부터 5년\n2. 원형지 공급 계약일부터 10년\n⑤ 시행자는 법 제25조의2제8항 각 호의 어느 하나에 해당하는 사유가 발생한 경우에 원형지개발자에게 2회 이상 시정을 요구하여야 하고, 원형지개발자가 시정하지 아니한 경우에는 원형지 공급계약을 해제할 수 있다. 이 경우 원형지개발자는 시행자의 시정 요구에 대하여 의견을 제시할 수 있다.\n⑦ 법 제25조의2제9항에 따른 원형지 공급가격은 개발계획이 반영된 원형지의 감정가격에 시행자가 원형지에 설치한 기반시설 등의 공사비를 더한 금액을 기준으로 시행자와 원형지개발자가 협의하여 결정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제25조의2제1항제5호의 원형지개발자는 경쟁입찰로 선정하고, 경쟁입찰이 2회 이상 유찰되면 수의계약이 가능하다(영 제55조의2제6항)."},{"번호":2,"판정":"틀림","설명":"지정권자는 승인할 때 용적률 등 개발밀도, 토지용도별 면적·배치, 교통처리계획, 기반시설 설치 등에 관한 이행조건을 붙일 수 있다(법 제25조의2제5항)."},{"번호":3,"판정":"틀림","설명":"공급가격은 감정가격에 기반시설 등 공사비를 더한 금액을 기준으로 시행자와 원형지개발자가 협의하여 결정한다. 시·도 조례로 정하지 않는다(영 제55조의2제7항)."},{"번호":4,"판정":"틀림","설명":"국가와 지방자치단체는 매각 제한 대상에서 제외된다. 제한 기간도 공사완료 공고일부터 5년과 공급 계약일부터 10년 중 먼저 끝나는 기간이다(법 제25조의2제6항, 영 제55조의2제3항)."},{"번호":5,"판정":"틀림","설명":"시행자는 2회 이상 시정을 요구하고 이행하지 않을 때 공급계약을 해제할 수 있다(영 제55조의2제5항)."}],"개념":[{"종류":"표","제목":"원형지 공급·개발(법 제25조의2, 영 제55조의2)","머리":["항목","내용"],"행":[["공급 상한","도시개발구역 전체 토지면적의 3분의 1 이내"],["공급 대상","국가·지방자치단체, 공공기관, 지방공사, 공모에서 선정된 자, 학교·공장 부지로 직접 사용하는 자"],["승인","지정권자의 승인. 개발밀도 등 이행조건을 붙일 수 있음"],["원형지개발자 선정","원칙 수의계약. 학교·공장 부지 직접 사용자는 경쟁입찰(2회 이상 유찰 시 수의계약)"],["공급가격","감정가격 + 시행자가 설치한 기반시설 등 공사비를 기준으로 협의"],["매각 제한","원형지개발자(국가·지방자치단체 제외)는 공사완료 공고일부터 5년, 계약일부터 10년 중 먼저 끝나는 기간 동안 매각 불가"],["계약 해제","착수 지연, 사업 지연, 동의 없는 매각 등. 2회 이상 시정요구 후(영 제55조의2⑤)"]]},{"종류":"흐름","제목":"원형지 공급 절차","단계":[{"이름":"승인 신청","설명":"시행자가 원형지 공급 승인신청서와 개발계획 등 서류 제출(영 제55조의2①)"},{"이름":"개발계획 수립·승인","설명":"지정권자가 개발계획을 수립한 뒤 원형지 공급 승인(영 제55조의2②)"},{"이름":"공급계약 체결","설명":"승인내용과 공급 계획에 따라 원형지개발자와 계약(법 제25조의2④)"},{"이름":"세부계획 제출","설명":"원형지개발자가 세부계획 제출. 시행자가 실시계획에 반영(법 제25조의2④)"},{"이름":"감독·해제","설명":"이행조건 불이행 시 승인 취소·시정 요구, 시행자는 계약 해제(법 제25조의2⑦⑧)"}]}],"함정":"경쟁입찰은 학교·공장 부지로 직접 사용하는 원형지개발자에게만 적용되고 나머지는 수의계약이다. 매각 제한은 국가와 지방자치단체를 뺀 원형지개발자에게 적용되며, 계약 해제 전에는 시정요구가 2회 이상 필요하다."},"34회-2차-083":{"한줄":"공장시설물 부지와 같은 구역 안의 의료시설 등 부속시설물 부지는 공장용지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제9호","원문":"공장용지: 가. 제조업을 하고 있는 공장시설물의 부지 / 나. 「산업집적활성화 및 공장설립에 관한 법률」 등 관계 법령에 따른 공장부지 조성공사가 준공된 토지 / 다. 가목 및 나목의 토지와 같은 구역에 있는 의료시설 등 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제6호","원문":"광천지: 지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제17호","원문":"하천: 자연의 유수(流水)가 있거나 있을 것으로 예상되는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제25호","원문":"종교용지: 일반 공중의 종교의식을 위하여 예배ㆍ법요ㆍ설교ㆍ제사 등을 하기 위한 교회ㆍ사찰ㆍ향교 등 건축물의 부지와 이에 접속된 부속시설물의 부지"}],"선지":[{"번호":1,"판정":"틀림","설명":"송수관·송유관·저장시설 부지는 광천지에서 빠진다. 광천지는 용출구와 그 유지에 쓰는 부지만이다(영 제58조제6호 단서)."},{"번호":2,"판정":"틀림","설명":"교회·사찰·향교 건축물 부지는 종교용지다(영 제58조제25호). 사적지는 국가유산으로 지정된 유적·고적·기념물 보존 구획 토지다."},{"번호":3,"판정":"틀림","설명":"자연의 유수가 있거나 있을 것으로 예상되는 토지는 하천이다(영 제58조제17호). 구거는 인공 수로·둑과 그 부속시설물 부지, 소규모 수로부지다."},{"번호":4,"판정":"옳음","설명":"공장용지에는 공장시설물 부지와 같은 구역의 의료시설 등 부속시설물 부지가 들어간다(영 제58조제9호다목)."},{"번호":5,"판정":"틀림","설명":"국토계획법에 따라 공원·녹지로 결정·고시된 토지는 공원이다(영 제58조제22호). 체육용지는 종합운동장·실내체육관·야구장·골프장 같은 체육시설의 토지다."}],"개념":[{"종류":"표","제목":"물과 관련된 지목","머리":["지목","정의","구별 포인트"],"행":[["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","자연 상태의 흐름"],["구거","용수ㆍ배수를 위한 인공 수로ㆍ둑ㆍ부속시설물 부지, 자연 유수가 있는 소규모 수로부지","인공 수로 중심"],["유지","물이 고이거나 상시 저장하는 댐ㆍ저수지ㆍ소류지ㆍ호수ㆍ연못, 연ㆍ왕골 자생 배수불량 토지","저장하는 물"],["제방","조수ㆍ자연유수ㆍ모래ㆍ바람을 막는 방조제ㆍ방수제ㆍ방사제ㆍ방파제 부지","막는 시설"],["양어장","육상에 인공으로 조성된 수산생물 번식ㆍ양식 시설 부지와 접속 부속시설물","육상 인공 시설"],["수도용지","취수ㆍ저수ㆍ도수ㆍ정수ㆍ송수ㆍ배수 시설 부지와 접속 부속시설물","물 공급 시설"],["광천지","온수ㆍ약수ㆍ석유류 용출구와 그 유지에 쓰는 부지","송수관ㆍ송유관ㆍ저장시설 부지 제외"]]},{"종류":"표","제목":"공원ㆍ체육용지ㆍ유원지","머리":["지목","해당","제외"],"행":[["공원","보건ㆍ휴양ㆍ정서생활 시설을 갖추고 국토계획법에 따라 공원 또는 녹지로 결정ㆍ고시된 토지","-"],["체육용지","종합운동장ㆍ실내체육관ㆍ야구장ㆍ골프장ㆍ스키장ㆍ승마장ㆍ경륜장 등 체육시설 토지와 접속 부속시설물","영속성ㆍ독립성이 약한 정구장ㆍ골프연습장ㆍ실내수영장ㆍ체육도장, 유수를 이용한 요트장ㆍ카누장"],["유원지","수영장ㆍ유선장ㆍ낚시터ㆍ어린이놀이터ㆍ동물원ㆍ식물원ㆍ민속촌ㆍ경마장ㆍ야영장 등 위락ㆍ휴양 시설 토지와 접속 부속시설물","독립적 숙식시설ㆍ유기장 부지, 하천ㆍ구거ㆍ공유 유지로 분류되는 것"]]}],"함정":"3번은 하천의 정의를 구거에 붙인 문장이고, 5번은 공원의 정의를 체육용지에 붙인 문장이다. 정의 문구는 맞고 지목 이름만 바뀌어 있어 정의 쪽을 먼저 읽으면 걸러진다."},"34회-2차-092":{"한줄":"지상경계점등록부의 등록사항에 지적도면의 번호는 없다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제65조제2항","원문":"지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제60조제2항","원문":"법 제65조제2항제5호에서 “그 밖에 국토교통부령으로 정하는 사항”이란 다음 각 호의 사항을 말한다. 1. 공부상 지목과 실제 토지이용 지목 2. 경계점의 사진 파일 3. 경계점표지의 종류 및 경계점 위치"}],"선지":[{"번호":1,"판정":"틀림","설명":"법 제65조제2항 각 호와 규칙 제60조제2항 어디에도 지적도면의 번호는 없다."},{"번호":2,"판정":"옳음","설명":"토지의 소재는 법 제65조제2항제1호의 등록사항이다."},{"번호":3,"판정":"옳음","설명":"공부상 지목과 실제 토지이용 지목은 규칙 제60조제2항제1호의 등록사항이다."},{"번호":4,"판정":"옳음","설명":"경계점의 사진 파일은 규칙 제60조제2항제2호의 등록사항이다."},{"번호":5,"판정":"옳음","설명":"경계점표지의 종류 및 경계점 위치는 규칙 제60조제2항제3호의 등록사항이다."}],"개념":[{"종류":"표","제목":"지상경계점등록부 등록사항","머리":["구분","등록사항","근거"],"행":[["법에서 직접","토지의 소재","법 제65조제2항제1호"],["법에서 직접","지번","법 제65조제2항제2호"],["법에서 직접","경계점 좌표(경계점좌표등록부 시행지역에 한정)","법 제65조제2항제3호"],["법에서 직접","경계점 위치 설명도","법 제65조제2항제4호"],["규칙에서","공부상 지목과 실제 토지이용 지목","규칙 제60조제2항제1호"],["규칙에서","경계점의 사진 파일","규칙 제60조제2항제2호"],["규칙에서","경계점표지의 종류 및 경계점 위치","규칙 제60조제2항제3호"]]},{"종류":"표","제목":"지상경계의 결정기준","머리":["상황","경계 위치"],"행":[["연접 토지 간 높낮이 차이가 없는 경우","구조물 등의 중앙"],["연접 토지 간 높낮이 차이가 있는 경우","구조물 등의 하단부"],["도로ㆍ구거 등에 절토(땅깎기)된 부분이 있는 경우","경사면의 상단부"],["토지가 해면 또는 수면에 접하는 경우","최대만조위 또는 최대만수위가 되는 선"],["공유수면매립지에서 제방 등을 토지에 편입하여 등록하는 경우","바깥쪽 어깨부분"]]}],"함정":"5번의 「경계점 위치」는 법에 있는 「경계점 위치 설명도」와 이름이 비슷하다. 규칙 제60조제2항제3호는 경계점표지의 종류와 경계점 위치를 함께 정한 항목이라 등록사항이 맞다. 경계점 좌표는 경계점좌표등록부 시행지역에서만 등록한다."},"34회-2차-081":{"한줄":"지적측량수행자는 의뢰를 받은 때 측량기간ㆍ측량일자ㆍ수수료 등을 적은 수행계획서를 그 다음 날까지 지적소관청에 낸다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제25조제1항","원문":"법 제24조제1항에 따라 지적측량을 의뢰하려는 자는 별지 제15호서식의 지적측량 의뢰서(전자문서로 된 의뢰서를 포함한다)에 의뢰 사유를 증명하는 서류(전자문서를 포함한다)를 첨부하여 지적측량수행자에게 제출하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제25조제2항","원문":"지적측량수행자는 제1항에 따른 지적측량 의뢰를 받은 때에는 측량기간, 측량일자 및 측량 수수료 등을 적은 별지 제16호서식의 지적측량 수행계획서를 그 다음 날까지 지적소관청에 제출하여야 한다. 제출한 지적측량 수행계획서를 변경한 경우에도 같다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수행계획서가 규칙 제25조제2항에 따라 다음 날까지 지적소관청에 내는 서류이고, 계획을 변경한 때도 같다."},{"번호":2,"판정":"틀림","설명":"의뢰서는 의뢰인이 지적측량수행자에게 내는 서류다(규칙 제25조제1항)."},{"번호":3,"판정":"틀림","설명":"토지이동현황 조사계획은 지적소관청이 직권으로 토지이동을 조사ㆍ측량하려 할 때 스스로 세우는 계획이다(규칙 제59조제1항)."},{"번호":4,"판정":"틀림","설명":"토지이동정리 결의서는 지적소관청이 지적공부를 정리하면서 작성한다(영 제84조제2항)."},{"번호":5,"판정":"틀림","설명":"규칙 제25조제2항이 다음 날까지 내도록 정한 서류는 수행계획서뿐이다. 측량성과는 별도로 시ㆍ도지사, 대도시 시장 또는 지적소관청의 검사를 받는다(법 제25조제1항)."}],"개념":[{"종류":"표","제목":"지적측량 기간 (규칙 제25조제3항ㆍ제4항)","머리":["구분","기간"],"행":[["측량기간","5일"],["측량검사기간","4일"],["지적기준점을 설치하는 경우 (15점 이하)","측량ㆍ검사기간 각 4일"],["지적기준점을 설치하는 경우 (15점 초과)","4일에 15점을 초과하는 4점마다 1일 가산"],["의뢰인과 수행자가 합의한 기간","합의 기간 적용, 전체의 4분의 3은 측량기간, 4분의 1은 검사기간으로 봄"]]},{"종류":"흐름","제목":"지적측량 의뢰에서 적부심사까지","단계":[{"이름":"의뢰","설명":"의뢰서에 사유 증명서류를 붙여 지적측량수행자(지적측량업 등록자 또는 한국국토정보공사)에 제출 (법 제24조제1항, 규칙 제25조제1항)."},{"이름":"수행계획서 제출","설명":"의뢰받은 다음 날까지 지적소관청에 제출, 변경해도 같음 (규칙 제25조제2항)."},{"이름":"측량ㆍ성과 결정","설명":"측량기간 5일 (규칙 제25조제3항)."},{"이름":"성과검사","설명":"시ㆍ도지사, 대도시 시장 또는 지적소관청의 검사. 지적공부를 정리하지 않는 측량은 예외 (법 제25조제1항). 검사기간 4일."},{"이름":"적부심사","설명":"다툼이 있으면 시ㆍ도지사를 거쳐 지방지적위원회에 청구. 시ㆍ도지사 30일 내 조사 회부 → 위원회 60일 내 의결(30일 한 번 연장) → 시ㆍ도지사 7일 내 통지 → 불복 시 90일 내 중앙지적위원회 재심사 (법 제29조)."}]}],"함정":"서류 이름만 보면 2번 의뢰서를 고르기 쉽다. 의뢰서는 수행자에게 내는 서류이고, 지적소관청에 다음 날까지 내는 서류는 수행계획서다. 서류별 제출처를 따로 외워 둔다."},"34회-2차-100":{"한줄":"이의신청서는 관할 지방법원이 아니라 결정ㆍ처분을 한 등기관이 속한 등기소에 제출한다.","근거":[{"법령":"부동산등기법","조문":"제100조","원문":"등기관의 결정 또는 처분에 이의가 있는 자는 그 결정 또는 처분을 한 등기관이 속한 지방법원(이하 이 장에서 “관할 지방법원”이라 한다)에 이의신청을 할 수 있다."},{"법령":"부동산등기법","조문":"제101조","원문":"제100조에 따른 이의신청(이하 이 장에서 “이의신청”이라 한다)은 대법원규칙으로 정하는 바에 따라 결정 또는 처분을 한 등기관이 속한 등기소에 이의신청서를 제출하거나 전산정보처리조직을 이용하여 이의신청정보를 보내는 방법으로 한다."},{"법령":"부동산등기법","조문":"제102조","원문":"새로운 사실이나 새로운 증거방법을 근거로 이의신청을 할 수는 없다."},{"법령":"부동산등기법","조문":"제103조제2항","원문":"등기관은 이의가 이유 없다고 인정하면 이의신청일부터 3일 이내에 의견을 붙여 이의신청서 또는 이의신청정보를 관할 지방법원에 보내야 한다."},{"법령":"부동산등기법","조문":"제104조","원문":"이의에는 집행정지(執行停止)의 효력이 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"각하결정은 신청인에게만 불이익을 주므로 신청인이 아닌 제3자에게는 이의의 이익이 없다. 법 제100조의 「이의가 있는 자」는 이 범위로 읽는다."},{"번호":2,"판정":"틀림","설명":"관할 지방법원은 이의에 대해 결정하는 법원이고, 이의신청서는 등기관이 속한 등기소에 낸다(법 제101조). 등기소가 이의신청서를 관할 지방법원에 보낸다(법 제103조제2항)."},{"번호":3,"판정":"옳음","설명":"법 제100조~제108조에 이의신청 기간 제한 규정이 없다."},{"번호":4,"판정":"옳음","설명":"새로운 사실이나 새로운 증거방법을 근거로 한 이의는 허용되지 않는다(법 제102조)."},{"번호":5,"판정":"옳음","설명":"이의에는 집행정지 효력이 없어(법 제104조) 다른 등기신청은 계속 처리된다."}],"개념":[{"종류":"흐름","제목":"등기관의 처분에 대한 이의 절차","단계":[{"이름":"이의신청","설명":"결정ㆍ처분을 한 등기관이 속한 등기소에 이의신청서 제출 또는 이의신청정보 전송 (법 제101조). 기간 제한 없음, 새로운 사실ㆍ증거방법 불가 (법 제102조)."},{"이름":"등기관의 판단","설명":"이유 있으면 그에 해당하는 처분 (법 제103조제1항)."},{"이름":"관할 지방법원 송부","설명":"이유 없으면 이의신청일부터 3일 이내 의견을 붙여 송부. 등기를 마친 후의 이의는 이해관계인에게 이의 사실도 통지 (법 제103조제2항ㆍ제3항)."},{"이름":"지방법원의 조치","설명":"결정 전에 가등기 또는 이의가 있다는 뜻의 부기등기를 명령할 수 있음 (법 제106조)."},{"이름":"결정","설명":"이유를 붙여 결정. 이유 있으면 등기관에게 처분 명령 (법 제105조제1항)."},{"이름":"항고","설명":"비송사건절차법에 따라 항고 (법 제105조제2항)."}]},{"종류":"표","제목":"이의신청 규정 요약","머리":["항목","내용","근거"],"행":[["관할","처분한 등기관이 속한 지방법원","법 제100조"],["제출처","처분한 등기관이 속한 등기소","법 제101조"],["새로운 사실","근거로 삼을 수 없음","법 제102조"],["집행정지","효력 없음","법 제104조"],["법원 명령에 따른 등기","명령한 법원, 명령 연월일, 명령에 따라 등기한다는 뜻 기록","법 제107조"]]}],"함정":"2번은 이의 「관할」과 이의신청서 「제출처」를 섞은 선지다. 이의에 대한 판단은 관할 지방법원이 하지만 서류는 등기소에 낸다. 5번은 이의신청 중에도 같은 부동산의 다른 등기신청이 접수ㆍ처리된다는 뜻이며 집행 부정지에서 나온다.","개정":"법 제100조ㆍ제103조는 <개정 2024.9.20> 표시가 있다. 현행 제101조는 이의신청서를 등기소에 제출하거나 전산정보처리조직으로 이의신청정보를 보내는 두 방식이다. 정답은 달라지지 않는다."},"34회-2차-108":{"한줄":"재건축조합이 조합원에게 귀속되지 않는 토지를 취득하는 때는 소유권이전 고시일의 다음 날이고, 준공인가 고시일은 기준이 아니다.","근거":[{"법령":"지방세기본법","조문":"제34조제1항제1호","원문":"① 지방세를 납부할 의무는 다음 각 호의 구분에 따른 시기에 성립한다.\n  1. 취득세: 과세물건을 취득하는 때"},{"법령":"지방세법 시행령","조문":"제20조제1항·제2항","원문":"① 무상취득의 경우에는 그 계약일(상속 또는 유증으로 인한 취득의 경우에는 상속 또는 유증 개시일을 말한다)에 취득한 것으로 본다. 다만, 해당 취득물건을 등기ㆍ등록하지 않고 다음 각 호의 어느 하나에 해당하는 서류로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.\n  2. 공정증서(공증인이 인증한 사서증서를 포함하되, 취득일부터 취득일이 속하는 달의 말일부터 3개월 이내에 공증받은 것만 해당한다)\n② 유상승계취득의 경우에는 사실상의 잔금지급일(신고인이 제출한 자료로 사실상의 잔금지급일을 확인할 수 없는 경우에는 계약상의 잔금지급일을 말하고, 계약상 잔금 지급일이 명시되지 않은 경우에는 계약일부터 60일이 경과한 날을 말한다)에 취득한 것으로 본다. 다만, 해당 취득물건을 등기ㆍ등록하지 않고 다음 각 호의 어느 하나에 해당하는 서류로 계약이 해제된 사실이 입증되는 경우에는 취득한 것으로 보지 않는다.\n  1. 화해조서ㆍ인낙조서(해당 조서에서 취득일부터 60일 이내에 계약이 해제된 사실이 입증되는 경우만 해당한다)\n  2. 공정증서(공증인이 인증한 사서증서를 포함하되, 취득일부터 60일 이내에 공증받은 것만 해당한다)\n  3. 행정안전부령으로 정하는 계약해제신고서(취득일부터 60일 이내에 제출된 것만 해당한다)\n  4. 부동산 거래신고 관련 법령에 따른 부동산거래계약 해제등 신고서(취득일부터 60일 이내에 등록관청에 제출한 경우만 해당한다)"},{"법령":"지방세법 시행령","조문":"제20조제7항","원문":"⑦ 「주택법」 제11조에 따른 주택조합이 주택건설사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「주택법」 제49조에 따른 사용검사를 받은 날에 그 토지를 취득한 것으로 보고, 「도시 및 주거환경정비법」 제35조제3항에 따른 재건축조합이 재건축사업을 하거나 「빈집 및 소규모주택 정비에 관한 특례법」 제23조제2항에 따른 소규모재건축조합이 소규모재건축사업을 하면서 조합원으로부터 취득하는 토지 중 조합원에게 귀속되지 아니하는 토지를 취득하는 경우에는 「도시 및 주거환경정비법」 제86조제2항 또는 「빈집 및 소규모주택 정비에 관한 특례법」 제40조제2항에 따른 소유권이전 고시일의 다음 날에 그 토지를 취득한 것으로 본다."},{"법령":"지방세법 시행령","조문":"제20조제13항·제14항","원문":"⑬ 「민법」 제839조의2 및 제843조에 따른 재산분할로 인한 취득의 경우에는 취득물건의 등기일 또는 등록일을 취득일로 본다.\n⑭ 제1항, 제2항 및 제5항에 따른 취득일 전에 등기 또는 등록을 한 경우에는 그 등기일 또는 등록일에 취득한 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"상속·유증은 개시일에 취득한 것으로 본다(지방세법 시행령 제20조제1항). 취득세는 과세물건을 취득하는 때 납세의무가 성립한다(지방세기본법 제34조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"증여는 계약일 취득이 원칙이다. 등기·등록하지 않고 취득일이 속하는 달의 말일부터 3개월 이내에 공증받은 공정증서로 해제가 입증되면 취득하지 않은 것으로 본다. 60일 이내 공증이면 이 기한 안이다(시행령 제20조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"유상승계는 사실상 잔금지급일이 취득일이고, 그 전에 등기·등록하면 등기일·등록일이 취득일이다(시행령 제20조제2항·제14항)."},{"번호":4,"판정":"옳음","설명":"이혼 재산분할로 인한 취득은 취득물건의 등기일 또는 등록일이 취득일이다(시행령 제20조제13항)."},{"번호":5,"판정":"틀림","설명":"재건축조합이 비조합원용 토지를 취득하는 때는 소유권이전 고시일의 다음 날이다. 주택법상 주택조합이 취득하는 비조합원용 토지는 사용검사를 받은 날이다(시행령 제20조제7항)."}],"개념":[{"종류":"표","제목":"취득세 취득일(지방세법 시행령 제20조)","머리":["취득 유형","취득일"],"행":[["무상취득(증여 등)","계약일. 상속·유증은 개시일"],["유상승계취득","사실상 잔금지급일(확인 불가 시 계약상 잔금지급일, 명시가 없으면 계약일부터 60일이 지난 날)"],["연부취득","사실상의 연부금 지급일"],["건축·개수","사용승인서 교부일(임시사용승인 시 그날)과 사실상 사용일 중 빠른 날"],["주택조합의 비조합원용 토지","주택법에 따른 사용검사를 받은 날"],["재건축조합의 비조합원용 토지","소유권이전 고시일의 다음 날"],["매립·간척 원시취득","공사준공인가일. 그 전 사용승낙·허가·사실상 사용이 있으면 가장 빠른 날"],["지목변경","사실상 변경일과 공부상 변경일 중 빠른 날"],["점유취득·재산분할","취득물건의 등기일 또는 등록일"],["취득일 전 등기·등록(무상·유상·연부)","그 등기일 또는 등록일"]]},{"종류":"표","제목":"취득세 신고·납부 기한(지방세법 제20조제1항)","머리":["취득 원인","신고·납부 기한"],"행":[["일반(유상취득 등)","취득일부터 60일 이내"],["무상취득(상속 제외)·부담부증여","취득일이 속하는 달의 말일부터 3개월 이내"],["상속","상속개시일이 속하는 달의 말일부터 6개월 이내(외국에 주소를 둔 상속인이 있으면 9개월)"],["실종","실종선고일이 속하는 달의 말일부터 6개월 이내(외국에 주소를 둔 상속인이 있으면 9개월)"]]}],"함정":"⑤에서 '준공인가 고시일'을 '소유권이전 고시일'로 바꿔 놓았다. 주택조합은 사용검사일, 재건축조합은 소유권이전 고시일의 다음 날로 갈린다.","개정":"선지 ③에 '(그 전에 등기한 경우에는 등기일)'을 더했다. 시행령 제20조제14항에 따라 잔금지급일 전에 등기하면 등기일이 취득일이어서, 괄호가 없으면 ③도 틀린 선지가 되어 정답이 둘이 되기 때문이다. 증여 등 무상취득의 해제 입증 기한은 시행령 제20조제1항 각 호에 '취득일이 속하는 달의 말일부터 3개월'로 되어 있다(<개정 2023.12.29> 표시)."},"34회-2차-112":{"한줄":"주택 재산세 세액이 20만원 이하이면 조례로 7월 16일부터 7월 31일까지 한꺼번에 걷을 수 있고, 9월에 한꺼번에 걷는 규정은 없다.","근거":[{"법령":"지방세법","조문":"제115조제1항제3호","원문":"① 재산세의 납기는 다음 각 호와 같다.\n  3. 주택: 해당 연도에 부과ㆍ징수할 세액의 2분의 1은 매년 7월 16일부터 7월 31일까지, 나머지 2분의 1은 9월 16일부터 9월 30일까지. 다만, 해당 연도에 부과할 세액이 20만원 이하인 경우에는 조례로 정하는 바에 따라 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 부과ㆍ징수할 수 있다."},{"법령":"지방세법","조문":"제116조제1항·제2항","원문":"① 재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다.\n② 재산세를 징수하려면 토지, 건축물, 주택, 선박 및 항공기로 구분한 납세고지서에 과세표준과 세액을 적어 늦어도 납기개시 5일 전까지 발급하여야 한다."},{"법령":"지방세법","조문":"제114조","원문":"재산세의 과세기준일은 매년 6월 1일로 한다."},{"법령":"지방세법","조문":"제119조","원문":"고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"20만원 이하 주택분은 조례로 납기를 7월 16일부터 7월 31일까지로 하여 한꺼번에 걷는다(지방세법 제115조제1항제3호 단서). 9월 일괄 납기는 없다."},{"번호":2,"판정":"옳음","설명":"재산세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수로 부과·징수한다(제116조제1항)."},{"번호":3,"판정":"옳음","설명":"토지·건축물·주택·선박·항공기로 구분한 납세고지서를 늦어도 납기개시 5일 전까지 발급한다(제116조제2항)."},{"번호":4,"판정":"옳음","설명":"과세기준일은 매년 6월 1일이다(제114조)."},{"번호":5,"판정":"옳음","설명":"고지서 1장당 재산세 징수세액이 2천원 미만이면 징수하지 않는다(제119조)."}],"개념":[{"종류":"표","제목":"재산세 납기(지방세법 제115조제1항)","머리":["과세대상","납기"],"행":[["토지","9월 16일 ~ 9월 30일"],["건축물","7월 16일 ~ 7월 31일"],["주택","세액의 2분의 1은 7월 16일 ~ 7월 31일, 나머지 2분의 1은 9월 16일 ~ 9월 30일"],["주택(부과할 세액 20만원 이하)","조례로 7월 16일 ~ 7월 31일에 한꺼번에 부과·징수 가능"],["선박","7월 16일 ~ 7월 31일"],["항공기","7월 16일 ~ 7월 31일"]]},{"종류":"흐름","제목":"재산세 부과·징수 절차","단계":[{"이름":"과세기준일","설명":"매년 6월 1일 현재 사실상 소유자가 납세의무자(제114조, 제107조)"},{"이름":"세액 산정·고지서 발급","설명":"지방자치단체의 장이 세액을 산정해 보통징수. 토지·건축물·주택·선박·항공기로 구분한 납세고지서를 납기개시 5일 전까지 발급(제116조)"},{"이름":"납기 내 납부","설명":"토지 9월, 건축물·선박·항공기 7월, 주택은 7월·9월 반씩(제115조)"},{"이름":"물납·분할납부","설명":"납부세액 1천만원 초과 시 관할구역 안 부동산 물납 허가(제117조). 250만원 초과 시 납부기한이 지난 날부터 3개월 이내 분할납부(제118조)"},{"이름":"수시부과","설명":"과세대상 누락·위법·착오가 있으면 수시로 부과·징수(제115조제2항)"},{"이름":"소액 징수면제","설명":"고지서 1장당 징수할 세액이 2천원 미만이면 징수하지 않음(제119조)"}]}],"함정":"20만원 이하 일괄 납기를 9월로 적은 ①이 오답이다. 7월 16일부터 7월 31일이다. 토지에는 이 일괄 납기 특례가 없다."},"34회-2차-116":{"한줄":"완성되지 않은 자산은 대금을 청산한 날까지 완성되지 않았더라도 그 목적물이 완성 또는 확정된 날이 양도·취득시기다.","근거":[{"법령":"소득세법","조문":"제98조","원문":"자산의 양도차익을 계산할 때 그 취득시기 및 양도시기는 대금을 청산한 날이 분명하지 아니한 경우 등 대통령령으로 정하는 경우를 제외하고는 해당 자산의 대금을 청산한 날로 한다. 이 경우 자산의 대금에는 해당 자산의 양도에 대한 양도소득세 및 양도소득세의 부가세액을 양수자가 부담하기로 약정한 경우에는 해당 양도소득세 및 양도소득세의 부가세액은 제외한다."},{"법령":"소득세법 시행령","조문":"제162조제1항제1호·제2호·제4호·제5호·제8호","원문":"①법 제98조 전단에서 \"대금을 청산한 날이 분명하지 아니한 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 경우를 말한다.\n  1. 대금을 청산한 날이 분명하지 아니한 경우에는 등기부ㆍ등록부 또는 명부 등에 기재된 등기ㆍ등록접수일 또는 명의개서일\n  2. 대금을 청산하기 전에 소유권이전등기(등록 및 명의의 개서를 포함한다)를 한 경우에는 등기부ㆍ등록부 또는 명부등에 기재된 등기접수일\n  4. 자기가 건설한 건축물에 있어서는 「건축법」 제22조제2항에 따른 사용승인서 교부일. 다만, 사용승인서 교부일 전에 사실상 사용하거나 같은 조 제3항제2호에 따른 임시사용승인을 받은 경우에는 그 사실상의 사용일 또는 임시사용승인을 받은 날 중 빠른 날로 하고 건축허가를 받지 아니하고 건축하는 건축물에 있어서는 그 사실상의 사용일로 한다.\n  5. 상속 또는 증여에 의하여 취득한 자산에 대하여는 그 상속이 개시된 날 또는 증여를 받은 날\n  8. 완성 또는 확정되지 아니한 자산을 양도 또는 취득한 경우로서 해당 자산의 대금을 청산한 날까지 그 목적물이 완성 또는 확정되지 아니한 경우에는 그 목적물이 완성 또는 확정된 날. 이 경우 건설 중인 건물의 완성된 날에 관하여는 제4호를 준용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대금 청산일이 분명하지 않으면 등기·등록접수일 또는 명의개서일이다(소득세법 시행령 제162조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"상속으로 취득한 자산은 상속이 개시된 날이다(제5호)."},{"번호":3,"판정":"옳음","설명":"대금을 청산하기 전에 소유권이전등기를 하면 등기접수일이다(제2호)."},{"번호":4,"판정":"옳음","설명":"건축허가 없이 건축한 건축물은 사실상의 사용일이다(제4호 단서). 추후 받은 사용승인일이 아니다."},{"번호":5,"판정":"틀림","설명":"대금을 청산한 날까지 완성 또는 확정되지 않은 자산은 그 목적물이 완성 또는 확정된 날이다(제8호)."}],"개념":[{"종류":"비교","제목":"자기가 건설한 건축물의 취득시기(시행령 제162조제1항제4호)","왼쪽":{"이름":"허가·사용승인을 받은 건축물","항목":["건축법 제22조제2항에 따른 사용승인서 교부일","사용승인서 교부일 전에 사실상 사용하거나 임시사용승인을 받으면 사실상 사용일과 임시사용승인일 중 빠른 날"]},"오른쪽":{"이름":"건축허가 없이 건축한 건축물","항목":["그 사실상의 사용일","추후 사용승인이나 임시사용승인을 받아도 그 받은 날이 아님"]}},{"종류":"표","제목":"대금 청산을 기준으로 한 양도·취득시기","머리":["경우","시기","근거"],"행":[["원칙","대금을 청산한 날(양도소득세·부가세를 양수자가 부담하기로 약정한 금액은 대금에서 제외)","소득세법 제98조"],["청산일이 분명하지 않음","등기·등록접수일 또는 명의개서일","시행령 제162조제1항제1호"],["청산 전에 이전등기","등기접수일","같은 항 제2호"],["장기할부조건","등기접수일·인도일·사용수익일 중 빠른 날","같은 항 제3호"],["미완성·미확정 자산","목적물이 완성 또는 확정된 날(건설 중인 건물의 완성일은 제4호 준용)","같은 항 제8호"]]}],"함정":"⑤는 원칙인 대금 청산일을 그대로 적용했다. 목적물이 완성·확정되지 않은 자산은 완성·확정된 날이 시기다. ④의 사실상 사용일을 사용승인일로 바꿔 쓰면 틀리다."},"34회-1차-024":{"한줄":"시중금리가 오르면 무위험률이 올라 요구수익률도 상승한다.","근거":[{"이론":"요구수익률의 구성","내용":"요구수익률=무위험률+위험할증률+예상인플레이션율. 시중금리(무위험률) 상승, 위험 증가, 인플레이션 예상 상승은 모두 요구수익률을 높인다. 기대수익률이 요구수익률보다 크면 투자가 채택된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시중금리 상승은 무위험률을 높여 요구수익률을 상승시킨다."},{"번호":2,"판정":"옳음","설명":"기대수익률은 예상수입과 예상지출로 계산하는 사전(事前) 수익률이다."},{"번호":3,"판정":"옳음","설명":"자기자본수익률이 총자본수익률보다 높으면 정(+)의 레버리지효과다."},{"번호":4,"판정":"옳음","설명":"요구수익률은 위험을 고려해 투자자가 최소한 얻어야 하는 수익률이다."},{"번호":5,"판정":"옳음","설명":"담보대출과 전세보증금은 타인자본이므로 레버리지로 활용할 수 있다."}],"개념":[{"종류":"표","제목":"투자 수익률의 종류","머리":["수익률","의미","시점"],"행":[["기대수익률","예상수입과 예상지출로 계산한 예상 수익률","사전"],["요구수익률","위험을 고려해 투자자가 최소한 요구하는 수익률(무위험률+위험할증률+예상인플레이션율)","사전"],["실현수익률","투자 후 실제로 달성한 수익률","사후"],["투자 결정","기대수익률 > 요구수익률이면 채택","-"]]},{"종류":"계산","제목":"레버리지효과 판정","단계":[{"설명":"총투자액 10억원, 대출 4억원(금리 4퍼센트), 총자본수익률 6퍼센트일 때 순영업소득","식":"10억원×6%","값":"0.6억원"},{"설명":"대출이자","식":"4억원×4%","값":"0.16억원"},{"설명":"자기자본 투자액과 세전현금수지","식":"(10-4)억원, 0.6-0.16","값":"6억원, 0.44억원"},{"설명":"자기자본수익률","식":"0.44÷6","값":"약 7.33%"},{"설명":"판정: 자기자본수익률 7.33% > 총자본수익률 6%","식":"대출금리 4% < 총자본수익률 6%","값":"정(+)의 레버리지"}]}],"함정":"시중금리와 요구수익률은 같은 방향으로 움직인다. 금리가 오르면 요구수익률도 오른다. 정(+)·부(-)의 레버리지는 대출금리와 총자본수익률의 크기 비교로 정해진다."},"34회-1차-049":{"한줄":"조건이 사회질서에 위반하면 조건만이 아니라 법률행위 전부가 무효이다(제151조제1항).","근거":[{"법령":"민법","조문":"제151조","원문":"①조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다. ②조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 하고 해제조건이면 그 법률행위는 무효로 한다. ③조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 해제조건이면 조건없는 법률행위로 하고 정지조건이면 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제153조","원문":"①기한은 채무자의 이익을 위한 것으로 추정한다."},{"법령":"민법","조문":"제152조","원문":"②종기있는 법률행위는 기한이 도래한 때로부터 그 효력을 잃는다."},{"판례":"대법원 판례(조건의 증명책임)","요지":"법률행위에 조건이 붙어 있다는 사실은 이를 주장하는 자가 증명해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"불법조건이 붙은 법률행위는 조건만이 아니라 법률행위 전부가 무효이다(제151조제1항)."},{"번호":2,"판정":"옳음","설명":"조건이 붙어 있다는 사실은 이를 주장하는 자가 증명해야 한다."},{"번호":3,"판정":"옳음","설명":"기한은 채무자의 이익을 위한 것으로 추정한다(제153조제1항)."},{"번호":4,"판정":"옳음","설명":"이미 성취한 조건이 해제조건이면 법률행위는 무효이다(제151조제2항)."},{"번호":5,"판정":"옳음","설명":"종기 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다(제152조제2항)."}],"개념":[{"종류":"표","제목":"조건과 기한 비교","머리":["구분","조건","기한"],"행":[["내용","장래의 불확실한 사실","장래의 확실한 사실"],["효력 발생·소멸","정지조건은 성취한 때 발생, 해제조건은 성취한 때 소멸(제147조)","시기는 도래한 때 발생, 종기는 도래한 때 소멸(제152조)"],["소급효","당사자가 특약으로 소급하게 할 수 있음(제147조제3항)","소급효를 인정하지 않음"],["이익","조건의 성부 미정 중에도 조건부 권리는 처분·상속·보존·담보 가능(제149조)","기한은 채무자의 이익으로 추정(제153조제1항), 이익은 포기 가능하나 상대방 이익을 해하지 못함"],["불법의 경우","불법조건이면 법률행위 전부 무효(제151조제1항)","해당 없음"]]},{"종류":"표","제목":"기성조건·불능조건의 효과(제151조)","머리":["조건의 종류","정지조건","해제조건"],"행":[["이미 성취한 조건(기성)","조건 없는 법률행위","무효"],["성취할 수 없는 조건(불능)","무효","조건 없는 법률행위"],["불법조건","법률행위 전부 무효","법률행위 전부 무효"],["조건 성취를 신의칙에 반해 방해(제150조제1항)","상대방은 조건이 성취된 것으로 주장 가능","같음"]]}],"함정":"선지 1이 틀린 이유는 조건만 떼어 무효로 보는 점이다. 불법조건은 법률행위 전부를 무효로 만든다. 선지 4의 기성 해제조건은 무효이고, 선지 3의 기한 이익은 채무자에게 추정된다."},"34회-1차-051":{"한줄":"악의의 점유자는 과실을 취득하지 못하므로 통상의 필요비도 청구할 수 있다.","근거":[{"법령":"민법","조문":"제201조","원문":"①선의의 점유자는 점유물의 과실을 취득한다. ②악의의 점유자는 수취한 과실을 반환하여야 하며 소비하였거나 과실로 인하여 훼손 또는 수취하지 못한 경우에는 그 과실의 대가를 보상하여야 한다. ③전항의 규정은 폭력 또는 은비에 의한 점유자에 준용한다."},{"법령":"민법","조문":"제202조","원문":"점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"법령":"민법","조문":"제203조","원문":"①점유자가 점유물을 반환할 때에는 회복자에 대하여 점유물을 보존하기 위하여 지출한 금액 기타 필요비의 상환을 청구할 수 있다. 그러나 점유자가 과실을 취득한 경우에는 통상의 필요비는 청구하지 못한다. ②점유자가 점유물을 개량하기 위하여 지출한 금액 기타 유익비에 관하여는 그 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 그 지출금액이나 증가액의 상환을 청구할 수 있다. ③전항의 경우에 법원은 회복자의 청구에 의하여 상당한 상환기간을 허여할 수 있다."},{"판례":"대법원 판례(계약해제와 과실)","요지":"매매계약이 해제되면 매수인은 원상회복 의무를 진다. 선의의 매수인이라도 해제 후 반환할 때 점유 중 얻은 과실을 반환해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소유 의사 없는 점유자는 선의라도 손해 전부를 배상한다(제202조 후문). 이익이 현존하는 한도에서 배상하는 것은 선의의 자주점유자이다."},{"번호":2,"판정":"옳음","설명":"악의의 점유자는 수취한 과실을 반환해야 하므로 과실을 취득하지 못한다. 그래서 통상의 필요비도 청구할 수 있다(제203조제1항)."},{"번호":3,"판정":"틀림","설명":"법원이 허여하는 상환기간은 유익비에 관한 것이다(제203조제3항). 필요비에는 적용되지 않는다."},{"번호":4,"판정":"틀림","설명":"계약이 해제되면 선의의 매수인도 과실을 반환해야 한다. 과실취득권으로 보호받지 못한다."},{"번호":5,"판정":"틀림","설명":"폭력 또는 은비에 의한 점유자는 악의의 점유자와 같이 과실을 반환해야 한다(제201조제3항)."}],"개념":[{"종류":"표","제목":"점유자별 회복자에 대한 관계","머리":["점유자","과실(제201조)","멸실·훼손 책임(제202조)","필요비(제203조제1항)"],"행":[["선의의 자주점유자","취득","이익이 현존하는 한도","통상 필요비는 청구 불가, 특별 필요비는 가능"],["악의의 점유자","반환 및 소비·훼손분 보상","손해 전부","통상·특별 필요비 모두 청구 가능"],["폭력·은비 점유자","악의 점유자와 같음","손해 전부(악의 취급)","악의 점유자와 같음"],["소유 의사 없는 점유자","선의 여부에 따름","선의라도 손해 전부","선의 여부에 따름"]]},{"종류":"표","제목":"필요비와 유익비 비교","머리":["구분","필요비","유익비"],"행":[["의미","점유물을 보존하기 위해 지출한 금액","점유물을 개량하기 위해 지출한 금액"],["상환 범위","지출한 금액 전부(과실 취득 시 통상 필요비 제외)","가치 증가가 현존하는 경우 회복자 선택에 따라 지출액 또는 증가액"],["상환기간 허여","없음","회복자의 청구에 의해 법원이 허여 가능(제203조제3항)"],["과실을 취득한 점유자","통상의 필요비는 청구 불가","영향 없음"],["악의의 점유자","청구 가능","가치 증가가 현존하면 청구 가능"]]}],"함정":"상환기간 허여는 유익비에만 해당한다. 소유 의사 없는 점유자는 선의라도 손해 전부를 배상한다. 은비 점유자는 악의 점유자와 같이 과실을 반환한다."},"34회-1차-065":{"한줄":"환매권은 재산권이어서 양도할 수 있고 매도인의 채권자도 대위하여 행사할 수 있다.","근거":[{"법령":"민법","조문":"제590조","원문":"제590조(환매의 의의) ①매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다. ②전항의 환매대금에 관하여 특별한 약정이 있으면 그 약정에 의한다. ③전2항의 경우에 목적물의 과실과 대금의 이자는 특별한 약정이 없으면 이를 상계한 것으로 본다."},{"법령":"민법","조문":"제591조","원문":"제591조(환매기간) ①환매기간은 부동산은 5년, 동산은 3년을 넘지 못한다. 약정기간이 이를 넘는 때에는 부동산은 5년, 동산은 3년으로 단축한다. ②환매기간을 정한 때에는 다시 이를 연장하지 못한다. ③환매기간을 정하지 아니한 때에는 그 기간은 부동산은 5년, 동산은 3년으로 한다."},{"법령":"민법","조문":"제593조","원문":"제593조(환매권의 대위행사와 매수인의 권리) 매도인의 채권자가 매도인을 대위하여 환매하고자 하는 때에는 매수인은 법원이 선정한 감정인의 평가액에서 매도인이 반환할 금액을 공제한 잔액으로 매도인의 채무를 변제하고 잉여액이 있으면 이를 매도인에게 지급하여 환매권을 소멸시킬 수 있다."},{"법령":"부동산등기법","조문":"제52조","원문":"제52조(부기로 하는 등기) 등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다. 1. 등기명의인표시의 변경이나 경정의 등기 2. 소유권 외의 권리의 이전등기 3. 소유권 외의 권리를 목적으로 하는 권리에 관한 등기 4. 소유권 외의 권리에 대한 처분제한 등기 5. 권리의 변경이나 경정의 등기 6. 제53조의 환매특약등기 7. 제54조의 권리소멸약정등기 8. 제67조제1항 후단의 공유물 분할금지의 약정등기 9. 그 밖에 대법원규칙으로 정하는 등기"},{"법령":"부동산등기법","조문":"제53조","원문":"제53조(환매특약의 등기) 등기관이 환매특약의 등기를 할 때에는 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호는 등기원인에 그 사항이 정하여져 있는 경우에만 기록한다. 1. 매수인이 지급한 대금 2. 매매비용 3. 환매기간"}],"선지":[{"번호":1,"판정":"틀림","설명":"환매권은 일신전속권이 아니다. 매도인의 채권자가 대위하여 환매할 수 있고(제593조), 환매권도 양도할 수 있다."},{"번호":2,"판정":"옳음","설명":"환매특약은 매매계약에 부수하는 약정이어서 매매가 무효이면 함께 무효가 된다."},{"번호":3,"판정":"옳음","설명":"환매기간을 정한 때에는 다시 연장하지 못한다(제591조 제2항)."},{"번호":4,"판정":"옳음","설명":"환매특약의 등기는 부기로 한다(부동산등기법 제52조 제6호, 제53조)."},{"번호":5,"판정":"옳음","설명":"환매특약은 매매계약과 동시에 하여야 한다(제590조 제1항)."}],"개념":[{"종류":"표","제목":"환매의 요건과 효과","머리":["구분","내용","근거"],"행":[["시기","매매계약과 동시에 환매권 보류","제590조 제1항"],["환매대금","영수한 대금 + 매수인이 부담한 매매비용(특약 우선)","제590조 제1·2항"],["과실과 이자","특약이 없으면 상계한 것으로 봄","제590조 제3항"],["환매기간","부동산 5년, 동산 3년 이내 / 정하지 않으면 5년, 3년 / 연장 불가","제591조"],["제3자 대항","매매등기와 동시에 환매권 보류 등기","제592조"],["대금 제공","기간 내 대금과 매매비용을 제공하지 않으면 환매권 상실","제594조 제1항"],["비용 상환","매수인·전득자가 지출한 비용은 제203조에 따라 상환","제594조 제2항"]]},{"종류":"흐름","제목":"환매 절차","단계":[{"이름":"환매특약","설명":"매매계약과 동시에 합의하고 매매등기와 동시에 환매특약 등기(부기)"},{"이름":"환매권 행사","설명":"환매기간(최장 부동산 5년) 안에 대금과 매매비용을 매수인에게 제공"},{"이름":"소유권 회복","설명":"환매 의사표시와 대금 제공으로 목적물 소유권이 매도인에게 복귀"},{"이름":"비용 상환","설명":"매수인·전득자가 지출한 필요비·유익비는 제203조에 따라 상환"}]}],"함정":"환매권을 일신전속권으로 보는 것이 함정이다. 환매권은 양도·대위행사가 가능하다. 환매기간 5년은 부동산의 최장 기간이고 연장은 안 된다."},"34회-2차-012":{"한줄":"일반중개계약에도 국토교통부장관이 정한 표준서식이 있고, 다만 사용은 권장일 뿐이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제19조","원문":"국토교통부장관은 법 제22조의 규정에 따른 일반중개계약의 표준이 되는 서식을 정하여 그 사용을 권장할 수 있다."},{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"제14조","원문":"①법 제23조제2항의 규정에 따른 전속중개계약서는 별지 제15호서식에 따른다. ②법 제23조제2항에서 \"국토교통부령이 정하는 기간\"이라 함은 3년을 말한다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제15호서식(전속중개계약서)","원문":"전속중개계약의 유효기간 내에 갑이 스스로 발견한 상대방과 거래한 경우(제3호)에는 중개보수의 50퍼센트에 해당하는 금액의 범위에서 을이 중개행위를 할 때 소요된 비용(사회통념에 비추어 상당하다고 인정되는 비용을 말한다)을 지급한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"3년 보존의무는 전속중개계약서에만 있다. 일반중개계약서는 보존의무가 없다(법 제23조제2항, 규칙 제14조제2항)."},{"번호":2,"판정":"옳음","설명":"표준서식이 있고 사용은 권장이다(영 제19조)."},{"번호":3,"판정":"틀림","설명":"전속중개계약서 서식 끝은 의뢰인과 개업공인중개사가 각자 서명 또는 날인한다. 소속공인중개사의 함께 서명 및 날인은 요구되지 않는다(별지 제15호서식)."},{"번호":4,"판정":"틀림","설명":"3개월은 정하지 않았을 때의 기간이고, 당사자 약정이 있으면 그에 따른다(영 제20조제1항)."},{"번호":5,"판정":"틀림","설명":"스스로 발견한 상대방과 거래하면 위약금이 아니라 중개보수의 50% 범위에서 중개사가 쓴 비용을 낸다(별지 제15호서식)."}],"개념":[{"종류":"표","제목":"일반중개계약과 전속중개계약","머리":["구분","일반중개계약","전속중개계약"],"행":[["계약서","의뢰인이 요청하면 작성, 표준서식 사용 권장(영 제19조)","국토교통부령 서식(별지 제15호) 필수(법 제23조제2항)"],["보존","의무 없음","3년"],["처리상황 통지","의무 없음","2주일에 1회 이상 문서"],["정보공개","의무 없음","체결 후 7일 이내 정보망·일간신문, 비공개 요청 시 공개 금지"],["유효기간","정한 바 없음","원칙 3개월, 약정이 있으면 그에 따름"],["제재","없음","서식 미사용·미보존은 업무정지, 공개 위반은 등록취소 가능"]]},{"종류":"표","제목":"전속중개계약 중 거래한 경우 의뢰인 부담","머리":["상황","의뢰인 부담"],"행":[["다른 개업공인중개사에게 의뢰해 거래","중개보수에 해당하는 금액을 위약금으로 지급"],["소개받은 상대방과 중개사를 배제하고 직접 거래","중개보수에 해당하는 금액을 위약금으로 지급"],["스스로 발견한 상대방과 거래","중개보수의 50% 범위에서 소요된 비용(사회통념상 상당한 비용)"]]}],"함정":"일반과 전속의 의무를 맞바꾼 선지가 나온다. 선지 1은 전속의 3년 보존을 일반에 붙였다. 선지 5는 스스로 발견한 상대방을 소개받은 상대방과 같은 취급으로 쓴 것이다."},"34회-2차-059":{"한줄":"공동으로 사용하는 구판장은 공동이용시설이고 정비기반시설이 아니다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제2조제4호","원문":"4. \"정비기반시설\"이란 도로ㆍ상하수도ㆍ구거(溝渠: 도랑)ㆍ공원ㆍ공용주차장ㆍ공동구(「국토의 계획 및 이용에 관한 법률」 제2조제9호에 따른 공동구를 말한다. 이하 같다), 그 밖에 주민의 생활에 필요한 열ㆍ가스 등의 공급시설로서 대통령령으로 정하는 시설을 말한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제3조","원문":"제3조(정비기반시설) 법 제2조제4호에서 \"대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다. 1. 녹지 3. 공공공지 5. 소방용수시설"},{"법령":"도시 및 주거환경정비법","조문":"제2조제5호","원문":"5. \"공동이용시설\"이란 주민이 공동으로 사용하는 놀이터ㆍ마을회관ㆍ공동작업장, 그 밖에 대통령령으로 정하는 시설을 말한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제4조","원문":"제4조(공동이용시설) 법 제2조제5호에서 \"대통령령으로 정하는 시설\"이란 다음 각 호의 시설을 말한다. 1. 공동으로 사용하는 구판장ㆍ세탁장ㆍ화장실 및 수도"}],"선지":[{"번호":1,"판정":"옳음","설명":"녹지는 정비기반시설이다(영 제3조제1호)."},{"번호":2,"판정":"옳음","설명":"공공공지는 정비기반시설이다(영 제3조제3호)."},{"번호":3,"판정":"옳음","설명":"공용주차장은 법에서 직접 정한 정비기반시설이다(법 제2조제4호)."},{"번호":4,"판정":"옳음","설명":"소방용수시설은 정비기반시설이다(영 제3조제5호)."},{"번호":5,"판정":"틀림","설명":"공동으로 사용하는 구판장은 공동이용시설이다(영 제4조제1호). 주거환경개선사업 정비구역에서 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 공동이용시설만 정비기반시설이 되는데(영 제3조제9호), 이 문항은 그 정비구역이 아니다."}],"개념":[{"종류":"표","제목":"정비기반시설과 공동이용시설","머리":["구분","시설","근거"],"행":[["정비기반시설(법)","도로, 상하수도, 구거, 공원, 공용주차장, 공동구, 열·가스 등 공급시설","법 제2조제4호"],["정비기반시설(영)","녹지, 하천, 공공공지, 광장, 소방용수시설, 비상대피시설, 가스공급시설, 지역난방시설","영 제3조제1호~제8호"],["정비기반시설(영)","주거환경개선사업 정비구역의 공동이용시설로서 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 시설","영 제3조제9호"],["공동이용시설(법)","놀이터, 마을회관, 공동작업장","법 제2조제5호"],["공동이용시설(영)","공동으로 사용하는 구판장·세탁장·화장실 및 수도, 탁아소·어린이집·경로당 등 노유자시설, 시·도조례로 정하는 유사 시설","영 제4조"]]},{"종류":"표","제목":"정비사업의 종류(법 제2조제2호)","머리":["사업","대상 지역·목적"],"행":[["주거환경개선사업","도시저소득 주민이 집단거주하고 정비기반시설이 극히 열악하며 노후·불량건축물이 과도하게 밀집한 지역의 주거환경 개선, 또는 단독주택·다세대주택 밀집 지역에서 정비기반시설과 공동이용시설 확충"],["재개발사업","정비기반시설이 열악하고 노후·불량건축물이 밀집한 지역의 주거환경 개선, 상업지역·공업지역 등에서 도시기능 회복과 상권활성화를 위한 도시환경 개선"],["재건축사업","정비기반시설은 양호하나 노후·불량건축물에 해당하는 공동주택이 밀집한 지역의 주거환경 개선"]]}],"함정":"구판장·세탁장·화장실·수도·어린이집·경로당은 공동이용시설이고, 녹지·하천·공공공지·광장·소방용수시설은 정비기반시설이다. 주거환경개선사업 정비구역에서는 사업시행계획서에 시장·군수등이 관리하는 것으로 포함된 공동이용시설이 정비기반시설이 된다(영 제3조제9호)."},"34회-2차-076":{"한줄":"문화 및 집회시설은 출구 설치 대상이지만 전시장 및 동·식물원은 제외된다.","근거":[{"법령":"건축법 시행령","조문":"영 제39조제1항","원문":"① 법 제49조제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물에는 국토교통부령으로 정하는 기준에 따라 그 건축물로부터 바깥쪽으로 나가는 출구를 설치하여야 한다.\n1. 제2종 근린생활시설 중 공연장ㆍ종교집회장ㆍ인터넷컴퓨터게임시설제공업소(해당 용도로 쓰는 바닥면적의 합계가 각각 300제곱미터 이상인 경우만 해당한다)\n2. 문화 및 집회시설(전시장 및 동ㆍ식물원은 제외한다)\n3. 종교시설\n4. 판매시설\n5. 업무시설 중 국가 또는 지방자치단체의 청사\n6. 위락시설\n7. 연면적이 5천 제곱미터 이상인 창고시설\n8. 교육연구시설 중 학교\n9. 장례시설\n10. 승강기를 설치하여야 하는 건축물"}],"선지":[{"번호":1,"판정":"틀림","설명":"전시장은 문화 및 집회시설이지만 영 제39조제1항제2호가 「전시장 및 동·식물원은 제외한다」고 정한다. 출구 설치 대상이 아니다."},{"번호":2,"판정":"옳음","설명":"무도학원은 위락시설(별표 1 제16호마목)이고 위락시설은 대상이다(영 제39조제1항제6호)."},{"번호":3,"판정":"옳음","설명":"동물 전용의 장례식장은 장례시설(별표 1 제28호나목)이고 장례시설은 대상이다(영 제39조제1항제9호)."},{"번호":4,"판정":"옳음","설명":"인터넷컴퓨터게임시설제공업소는 해당 용도 바닥면적 합계가 300제곱미터 이상이면 대상이다(영 제39조제1항제1호). 문제의 단서가 300제곱미터 이상으로 주어져 있다."},{"번호":5,"판정":"옳음","설명":"업무시설 중 국가 또는 지방자치단체의 청사가 대상이다(영 제39조제1항제5호)."}],"개념":[{"종류":"표","제목":"바깥쪽으로 나가는 출구 설치 대상(영 제39조제1항)","머리":["호","대상 건축물","단서"],"행":[["1","제2종 근린생활시설 중 공연장·종교집회장·인터넷컴퓨터게임시설제공업소","해당 용도 바닥면적 합계가 각각 300제곱미터 이상인 경우만"],["2","문화 및 집회시설","전시장 및 동·식물원 제외"],["3","종교시설","-"],["4","판매시설","-"],["5","업무시설 중 국가 또는 지방자치단체의 청사","-"],["6","위락시설","-"],["7","창고시설","연면적 5천제곱미터 이상인 경우만"],["8","교육연구시설 중 학교","-"],["9","장례시설","-"],["10","승강기를 설치하여야 하는 건축물","-"]]},{"종류":"표","제목":"문화 및 집회시설의 세부 용도(별표 1 제5호)","머리":["목","용도","출구 설치 대상 여부"],"행":[["가","공연장(제2종 근린생활시설에 해당하지 않는 것)","대상"],["나","집회장(예식장, 공회당, 회의장 등)","대상"],["다","관람장(경마장, 경륜장, 경정장, 자동차 경기장 등)","대상"],["라","전시장(박물관, 미술관, 과학관, 산업전시장 등)","제외"],["마","동·식물원(동물원, 식물원, 수족관 등)","제외"]]}],"함정":"문화 및 집회시설을 통째로 대상으로 보면 전시장에서 틀린다. 무도학원은 위락시설(별표 1 제16호마목), 동물 전용의 장례식장은 장례시설(별표 1 제28호나목)로 분류되어 출구 설치 대상에 든다."},"34회-2차-073":{"한줄":"건축협정구역에서 완화 적용하는 기준 중 용적률(제56조)만 건축위원회와 지방도시계획위원회의 통합 심의를 거친다.","근거":[{"법령":"건축법","조문":"법 제77조의13제6항","원문":"⑥ 건축협정구역에 건축하는 건축물에 대하여는 제42조, 제55조, 제56조, 제58조, 제60조 및 제61조와 「주택법」 제35조를 대통령령으로 정하는 바에 따라 완화하여 적용할 수 있다. 다만, 제56조를 완화하여 적용하는 경우에는 제4조에 따른 건축위원회의 심의와 「국토의 계획 및 이용에 관한 법률」 제113조에 따른 지방도시계획위원회의 심의를 통합하여 거쳐야 한다."},{"법령":"건축법 시행령","조문":"영 제110조의7제1항","원문":"① 건축협정구역에서 건축하는 건축물에 대해서는 법 제77조의13제6항에 따라 법 제42조, 제55조, 제56조, 제60조 및 제61조를 다음 각 호의 구분에 따라 완화하여 적용할 수 있다.\n2. 법 제55조에 따른 건폐율: 해당 지역에 적용하는 건폐율의 100분의 20의 범위에서 완화. 이 경우 「국토의 계획 및 이용에 관한 법률 시행령」 제84조에 따른 건폐율의 최대한도를 초과할 수 없다.\n3. 법 제56조에 따른 용적률: 해당 지역에 적용하는 용적률의 100분의 20의 범위에서 완화. 이 경우 「국토의 계획 및 이용에 관한 법률 시행령」 제85조에 따른 용적률의 최대한도를 초과할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"용적률(법 제56조)을 완화 적용하는 경우에만 건축위원회와 지방도시계획위원회의 심의를 통합하여 거친다(법 제77조의13제6항 단서)."},{"번호":2,"판정":"틀림","설명":"건폐율(법 제55조)은 기준의 100분의 20 범위에서 완화하며 국토계획법 시행령 제84조의 최대한도를 넘을 수 없다(영 제110조의7제1항제2호). 통합 심의는 제56조를 완화하는 경우에 한한다."},{"번호":3,"판정":"틀림","설명":"높이 제한(법 제60조)은 너비 6미터 이상의 도로에 접한 구역에 한해 높이 기준의 100분의 20 범위에서 완화한다(영 제110조의7제1항제4호). 이 완화는 통합 심의를 거치지 않는다."},{"번호":4,"판정":"틀림","설명":"대지의 조경 면적(법 제42조)은 도로에 면해 통합 조성하는 구역에 한해 기준의 100분의 20 범위에서 완화한다(영 제110조의7제1항제1호). 건축위원회 심의만으로 족하다."},{"번호":5,"판정":"틀림","설명":"일조 등의 확보를 위한 높이 제한(법 제61조)은 구역 안 대지 상호간에 건축하는 공동주택에 한해 100분의 20 범위에서 완화한다(영 제110조의7제1항제5호). 통합 심의 규정과 무관하다."}],"개념":[{"종류":"표","제목":"건축협정구역의 건축기준 완화(법 제77조의13제6항, 영 제110조의7제1항)","머리":["완화 기준","완화 범위","조건·심의"],"행":[["대지의 조경(법 제42조)","조경 면적 기준의 100분의 20 범위","도로에 면하여 통합 조성하는 건축협정구역에 한정"],["건폐율(법 제55조)","기준의 100분의 20 범위","국토계획법 시행령 제84조의 최대한도 초과 불가"],["용적률(법 제56조)","기준의 100분의 20 범위","국토계획법 시행령 제85조의 최대한도 초과 불가. 건축위원회와 지방도시계획위원회 통합 심의"],["높이 제한(법 제60조)","높이 기준의 100분의 20 범위","너비 6미터 이상 도로에 접한 구역에 한정"],["일조 등 높이 제한(법 제61조)","기준의 100분의 20 범위","구역 안 대지 상호간에 건축하는 공동주택에 한정"]]},{"종류":"흐름","제목":"건축협정의 체결부터 폐지까지","단계":[{"이름":"체결","설명":"토지 또는 건축물의 소유자, 지상권자 등이 전원의 합의로 지구단위계획구역 등에서 체결한다. 토지 소유자가 1인이어도 체결할 수 있다(법 제77조의4제1항·제2항)."},{"이름":"인가","설명":"협정체결자 또는 건축협정운영회의 대표자가 건축협정서를 작성해 건축협정인가권자의 인가를 받는다. 인가 전 건축위원회 심의를 거친다(법 제77조의6제1항)."},{"이름":"공고","설명":"인가하면 내용을 공고한다. 공고 후 권리를 이전받은 자는 협정체결자의 지위를 승계한다(법 제77조의6제3항, 제77조의10제2항)."},{"이름":"변경","설명":"인가받은 사항을 변경하려면 변경인가를 받는다. 경미한 사항은 제외한다(법 제77조의7)."},{"이름":"폐지","설명":"협정체결자 과반수의 동의를 받아 건축협정인가권자의 인가를 받는다(법 제77조의9제1항)."}]}],"함정":"완화 대상은 조경·건폐율·용적률·높이·일조 높이 다섯 가지이지만 통합 심의는 용적률만이다. 건폐율을 용적률과 같은 묶음으로 보기 쉽다. 이 외에 맞벽 건축 등에서는 대지의 조경, 대지와 도로의 관계, 지하층, 건폐율, 부설주차장 등을 통합 적용하는 별도 특례가 있다(법 제77조의13제3항)."},"34회-2차-070":{"한줄":"주택에 딸린 자전거보관소는 복리시설이 아니라 부대시설이다.","근거":[{"법령":"주택법 시행령","조문":"영 제6조제1호","원문":"제6조(부대시설의 범위) 법 제2조제13호다목에서 \"대통령령으로 정하는 시설 또는 설비\"란 다음 각 호의 시설 또는 설비를 말한다.\n1. 보안등, 대문, 경비실 및 자전거보관소"},{"법령":"주택법","조문":"법 제2조제13호·제14호","원문":"13. \"부대시설\"이란 주택에 딸린 다음 각 목의 시설 또는 설비를 말한다.\n14. \"복리시설\"이란 주택단지의 입주자 등의 생활복리를 위한 다음 각 목의 공동시설을 말한다.\n가. 어린이놀이터, 근린생활시설, 유치원, 주민운동시설 및 경로당"},{"법령":"주택법 시행령","조문":"영 제4조제4호","원문":"제4조(준주택의 종류와 범위) 법 제2조제4호에 따른 준주택의 종류와 범위는 다음 각 호와 같다.\n4. 「건축법 시행령」 별표 1 제14호나목2)에 따른 오피스텔"},{"법령":"주택법","조문":"법 제2조제12호다목","원문":"12. \"주택단지\"란 제15조에 따른 주택건설사업계획 또는 대지조성사업계획의 승인을 받아 주택과 그 부대시설 및 복리시설을 건설하거나 대지를 조성하는 데 사용되는 일단(一團)의 토지를 말한다. 다만, 다음 각 목의 시설로 분리된 토지는 각각 별개의 주택단지로 본다.\n다. 폭 8미터 이상인 도시계획예정도로"},{"법령":"주택법","조문":"법 제2조제16호","원문":"16. \"기간시설\"(基幹施設)이란 도로ㆍ상하수도ㆍ전기시설ㆍ가스시설ㆍ통신시설ㆍ지역난방시설 등을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"다세대주택은 공동주택의 종류다(영 제3조제1항제3호)."},{"번호":2,"판정":"옳음","설명":"오피스텔은 준주택이다(영 제4조제4호)."},{"번호":3,"판정":"옳음","설명":"폭 8미터 이상인 도시계획예정도로로 분리된 토지는 각각 별개의 주택단지로 본다(법 제2조제12호다목)."},{"번호":4,"판정":"틀림","설명":"자전거보관소는 부대시설이다(영 제6조제1호). 복리시설은 어린이놀이터, 근린생활시설, 유치원, 주민운동시설, 경로당 등이다(법 제2조제14호)."},{"번호":5,"판정":"옳음","설명":"도로·상하수도·전기시설·가스시설·통신시설·지역난방시설 등이 기간시설이다(법 제2조제16호)."}],"개념":[{"종류":"비교","제목":"부대시설과 복리시설","왼쪽":{"이름":"부대시설(법 제2조제13호, 영 제6조)","항목":["주차장, 관리사무소, 담장, 주택단지 안의 도로","건축설비(전기·가스·급수·배수·난방·소화·승강기 등)","보안등, 대문, 경비실, 자전거보관소","조경시설, 옹벽, 축대","안내표지판, 공중화장실","저수시설, 지하양수시설, 대피시설","쓰레기 수거·처리시설, 오수처리시설, 정화조","소방시설, 냉난방공급시설(지역난방공급시설 제외), 방범설비","전기자동차 충전 공급시설"]},"오른쪽":{"이름":"복리시설(법 제2조제14호, 영 제7조)","항목":["어린이놀이터, 근린생활시설, 유치원, 주민운동시설, 경로당","종교시설, 판매시설 중 소매시장 및 상점","교육연구시설, 노유자시설, 수련시설","업무시설 중 금융업소, 지식산업센터, 사회복지관","공동작업장, 주민공동시설, 도시·군계획시설인 시장","제2종 근린생활시설 중 총포판매소·장의사·다중생활시설·단란주점·안마시술소는 제외"]}},{"종류":"표","제목":"주택법상 주택·준주택·주택단지 용어","머리":["용어","내용","근거"],"행":[["공동주택","아파트, 연립주택, 다세대주택","영 제3조제1항"],["준주택","기숙사, 다중생활시설, 노인복지주택, 오피스텔","영 제4조"],["주택단지 분리","철도·고속도로·자동차전용도로, 폭 20미터 이상 일반도로, 폭 8미터 이상 도시계획예정도로로 분리된 토지는 별개의 주택단지","법 제2조제12호"],["기간시설","도로·상하수도·전기시설·가스시설·통신시설·지역난방시설 등","법 제2조제16호"],["간선시설","주택단지 안의 기간시설을 단지 밖의 같은 종류의 기간시설에 연결시키는 시설. 가스·통신·지역난방은 단지 안 기간시설 포함","법 제2조제17호"]]}],"함정":"부대시설과 복리시설의 구분이 핵심이다. 자전거보관소·경비실·조경시설·방범설비는 부대시설이고, 주민공동시설·어린이놀이터·경로당은 복리시설이다. 기간시설은 도로·상하수도 등 시설 자체이고, 간선시설은 단지 안 기간시설을 단지 밖 같은 종류의 기간시설에 연결하는 시설이다(법 제2조제17호)."},"34회-2차-091":{"한줄":"토지대장은 확정공고된 축척변경 지번별 조서에 따라 등록한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제2항","원문":"② 영 제78조제2항에 따라 지적공부에 등록하는 때에는 다음 각 호의 기준에 따라야 한다.\n  1. 토지대장은 제1항제2호에 따라 확정공고된 축척변경 지번별 조서에 따를 것\n  2. 지적도는 확정측량 결과도 또는 경계점좌표에 따를 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조제2항","원문":"② 지적소관청은 제1항에 따른 확정공고를 하였을 때에는 지체 없이 축척변경에 따라 확정된 사항을 지적공부에 등록하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"확정측량 결과도는 지적도에 등록하는 기준이다(규칙 제92조제2항제2호)."},{"번호":2,"판정":"틀림","설명":"청산금납부고지서는 청산금을 고지할 때 쓰는 서식이다(규칙 제90조). 지적공부 등록 기준이 아니다."},{"번호":3,"판정":"틀림","설명":"토지이동현황 조사계획은 지적소관청이 직권으로 토지이동을 조사ㆍ측량할 때 세우는 계획이다(규칙 제59조제1항)."},{"번호":4,"판정":"옳음","설명":"토지대장은 확정공고된 축척변경 지번별 조서에 따른다(규칙 제92조제2항제1호)."},{"번호":5,"판정":"틀림","설명":"시행계획은 시행공고 사항이다(영 제71조제1항제2호). 등록 기준이 아니다."}],"개념":[{"종류":"표","제목":"축척변경 확정사항의 지적공부 등록 기준","머리":["대상","등록 기준","근거"],"행":[["토지대장","확정공고된 축척변경 지번별 조서","규칙 제92조제2항제1호"],["지적도","확정측량 결과도 또는 경계점좌표","규칙 제92조제2항제2호"],["면적(원칙)","축척변경 측량 결과도","규칙 제87조제1항"],["면적(오차가 허용범위 이내)","축척변경 전의 면적을 결정면적으로 함","규칙 제87조제2항"],["면적(오차가 허용면적 초과)","축척변경 후의 면적을 결정면적으로 함","규칙 제87조제2항"],["경계점좌표등록부를 새로 갖추는 지역","경계점좌표에 따라 면적 결정","규칙 제87조제3항"]]},{"종류":"흐름","제목":"확정공고 이후","단계":[{"이름":"확정공고","설명":"청산금의 납부 및 지급이 완료되었을 때 지체 없이"},{"이름":"지적공부 등록","설명":"토지대장은 지번별 조서, 지적도는 확정측량 결과도 또는 경계점좌표에 따라 등록"},{"이름":"토지 이동 시기","설명":"확정공고일에 토지의 이동이 있는 것으로 본다"},{"이름":"등기촉탁","설명":"토지의 표시 변경 등기가 필요하면 지체 없이 관할 등기관서에 촉탁"}]}],"함정":"토지대장은 지번별 조서, 지적도는 확정측량 결과도 또는 경계점좌표다. 두 공부의 기준을 서로 바꾼 ①이 가장 그럴듯한 오답이다."},"34회-2차-095":{"한줄":"위조 서류로 말소된 1번 근저당권등기가 회복되면 종전 순위를 되찾으므로 1번이 2번보다 우선한다.","근거":[{"법령":"부동산등기법","조문":"제4조","원문":"제4조(권리의 순위)\n① 같은 부동산에 관하여 등기한 권리의 순위는 법률에 다른 규정이 없으면 등기한 순서에 따른다.\n② 등기의 순서는 등기기록 중 같은 구(區)에서 한 등기 상호간에는 순위번호에 따르고, 다른 구에서 한 등기 상호간에는 접수번호에 따른다."},{"법령":"부동산등기법","조문":"제5조","원문":"제5조(부기등기의 순위) 부기등기(附記登記)의 순위는 주등기(主登記)의 순위에 따른다. 다만, 같은 주등기에 관한 부기등기 상호간의 순위는 그 등기 순서에 따른다."},{"법령":"부동산등기법","조문":"제59조","원문":"제59조(말소등기의 회복) 말소된 등기의 회복(回復)을 신청하는 경우에 등기상 이해관계 있는 제3자가 있을 때에는 그 제3자의 승낙이 있어야 한다."},{"법령":"부동산등기법","조문":"제91조","원문":"제91조(가등기에 의한 본등기의 순위) 가등기에 의한 본등기(本登記)를 한 경우 본등기의 순위는 가등기의 순위에 따른다."},{"이론":"말소회복등기의 순위(판례 취지)","내용":"말소된 등기를 회복하면 말소 전의 순위와 효력을 되찾는다. 말소 후 회복 전에 설정된 등기의 명의인은 등기상 이해관계 있는 제3자로서 회복등기에 승낙할 의무가 있다."},{"이론":"나대지 근저당권과 대지권(판례 취지)","내용":"집합건물 착공 전 나대지에 설정된 근저당권은 건물 신축과 대지권등기보다 앞서 성립한 권리여서 대지권등기에 우선한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"가압류등기는 갑구, 저당권설정등기는 을구에 하므로 다른 구의 등기다. 접수번호로 순위를 정한다(법 제4조제2항)."},{"번호":2,"판정":"옳음","설명":"부기등기의 순위는 주등기에 따른다. 1번 저당권의 일부이전 부기등기는 1번 순위여서 2번 저당권에 우선한다(법 제5조)."},{"번호":3,"판정":"틀림","설명":"회복된 1번 근저당권은 종전 순위를 되찾는다. 말소 뒤에 설정된 2번 근저당권자는 회복에 승낙할 의무가 있고 1번이 우선한다(법 제59조, 판례 취지)."},{"번호":4,"판정":"옳음","설명":"가등기에 의한 본등기의 순위는 가등기 순위에 따르므로 본등기가 제3자 명의 등기에 우선한다. 등기관은 가등기에 의하여 보전되는 권리를 침해하는 이후 등기를 직권으로 말소한다(법 제91조, 제92조제1항)."},{"번호":5,"판정":"옳음","설명":"착공 전에 설정된 근저당권은 대지권등기보다 먼저 성립한 권리여서 대지권등기에 우선한다(판례 취지)."}],"개념":[{"종류":"표","제목":"등기의 순위 결정","머리":["상황","순위 기준","근거"],"행":[["같은 구에서 한 등기 상호간","순위번호","법 제4조제2항"],["다른 구에서 한 등기 상호간(갑구와 을구)","접수번호","법 제4조제2항"],["부기등기와 주등기","주등기의 순위","법 제5조"],["같은 주등기에 관한 부기등기 상호간","그 등기 순서","법 제5조 단서"],["가등기에 의한 본등기","가등기의 순위","법 제91조"],["대지권에 대한 등기로서 효력이 있는 건물 등기와 토지 등기기록 중 해당 구의 등기","접수번호","법 제61조제2항"],["등기신청의 접수 시기","신청정보가 전산정보처리조직에 저장된 때","법 제6조제1항"],["등기의 효력 발생","접수한 때부터","법 제6조제2항"]]},{"종류":"표","제목":"부기로 하는 등기 (법 제52조)","머리":["부기 대상","비고"],"행":[["등기명의인표시의 변경이나 경정의 등기","-"],["소유권 외의 권리의 이전등기","저당권 이전 등이 해당"],["소유권 외의 권리를 목적으로 하는 권리에 관한 등기","전세권저당권 등"],["소유권 외의 권리에 대한 처분제한 등기","-"],["권리의 변경이나 경정의 등기","이해관계 있는 제3자의 승낙이 없으면 주등기"],["환매특약등기, 권리소멸약정등기, 공유물 분할금지약정등기","-"]]}],"함정":"부기등기는 별도 순위가 아니라 주등기의 순위를 갖는다(②). 말소회복은 새 등기가 아니라 종전 순위를 되찾는 것이어서 회복 전에 설정된 후순위 등기보다 앞선다(③). 갑구와 을구 등기는 접수번호로 비교한다(①)."},"34회-2차-093":{"한줄":"학교는 법인도 법인 아닌 사단ㆍ재단도 아니어서 등기명의인이 될 수 없고, 학교법인 명의로 등기한다.","근거":[{"법령":"부동산등기법","조문":"제26조","원문":"제26조(법인 아닌 사단 등의 등기신청)\n① 종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다.\n② 제1항의 등기는 그 사단이나 재단의 명의로 그 대표자나 관리인이 신청한다."},{"법령":"부동산등기법","조문":"제28조","원문":"제28조(채권자대위권에 의한 등기신청)\n① 채권자는 「민법」 제404조에 따라 채무자를 대위(代位)하여 등기를 신청할 수 있다.\n② 등기관이 제1항 또는 다른 법령에 따른 대위신청에 의하여 등기를 할 때에는 대위자의 성명 또는 명칭, 주소 또는 사무소 소재지 및 대위원인을 기록하여야 한다."},{"법령":"민법","조문":"제124조","원문":"제124조(자기계약, 쌍방대리) 대리인은 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자쌍방을 대리하지 못한다. 그러나 채무의 이행은 할 수 있다."},{"법령":"민법","조문":"제147조제1항","원문":"①정지조건있는 법률행위는 조건이 성취한 때로부터 그 효력이 생긴다."},{"이론":"등기명의인의 자격","내용":"자연인, 법인, 대표자나 관리인이 있는 법인 아닌 사단ㆍ재단이 등기명의인이 될 수 있다. 학교 자체는 이에 해당하지 않아 학교법인 명의로 등기한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"정지조건부 유증은 조건이 성취된 때 효력이 생기므로 조건 성취를 증명하는 정보를 함께 제공한다(민법 제147조제1항, 규칙 제46조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"학교 명의로는 등기하지 못한다. 학교법인이 등기명의인이다."},{"번호":3,"판정":"옳음","설명":"등기신청은 채무의 이행이어서 쌍방대리가 허용된다(민법 제124조 단서)."},{"번호":4,"판정":"옳음","설명":"종중은 그 명의로 등기하고 대표자가 신청한다(법 제26조)."},{"번호":5,"판정":"옳음","설명":"대위채권자는 채무자의 권리를 자기 이름으로 행사하며, 등기에는 대위자와 대위원인이 기록된다(법 제28조, 민법 제404조)."}],"개념":[{"종류":"표","제목":"등기신청인에 관한 규정","머리":["구분","내용","근거"],"행":[["원칙","등기권리자와 등기의무자가 공동으로 신청","법 제23조제1항"],["법인 아닌 사단ㆍ재단","그 사단ㆍ재단 명의로 대표자나 관리인이 신청","법 제26조"],["포괄승계인","등기원인 발생 후 상속 등이 있으면 상속인 등이 신청","법 제27조"],["채권자대위","채권자가 채무자를 대위하여 신청, 대위자 성명ㆍ주소ㆍ대위원인을 기록","법 제28조"],["신청 방법","방문신청(신청인 또는 대리인이 등기소에 출석하여 서면 제출) 또는 전자신청","법 제24조제1항"],["대리인","채무 이행인 등기신청은 쌍방대리 가능","민법 제124조 단서"]]},{"종류":"표","제목":"등기신청의 각하 사유 (법 제29조)","머리":["번호","사유"],"행":[["1","사건이 그 등기소의 관할이 아닌 경우"],["2","사건이 등기할 것이 아닌 경우"],["3","신청할 권한이 없는 자가 신청한 경우"],["4","방문신청에서 당사자나 대리인이 출석하지 아니한 경우"],["5","신청정보의 제공이 대법원규칙으로 정한 방식에 맞지 아니한 경우"],["6","신청정보의 부동산 또는 권리의 표시가 등기기록과 일치하지 아니한 경우"],["7","신청정보의 등기의무자 표시가 등기기록과 일치하지 아니한 경우(포괄승계인 신청 등 제외)"],["8","신청정보와 등기원인을 증명하는 정보가 일치하지 아니한 경우"],["9","등기에 필요한 첨부정보를 제공하지 아니한 경우"],["10","취득세ㆍ등록면허세ㆍ수수료를 내지 아니하거나 다른 법률에 따라 부과된 의무를 이행하지 아니한 경우"],["11","신청정보 또는 등기기록의 부동산 표시가 토지대장ㆍ임야대장ㆍ건축물대장과 일치하지 아니한 경우"]]}],"함정":"종중 같은 법인 아닌 사단은 명의 자격이 있어 ④가 옳다. 학교는 사단도 재단도 아닌 시설이어서 학교 이름으로는 등기할 수 없다. 쌍방대리가 안 된다는 민법 원칙(③)은 채무이행에는 적용되지 않는다."},"34회-2차-114":{"한줄":"신고가 없거나 신고가액이 시가표준액보다 적으면 시가표준액이 과세표준이다. 신고가액이 시가표준액보다 많은 경우는 신고가액을 따른다.","근거":[{"법령":"지방세법","조문":"제27조제2항","원문":"제1항에 따른 과세표준은 조례로 정하는 바에 따라 등록자의 신고에 따른다. 다만, 신고가 없거나 신고가액이 제4조에 따른 시가표준액보다 적은 경우에는 시가표준액을 과세표준으로 한다."},{"법령":"지방세법","조문":"제25조제1항제16호","원문":"같은 등록에 관계되는 재산이 둘 이상의 지방자치단체에 걸쳐 있어 등록면허세를 지방자치단체별로 부과할 수 없을 때에는 등록관청 소재지를 납세지로 한다."},{"법령":"지방세법","조문":"제28조제6항","원문":"지방자치단체의 장은 조례로 정하는 바에 따라 등록면허세의 세율을 제1항제1호에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다."},{"법령":"지방세법 시행령","조문":"제42조제2항","원문":"주택의 토지와 건축물을 한꺼번에 평가하여 토지나 건축물에 대한 과세표준이 구분되지 아니하는 경우에는 한꺼번에 평가한 개별주택가격을 토지나 건축물의 가액 비율로 나눈 금액을 각각 토지와 건축물의 과세표준으로 한다."},{"법령":"지방세법","조문":"제30조제5항","원문":"채권자대위자는 납세의무자를 대위하여 부동산의 등기에 대한 등록면허세를 신고납부할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"재산이 둘 이상의 지방자치단체에 걸쳐 따로 부과할 수 없으면 등록관청 소재지가 납세지다(지방세법 제25조 제1항 제16호)."},{"번호":2,"판정":"옳음","설명":"조례로 부동산 등기 표준세율의 100분의 50 범위에서 가감할 수 있다(지방세법 제28조 제6항)."},{"번호":3,"판정":"옳음","설명":"주택의 토지와 건축물이 한꺼번에 평가되어 구분되지 않으면 개별주택가격을 가액 비율로 나눠 각각의 과세표준으로 한다(지방세법 시행령 제42조 제2항)."},{"번호":4,"판정":"틀림","설명":"신고가 없거나 신고가액이 시가표준액보다 적은 경우에 시가표준액을 과세표준으로 한다. 신고가액이 시가표준액보다 많으면 신고가액이다(지방세법 제27조 제2항)."},{"번호":5,"판정":"옳음","설명":"채권자대위자는 납세의무자를 대위해 부동산 등기의 등록면허세를 신고납부할 수 있다. 지방자치단체의 장은 이를 납세의무자에게 즉시 통보한다(지방세법 제30조 제5항·제6항)."}],"개념":[{"종류":"표","제목":"부동산 등기 등록면허세 표준세율(제28조제1항제1호)","머리":["등기","과세표준","세율"],"행":[["소유권 보존","부동산 가액","1천분의 8"],["소유권 이전(유상)","부동산 가액","1천분의 20(유상 주택은 주택 취득세율의 100분의 50)"],["소유권 이전(무상)","부동산 가액","1천분의 15"],["소유권 이전(상속)","부동산 가액","1천분의 8"],["지상권","부동산 가액","1천분의 2"],["저당권","채권금액","1천분의 2"],["지역권","요역지 가액","1천분의 2"],["전세권","전세금액","1천분의 2"],["임차권","월 임대차금액","1천분의 2"],["경매신청·가압류·가처분","채권금액","1천분의 2"],["가등기","부동산 가액 또는 채권금액","1천분의 2"],["그 밖의 등기","건당","6천원"]]},{"종류":"표","제목":"등기·등록 등록면허세 납세지(제25조제1항)","머리":["등기·등록","납세지"],"행":[["부동산 등기","부동산 소재지"],["선박 등기·등록","선적항 소재지"],["법인 등기","등기에 관련되는 본점·지점 또는 주사무소·분사무소 등의 소재지"],["상호 등기","영업소 소재지"],["광업권 및 조광권 등록","광구 소재지"],["그 밖의 등록","등록관청 소재지"],["재산이 둘 이상의 지방자치단체에 걸쳐 따로 부과할 수 없는 경우","등록관청 소재지"],["같은 채권 담보를 위한 둘 이상의 저당권 등록","하나의 등록으로 보아 처음 등록하는 등록관청 소재지"]]}],"함정":"④는 비교 방향을 바꾼 문장이다. 시가표준액은 신고가액의 하한이라서 신고가액이 더 크면 신고가액이 과세표준이 된다."},"34회-2차-003":{"한줄":"공인중개사는 자격을 취득한 자이고 개설등록 여부와 관계가 없으므로 ⑤가 옳다.","근거":[{"법령":"공인중개사법","조문":"제2조제1호","원문":"\"중개\"라 함은 제3조에 따른 중개대상물에 대하여 거래당사자간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 알선하는 것을 말한다."},{"법령":"공인중개사법","조문":"제2조제2호","원문":"\"공인중개사\"라 함은 이 법에 의한 공인중개사자격을 취득한 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제3호","원문":"\"중개업\"이라 함은 다른 사람의 의뢰에 의하여 일정한 보수를 받고 중개를 업으로 행하는 것을 말한다."},{"법령":"공인중개사법","조문":"제2조제4호","원문":"\"개업공인중개사\"라 함은 이 법에 의하여 중개사무소의 개설등록을 한 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제5호","원문":"\"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제6호","원문":"\"중개보조원\"이라 함은 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개대상물에 대한 현장안내 및 일반서무 등 개업공인중개사의 중개업무와 관련된 단순한 업무를 보조하는 자를 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"중개는 거래 자체가 아니라 거래당사자 간의 교환·매매 등을 알선하는 것이다(제2조제1호). 당사자 간에 교환하는 행위는 중개가 아니다."},{"번호":2,"판정":"틀림","설명":"중개업은 일정한 보수를 받고 중개를 업으로 하는 것이다. 보수를 받지 않으면 중개업에 해당하지 않는다(제2조제3호)."},{"번호":3,"판정":"틀림","설명":"개업공인중개사는 중개사무소 개설등록을 한 자다. 법인의 임원인 공인중개사는 소속공인중개사에 해당한다(제2조제4호·제5호)."},{"번호":4,"판정":"틀림","설명":"공인중개사가 개업공인중개사에 소속되어 보조하면 소속공인중개사다. 중개보조원은 공인중개사가 아닌 자다(제2조제5호·제6호)."},{"번호":5,"판정":"옳음","설명":"공인중개사는 자격을 취득한 자이고 개설등록 여부와 무관하다(제2조제2호)."}],"개념":[{"종류":"표","제목":"중개업 관련 용어 정의","머리":["용어","정의의 핵심","조문"],"행":[["중개","중개대상물에 대한 매매·교환·임대차 등 권리 득실변경 행위의 알선","제2조제1호"],["공인중개사","공인중개사자격을 취득한 자(개설등록 여부 무관)","제2조제2호"],["중개업","다른 사람의 의뢰, 일정한 보수, 업으로 중개","제2조제3호"],["개업공인중개사","중개사무소 개설등록을 한 자(자격증 소지 여부는 요건이 아님)","제2조제4호"],["소속공인중개사","개업공인중개사 소속 공인중개사. 법인의 사원·임원인 공인중개사 포함. 중개업무 수행 또는 보조","제2조제5호"],["중개보조원","공인중개사 아닌 자로서 현장안내·일반서무 등 단순 업무 보조","제2조제6호"]]},{"종류":"비교","제목":"소속공인중개사와 중개보조원","왼쪽":{"이름":"소속공인중개사","항목":["공인중개사 자격 있음","중개업무 수행 또는 보조","법인 개업공인중개사의 사원·임원인 공인중개사 포함","확인·설명서에 중개행위를 한 경우 서명 및 날인(제25조제4항)"]},"오른쪽":{"이름":"중개보조원","항목":["공인중개사 자격 없음","현장안내·일반서무 등 단순 업무 보조","고용·고용관계 종료 시 개업공인중개사가 등록관청에 신고(제15조제1항)","고용 상한: 개업공인중개사와 소속공인중개사 합산 수의 5배(제15조제3항)"]}}],"함정":"③은 법인의 임원도 개업공인중개사라고 보기 쉽다. 법인의 사원·임원인 공인중개사는 소속공인중개사에 포함되고, 개업공인중개사는 등록을 한 법인 자체다. ④는 중개보조원이 공인중개사가 아닌 자라는 점을 놓치면 속는다."},"34회-2차-006":{"한줄":"동·호수가 특정되어 분양계약이 체결된 아파트와 입목법상 입목이 중개대상물이어서 ㄴ, ㄷ이 정답이다.","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"1. 토지 2. 건축물 그 밖의 토지의 정착물 3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법 시행령","조문":"제2조","원문":"1. 「입목에 관한 법률」에 따른 입목 2. 「공장 및 광업재단 저당법」에 따른 공장재단 및 광업재단"},{"판례":"대법원 판례(피담보채권·무형의 가치)","요지":"근저당권이 설정되어 있는 피담보채권은 금전채권이라 중개대상물이 아니다. 점포 위치에 따른 영업상의 이점 등 무형의 재산적 가치도 중개대상물이 아니다."},{"판례":"대법원 판례(분양계약이 체결된 아파트)","요지":"아직 완성되기 전이어도 동·호수가 특정되어 분양계약이 체결된 아파트는 중개대상물이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ, ㄹ은 모두 중개대상물이 아니다."},{"번호":2,"판정":"옳음","설명":"ㄴ, ㄷ이 중개대상물이다."},{"번호":3,"판정":"틀림","설명":"ㄹ(영업상의 이점)은 중개대상물이 아니고 ㄷ이 빠져 있다."},{"번호":4,"판정":"틀림","설명":"ㄱ(피담보채권)은 중개대상물이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄱ, ㄹ은 중개대상물이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"피담보채권은 금전채권이라 중개대상물이 아니다."},{"기호":"ㄴ","판정":"옳음","설명":"동·호수가 특정되어 분양계약이 체결된 아파트는 완성 전이어도 중개대상물이다."},{"기호":"ㄷ","판정":"옳음","설명":"입목에 관한 법률에 따른 입목은 시행령 제2조제1호의 중개대상물이다."},{"기호":"ㄹ","판정":"틀림","설명":"점포 위치에 따른 영업상의 이점은 무형의 재산적 가치로서 중개대상물이 아니다."}],"개념":[{"종류":"표","제목":"중개대상물 해당 여부 모음","머리":["대상","해당 여부","근거"],"행":[["토지(토지거래허가구역 토지, 가압류된 토지 포함)","해당","제3조제1호"],["건축물·정착물(미등기 건축물, 주벽을 갖춘 신축 중 건물)","해당","제3조제2호"],["입목법상 입목, 공장재단·광업재단","해당","시행령 제2조"],["동·호수가 특정되어 분양계약이 체결된 아파트 분양권","해당","판례"],["입주권(추첨 신청으로 분양예정자가 될 지위), 대토권","비해당","판례"],["영업시설·비품, 거래처·신용·점포 위치의 이점 등 무형의 가치","비해당","판례"],["금전채권(피담보채권 포함)","비해당","판례"]]}],"함정":"ㄱ은 근저당권이라는 권리가 눈에 띄어 포함시키기 쉽다. 대상은 근저당권이 담보하는 금전채권이고, 금전채권은 중개대상물이 아니다."},"34회-2차-020":{"한줄":"동일 당사자 사이에 매매를 포함한 거래가 동일 기회에 이루어지면 매매 거래금액 2억 5천만원만 적용하므로 상한은 2억 5천만원 × 0.4% = 100만원이고, 합의액 160만원 중 100만원까지만 받을 수 있다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제20조제5항제3호","원문":"동일한 중개대상물에 대하여 동일 당사자간에 매매를 포함한 둘 이상의 거래가 동일 기회에 이루어지는 경우에는 매매계약에 관한 거래금액만을 적용한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제20조제1항","원문":"법 제32조제4항에 따른 주택의 중개에 대한 보수는 중개의뢰인 쌍방으로부터 각각 받되, 그 일방으로부터 받을 수 있는 한도는 별표 1과 같으며, 그 금액은 법 제32조제4항에 따라 시ㆍ도의 조례로 정하는 요율한도 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."},{"법령":"공인중개사법","조문":"법 제33조제1항제3호","원문":"사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위"}],"선지":[{"번호":1,"판정":"-","설명":"100만원. 매매 거래금액 2억 5천만원 × 0.004 = 100만원이고 이 구간에는 한도액이 없다. 합의액 160만원이 이를 넘으므로 100만원이 최고한도액이다."},{"번호":2,"판정":"-","설명":"115만 5천원. 매매 100만원에 임대차 보수 15만 5천원을 더한 값이다. 임대차 환산액(1천만원 + 30만원 × 70 = 3천 100만원)의 0.5%가 15만 5천원이다. 동일 기회의 매매·임대차는 매매 거래금액만 적용하므로 임대차분을 더하지 않는다."},{"번호":3,"판정":"-","설명":"120만원. 매매 100만원에 임대차 한도액 20만원을 더한 값이다. 임대차분은 따로 받을 수 없다(시행규칙 제20조제5항제3호)."},{"번호":4,"판정":"-","설명":"160만원. 합의된 보수를 그대로 받는 값이다. 합의액이 상한을 넘으면 넘는 부분은 받을 수 없다(법 제33조제1항제3호)."},{"번호":5,"판정":"-","설명":"175만 5천원. 합의액 160만원에 임대차분 15만 5천원을 더한 값이다. 상한을 넘고 임대차분까지 합산한 이중 오류다."}],"개념":[{"종류":"계산","제목":"매매·임대차 동시 중개 시 중개보수 상한","단계":[{"설명":"거래금액 결정: 동일 당사자(甲)·동일 기회에 매매와 임대차를 중개했으므로 매매계약 거래금액만 적용","식":"거래금액 = 매매대금","값":"2억 5천만원"},{"설명":"상한요율 확인: 조례 기준 매매 2억원 이상 9억원 미만 구간(한도액 없음)","식":"상한요율 = 0.4%","값":"0.004"},{"설명":"상한액 계산","식":"250,000,000 × 0.004","값":"1,000,000원"},{"설명":"합의액과 비교: 합의 160만원 > 상한 100만원이므로 상한까지만 수령","식":"min(1,600,000 ; 1,000,000)","값":"100만원"}]},{"종류":"표","제목":"거래금액 계산 규칙","머리":["경우","거래금액","조문"],"행":[["임대차에 월 차임이 있는 경우","보증금 + 월 차임 × 100","시행규칙 제20조제5항제1호"],["위 합산액이 5천만원 미만인 경우","보증금 + 월 차임 × 70","시행규칙 제20조제5항제1호 단서"],["교환계약","교환 대상 중 거래금액이 큰 쪽의 가액","시행규칙 제20조제5항제2호"],["동일 당사자·동일 기회에 매매를 포함한 둘 이상의 거래","매매계약 거래금액만 적용","시행규칙 제20조제5항제3호"]]}],"함정":"매매와 임대차를 따로 계산해 더하는 ②, ③, ⑤가 가장 흔한 오답이다. 같은 사람과 같은 기회에 이루어진 매매·임대차는 매매 거래금액만 적용한다. 합의액이 높다고 그대로 받을 수 있는 것도 아니다(④)."},"34회-2차-022":{"한줄":"소속공인중개사의 자격정지 기준 중 6개월은 둘 이상의 중개사무소에 소속된 경우(ㄱ)뿐이고, 거래계약서 서명·날인 누락(ㄴ), 미등록 인장 사용(ㄷ), 확인·설명 근거자료 미제시(ㄹ)는 3개월이다.","근거":[{"법령":"공인중개사법","조문":"법 제36조제1항제1호","원문":"제12조제2항의 규정을 위반하여 둘 이상의 중개사무소에 소속된 경우"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별표 3 제1호","원문":"법 제12조제2항을 위반하여 2 이상의 중개사무소에 소속된 경우: 자격정지 6월"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별표 3 제2호","원문":"법 제16조를 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우: 자격정지 3월"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별표 3 제3호","원문":"법 제25조제1항을 위반하여 성실·정확하게 확인·설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 경우: 자격정지 3월"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별표 3 제5호","원문":"법 제26조제2항을 위반하여 거래계약서에 서명·날인을 하지 아니한 경우: 자격정지 3월"}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 6개월 기준이다. ㄴ, ㄷ, ㄹ은 3개월이다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 3개월 기준이라 ㄱ, ㄷ 조합은 맞지 않는다."},{"번호":3,"판정":"틀림","설명":"ㄴ, ㄷ은 모두 3개월 기준이라 이 조합은 맞지 않는다."},{"번호":4,"판정":"틀림","설명":"ㄴ, ㄹ은 3개월 기준이라 이 조합은 맞지 않는다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ, ㄹ은 모두 3개월 기준이라 이 조합은 맞지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"둘 이상의 중개사무소에 소속된 경우의 자격정지 기준은 6개월이다(시행규칙 별표 3 제1호)."},{"기호":"ㄴ","판정":"틀림","설명":"거래계약서에 서명·날인을 하지 않은 경우는 3개월이다(시행규칙 별표 3 제5호)."},{"기호":"ㄷ","판정":"틀림","설명":"등록하지 않은 인장을 사용한 경우는 3개월이다(시행규칙 별표 3 제2호)."},{"기호":"ㄹ","판정":"틀림","설명":"확인·설명의 근거자료를 제시하지 않은 경우는 3개월이다(시행규칙 별표 3 제3호)."}],"개념":[{"종류":"표","제목":"소속공인중개사 자격정지 사유와 기준(법 제36조제1항, 시행규칙 별표 3)","머리":["호","사유","자격정지 기준"],"행":[["1","둘 이상의 중개사무소에 소속된 경우","6개월"],["2","인장등록을 하지 않거나 등록하지 않은 인장을 사용한 경우","3개월"],["3","중개대상물의 확인·설명을 성실·정확하게 하지 않거나 설명의 근거자료를 제시하지 않은 경우","3개월"],["4","중개대상물확인·설명서에 서명 및 날인을 하지 않은 경우","3개월"],["5","거래계약서에 서명 및 날인을 하지 않은 경우","3개월"],["6","거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우","6개월"],["7","제33조제1항 각 호의 금지행위를 한 경우","6개월"]]},{"종류":"표","제목":"자격정지 기간의 조정(시행규칙 제22조제2항)","머리":["구분","내용"],"행":[["가중·감경 범위","위반행위의 동기·결과·횟수 등을 참작하여 자격정지기간의 2분의 1 범위에서 가중 또는 감경"],["가중 상한","가중하여 처분하는 때에도 자격정지기간은 6월을 초과할 수 없음"],["처분권자","시·도지사(법 제36조제1항)"]]}],"함정":"정지 6개월은 둘 이상의 중개사무소 소속(제1호), 거래내용 거짓 기재·이중 계약서(제6호), 금지행위(제7호) 세 가지다. 서명·날인, 인장, 확인·설명은 모두 3개월이다. 거래계약서에 서명·날인하지 않은 경우를 거래계약서 관련이라는 이유로 6개월로 기억하기 쉽다."},"34회-2차-023":{"한줄":"2022. 4. 1. 과태료 처분 후 폐업하고 2023. 3. 2. 재등록하면 처분일부터 11개월로 1년 이내라 처분의 효과가 승계되므로 ⑤가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제40조제1항","원문":"개업공인중개사가 제21조에 따른 폐업신고후 제9조에 따라 다시 중개사무소의 개설등록을 한 때에는 폐업신고 전의 개업공인중개사의 지위를 승계한다."},{"법령":"공인중개사법","조문":"법 제40조제2항","원문":"제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다."},{"법령":"공인중개사법","조문":"법 제40조제3항제2호","원문":"폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"},{"법령":"공인중개사법","조문":"법 제40조제4항","원문":"제3항에 따라 행정처분을 하는 경우에는 폐업기간과 폐업의 사유 등을 고려하여야 한다."},{"법령":"공인중개사법","조문":"법 제39조제1항제4호","원문":"제24조제7항의 규정을 위반하여 중개대상물에 관한 정보를 거짓으로 공개하거나 거래정보사업자에게 공개를 의뢰한 중개대상물의 거래가 완성된 사실을 해당 거래정보사업자에게 통보하지 아니한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"지위 승계는 폐업신고를 한 개업공인중개사가 다시 개설등록을 한 때에 생긴다(법 제40조제1항). 다른 개업공인중개사가 같은 사무소에 새로 등록하는 경우에는 승계가 없다."},{"번호":2,"판정":"틀림","설명":"정보 거짓 공개로 인한 업무정지처분의 효과는 처분일부터 1년간 승계된다(법 제40조제2항). 불복기간이 지난 날부터 계산하지 않는다."},{"번호":3,"판정":"틀림","설명":"업무정지에 해당하는 위반행위는 폐업기간이 1년을 초과해야 처분할 수 없다(법 제40조제3항제2호). 폐업기간 6개월이면 처분할 수 있다."},{"번호":4,"판정":"틀림","설명":"재등록 개업공인중개사에게 처분할 때는 폐업기간과 폐업의 사유 등을 고려해야 한다(법 제40조제4항)."},{"번호":5,"판정":"옳음","설명":"2022. 4. 1.부터 2023. 3. 2.까지는 11개월 남짓으로 처분일부터 1년 안이다. 과태료부과처분의 효과가 승계된다(법 제40조제2항)."}],"개념":[{"종류":"표","제목":"행정제재처분효과의 승계(법 제40조)","머리":["구분","내용"],"행":[["지위 승계","폐업신고 후 다시 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계(동일인 재등록의 경우)"],["처분 효과의 승계","폐업신고 전 업무정지·과태료 처분의 효과는 그 처분일부터 1년간 재등록 개업공인중개사에게 승계"],["위반행위에 대한 처분","재등록 개업공인중개사에게 폐업신고 전의 등록취소·업무정지 사유 위반행위로 처분 가능"],["처분 불가 1","폐업기간(폐업신고일~재등록일)이 3년을 초과한 경우"],["처분 불가 2","폐업신고 전 위반행위에 대한 처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우"],["처분 시 고려","폐업기간과 폐업의 사유 등을 고려"],["법인","법인의 대표자에 관하여 준용(개업공인중개사는 법인의 대표자로 봄)"]]},{"종류":"계산","제목":"승계 기간 판단(⑤)","단계":[{"설명":"처분일부터 재등록일까지 기간","식":"2022.4.1 ~ 2023.3.2","값":"11개월 1일"},{"설명":"승계 기준: 처분일부터 1년","식":"11개월 1일 ≤ 1년","값":"승계됨"}]}],"함정":"②는 1년이라는 숫자는 맞지만 기산점을 불복기간이 지난 날로 바꿨다. 기산점은 처분일이다. ③은 업무정지 사유는 폐업기간 1년 초과가 한계인데 6개월이라도 처분할 수 없다고 바꿔 놓았다."},"34회-2차-002":{"한줄":"위원은 위원장이 아니라 국토교통부장관이 임명하거나 위촉하므로 ①이 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제1조의2제2항","원문":"심의위원회 위원장은 국토교통부 제1차관이 되고, 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 국토교통부장관이 임명하거나 위촉한다."},{"법령":"공인중개사법","조문":"법 제2조의2제1항제3호","원문":"공인중개사의 업무에 관한 다음 각 호의 사항을 심의하기 위하여 국토교통부에 공인중개사 정책심의위원회를 둘 수 있다. 중개보수 변경에 관한 사항"},{"법령":"공인중개사법","조문":"법 제2조의2제3항","원문":"제1항에 따라 공인중개사 정책심의위원회에서 심의한 사항 중 제1호의 경우에는 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 이에 따라야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의2제1항","원문":"「공인중개사법」(이하 \"법\"이라 한다) 제2조의2제1항에 따른 공인중개사 정책심의위원회(이하 \"심의위원회\"라 한다)는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의3제1항제4호","원문":"심의위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 심의위원회의 심의ㆍ의결에서 제척(除斥)된다. 위원이나 위원이 속한 법인ㆍ단체 등이 해당 안건의 당사자의 대리인이거나 대리인이었던 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"위원장은 국토교통부 제1차관이 되고, 위원은 국토교통부장관이 임명하거나 위촉한다(영 제1조의2제2항)."},{"번호":2,"판정":"옳음","설명":"중개보수 변경에 관한 사항이 심의사항에 들어 있다(법 제2조의2제1항제3호)."},{"번호":3,"판정":"옳음","설명":"심의사항 중 자격취득에 관한 사항(제1호)은 시·도지사가 그대로 따라야 한다(법 제2조의2제3항)."},{"번호":4,"판정":"옳음","설명":"위원장 1명을 포함해 7명 이상 11명 이내로 구성한다(영 제1조의2제1항)."},{"번호":5,"판정":"옳음","설명":"위원이 속한 법인·단체가 안건 당사자의 대리인이었던 경우도 제척 사유다(영 제1조의3제1항제4호)."}],"개념":[{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","근거"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","자격취득(시험 등), 중개업 육성, 중개보수 변경, 손해배상책임 보장","법 제2조의2제1항제1호~제4호"],["시·도지사 구속","심의사항 중 자격취득에 관한 사항(제1호)은 시·도지사가 이에 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장·위원","위원장은 국토교통부 제1차관, 위원은 국토교통부장관이 임명 또는 위촉","영 제1조의2제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"],["소집 통보","개최 7일 전까지(긴급하면 개최 전날까지)","영 제1조의5제3항"]]},{"종류":"표","제목":"위원의 제척·기피·회피(영 제1조의3)","머리":["구분","내용"],"행":[["제척 제1호","위원 또는 그 배우자(이었던 사람)가 안건의 당사자이거나 당사자와 공동권리자·공동의무자인 경우(당사자가 법인·단체면 임원 포함)"],["제척 제2호","위원이 안건 당사자와 친족이거나 친족이었던 경우"],["제척 제3호","위원이 안건에 대해 증언, 진술, 자문, 조사, 연구, 용역 또는 감정을 한 경우"],["제척 제4호","위원이나 위원이 속한 법인·단체 등이 당사자의 대리인이거나 대리인이었던 경우"],["기피","당사자가 신청하고 심의위원회가 의결로 결정. 기피 대상 위원은 그 의결에 참여하지 못함"],["회피","위원 본인이 제척 사유에 해당하면 스스로 회피. 회피하지 않으면 국토교통부장관이 해촉할 수 있음"]]}],"함정":"위원을 임명·위촉하는 사람은 국토교통부장관이다. 위원장은 국토교통부 제1차관이 맡는 자리로 정해져 있어 임명 대상이 아니다. 심의사항 중 시·도지사를 구속하는 것은 자격취득에 관한 제1호뿐이고, 인원은 7명 이상 11명 이내다."},"34회-2차-004":{"한줄":"분사무소는 법인인 개업공인중개사만 둘 수 있으므로 법인이 아닌 개업공인중개사의 분사무소 설치를 전제로 한 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제13조제1항","원문":"개업공인중개사는 그 등록관청의 관할 구역안에 중개사무소를 두되, 1개의 중개사무소만을 둘 수 있다."},{"법령":"공인중개사법","조문":"법 제13조제2항","원문":"개업공인중개사는 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치하여서는 아니된다."},{"법령":"공인중개사법 시행령","조문":"영 제15조제1항","원문":"법 제13조제3항에 따른 분사무소는 주된 사무소의 소재지가 속한 시(구가 설치되지 아니한 시와 특별자치도의 행정시를 말한다. 이하 이 조에서 같다)ㆍ군ㆍ구를 제외한 시ㆍ군ㆍ구별로 설치하되, 시ㆍ군ㆍ구별로 1개소를 초과할 수 없다."},{"법령":"공인중개사법","조문":"법 제13조제3항","원문":"제1항에도 불구하고 법인인 개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다."},{"법령":"공인중개사법","조문":"법 제13조제4항","원문":"제3항에 따라 분사무소 설치신고를 받은 등록관청은 그 신고내용이 적합한 경우에는 국토교통부령으로 정하는 신고확인서를 교부하고 지체 없이 그 분사무소설치예정지역을 관할하는 시장ㆍ군수 또는 구청장에게 이를 통보하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"등록관청의 관할 구역 안에 1개의 중개사무소만 둔다(법 제13조제1항)."},{"번호":2,"판정":"옳음","설명":"이동이 용이한 임시 중개시설물은 설치할 수 없다(법 제13조제2항)."},{"번호":3,"판정":"옳음","설명":"분사무소는 주된 사무소의 소재지가 속한 시·군·구를 제외하고 설치하므로 같은 군에는 둘 수 없다(영 제15조제1항)."},{"번호":4,"판정":"틀림","설명":"분사무소는 법인인 개업공인중개사만 신고하고 설치할 수 있다. 법인이 아닌 개업공인중개사는 분사무소를 둘 수 없다(법 제13조제3항)."},{"번호":5,"판정":"옳음","설명":"신고 내용이 적합하면 등록관청은 신고확인서를 교부한다(법 제13조제4항)."}],"개념":[{"종류":"표","제목":"중개사무소의 설치(법 제13조)","머리":["항목","내용","위반 시"],"행":[["개수","등록관청 관할구역 안에 1개만","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제4호), 등록취소 가능"],["임시 시설물","천막 등 이동이 용이한 임시 중개시설물 설치 금지","제49조제1항제5호, 등록취소 가능(제38조제2항제3호)"],["분사무소","법인인 개업공인중개사만 신고하고 관할 구역 밖에 설치","-"],["공동 사용","다른 개업공인중개사와 공동 사용 가능. 업무정지기간 중 일정한 경우 제한","-"],["중개 지역","사무소를 두는 지역만 정하고 중개대상물의 소재지는 제한하지 않음","-"]]},{"종류":"표","제목":"분사무소 설치(법 제13조제3항, 영 제15조)","머리":["항목","내용","근거"],"행":[["설치 주체","법인인 개업공인중개사","법 제13조제3항"],["설치 지역","주된 사무소 소재지가 속한 시·군·구를 제외한 시·군·구, 시·군·구별 1개소","영 제15조제1항"],["책임자","공인중개사. 다른 법률에 따라 중개업을 하는 법인의 분사무소는 예외","영 제15조제2항"],["신고처","주된 사무소 소재지 관할 등록관청","영 제15조제3항"],["첨부서류","책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류","영 제15조제3항제3호~제5호"],["신고확인서","적합하면 신고확인서를 교부하고 설치예정지역 관할 시장·군수·구청장에게 통보","법 제13조제4항"],["보증","분사무소마다 2억원 이상 추가 설정","영 제24조제1항제1호"]]}],"함정":"분사무소를 둘 수 있는 사람은 법인이다. 신고 절차나 신고확인서 교부가 있다고 해서 법인이 아닌 개업공인중개사에게 설치 자격이 생기지는 않는다."},"34회-2차-009":{"한줄":"분사무소 폐업신고에는 분사무소설치신고확인서를 첨부하고(ㄱ), 임신은 6개월 초과 휴업 사유이며(ㄴ), 업무정지 후 폐업해도 정지기간이 지나기 전에는 결격이다(ㄷ 틀림).","근거":[{"법령":"공인중개사법 시행령","조문":"영 제18조제2항","원문":"법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다. 이 경우 법 제13조제4항에 따른 신고확인서를 첨부(제1항제1호 및 제2호의 경우만 해당한다)해야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제18조제6항제4호","원문":"법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. 임신 또는 출산"},{"법령":"공인중개사법","조문":"법 제10조제1항제9호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제39조에 따라 업무정지처분을 받고 제21조에 따른 폐업신고를 한 자로서 업무정지기간(폐업에도 불구하고 진행되는 것으로 본다)이 지나지 아니한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ도 옳은 보기라서 ㄴ만으로는 모자란다."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄴ이 옳다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 옳지 않다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 옳지 않고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 옳지 않다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"분사무소별 휴업·폐업 신고에는 분사무소설치신고확인서를 첨부한다(영 제18조제2항)."},{"기호":"ㄴ","판정":"옳음","설명":"임신 또는 출산은 6개월을 초과하여 휴업할 수 있는 사유다(영 제18조제6항제4호)."},{"기호":"ㄷ","판정":"틀림","설명":"업무정지처분을 받고 폐업신고를 한 자는 업무정지기간이 지나기 전까지 개설등록을 할 수 없다(법 제10조제1항제9호)."}],"개념":[{"종류":"표","제목":"휴업·폐업·재개 신고(법 제21조, 영 제18조)","머리":["항목","내용"],"행":[["신고 대상","3개월 초과 휴업(개설등록 후 업무 미개시 포함), 폐업, 3개월 초과 휴업한 중개업 재개, 휴업기간 변경"],["신고 방법","등록관청에 미리 신고. 휴업·폐업은 등록증 첨부, 재개·변경은 전자문서 신고 가능"],["휴업 기간","6개월 초과 불가"],["예외 사유","질병으로 인한 요양, 징집으로 인한 입영, 취학, 임신 또는 출산, 이에 준하는 고시 사유"],["분사무소","법인은 분사무소별로 신고 가능(신고확인서 첨부)"],["위반","신고하지 않으면 100만원 이하 과태료(법 제51조제3항제4호), 6개월 초과 휴업은 등록취소 가능(법 제38조제2항제5호)"]]},{"종류":"표","제목":"폐업·휴업과 관련한 법적 효과","머리":["항목","내용","근거"],"행":[["교육 면제","폐업신고 후 1년 이내 소속공인중개사로 고용신고되면 실무교육 면제","법 제34조제2항제2호"],["공탁금","폐업 또는 사망한 날부터 3년 이내에는 회수 불가","법 제30조제4항"],["간판","폐업신고 후 지체 없이 철거","법 제21조의2제1항제2호"],["결격","업무정지처분을 받고 폐업신고를 한 자는 업무정지기간(폐업에도 진행)이 지나기 전까지 결격","법 제10조제1항제9호"],["분사무소","분사무소는 주된 사무소와 별도로 휴업·폐업 신고 가능","영 제18조제2항"],["수수료","폐업신고는 수수료 납부 대상으로 열거되지 않음","법 제47조제1항"]]}],"함정":"업무정지기간은 폐업에도 불구하고 진행되는 것으로 보지만, 그 기간이 지나기 전까지는 결격이다. 폐업으로 처분을 피할 수 없다."}};